-- Step 1: Normalize Case 141 if old test upload exists at id=2

UPDATE ecg_cases
SET image_url = '/uploads/ecg/case_141.png',
    diagnosis_id = (SELECT id FROM ecg_diagnoses WHERE code = 'LQTS' LIMIT 1),
    difficulty = 'advanced',
    findings_json = '{"history":"This ECG was recorded from a 15-year-old boy who collapsed while playing football. His brother had died suddenly. What does the ECG show and what clinical possibilities should be considered?","ecg_shows":"•\tSinus rhythm, rate 91/min •\tNormal PR interval •\tNormal axis •\tNormal QRS complexes •\tProlonged QT interval (QT = 492 ms; QTc = 598 ms) •\tInverted T waves in leads V2–V5","clinical_interpretation":"This is clearly a very abnormal ECG, with a markedly prolonged QT interval and  abnormal T waves.","what_to_do":"The family history suggests that this may well be an example of one of the congenital  forms of prolonged QT interval: the Jervell–Lange–Nielson syndrome or the  Romano–Ward syndrome. These are characterized by episodes of loss of conscious­ ness in children, often at times of increased sympathetic nervous system activity,  and beta-blockers are the immediate form of treatment. The insertion of a perma­ nent defibrillator may be necessary. Prolonged QT interval syndrome is also associ­ ated with antiarrhythmic drugs (quinidine, procainamide, disopyramide, amiodarone  and sotalol) and with other drugs such as the tricyclic antidepressants and erythro­ mycin. Electrolyte abnormalities (low potassium, magnesium or calcium levels) also  prolong the QT interval.","summary":"Marked prolongation of the QT interval – long QT syndrome.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":91,"min":85,"max":95},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The family history suggests that this may well be an example of one of the congenital  forms of prolonged QT interval: the Jervell–Lange–Nielson syndrome or the  Romano–Ward syndrome. These are characterized by episodes of loss of conscious­ ness in children, often at times of increased sympathetic nervous system activity,  and beta-blockers are the immediate form of treatment. The insertion of a perma­ nent defibrillator may be necessary. Prolonged QT interval syndrome is also associ­ ated with antiarrhythmic drugs (quinidine, procainamide, disopyramide, amiodarone  and sotalol) and with other drugs such as the tricyclic antidepressants and erythro­ mycin. Electrolyte abnormalities (low potassium, magnesium or calcium levels) also  prolong the QT interval."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb
WHERE id = 2 AND image_url LIKE '%1769929257584%';

INSERT INTO ecg_cases (diagnosis_id, image_url, difficulty, findings_json, secondary_diagnoses_ids)
SELECT id, '/uploads/ecg/case_141.png', 'advanced', '{"history":"This ECG was recorded from a 15-year-old boy who collapsed while playing football. His brother had died suddenly. What does the ECG show and what clinical possibilities should be considered?","ecg_shows":"•\tSinus rhythm, rate 91/min •\tNormal PR interval •\tNormal axis •\tNormal QRS complexes •\tProlonged QT interval (QT = 492 ms; QTc = 598 ms) •\tInverted T waves in leads V2–V5","clinical_interpretation":"This is clearly a very abnormal ECG, with a markedly prolonged QT interval and  abnormal T waves.","what_to_do":"The family history suggests that this may well be an example of one of the congenital  forms of prolonged QT interval: the Jervell–Lange–Nielson syndrome or the  Romano–Ward syndrome. These are characterized by episodes of loss of conscious­ ness in children, often at times of increased sympathetic nervous system activity,  and beta-blockers are the immediate form of treatment. The insertion of a perma­ nent defibrillator may be necessary. Prolonged QT interval syndrome is also associ­ ated with antiarrhythmic drugs (quinidine, procainamide, disopyramide, amiodarone  and sotalol) and with other drugs such as the tricyclic antidepressants and erythro­ mycin. Electrolyte abnormalities (low potassium, magnesium or calcium levels) also  prolong the QT interval.","summary":"Marked prolongation of the QT interval – long QT syndrome.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":91,"min":85,"max":95},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The family history suggests that this may well be an example of one of the congenital  forms of prolonged QT interval: the Jervell–Lange–Nielson syndrome or the  Romano–Ward syndrome. These are characterized by episodes of loss of conscious­ ness in children, often at times of increased sympathetic nervous system activity,  and beta-blockers are the immediate form of treatment. The insertion of a perma­ nent defibrillator may be necessary. Prolonged QT interval syndrome is also associ­ ated with antiarrhythmic drugs (quinidine, procainamide, disopyramide, amiodarone  and sotalol) and with other drugs such as the tricyclic antidepressants and erythro­ mycin. Electrolyte abnormalities (low potassium, magnesium or calcium levels) also  prolong the QT interval."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb, '{}'::integer[]
FROM ecg_diagnoses WHERE code = 'LQTS'
WHERE NOT EXISTS (SELECT 1 FROM ecg_cases WHERE image_url LIKE '%case_141.png%');

-- Step 2: Canonical findings update for all 150 ECG cases
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 20-year-old student who complained of an irregular heartbeat. Apart from an irregular pulse, her heart was clinically normal. What do the ECG and chest X-ray show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 100/min •\tVentricular extrasystoles •\tNormal axis •\tNormal QRS complexes and T waves","clinical_interpretation":"The extrasystoles are fairly frequent but the ECG is otherwise normal.","what_to_do":"Ventricular extrasystoles are very common. In large groups of people, there is a  correlation between the presence of extrasystoles and heart disease of many types.  However, in young people who are otherwise asymptomatic and whose hearts are  otherwise normal, the chances of a significant cardiac problem are very low. In a young woman it is worth checking the haemoglobin level. An echocardio­ gram might set her mind at rest, but is not essential. The important thing is to advise  her not to smoke and to avoid alcohol, coffee and tea.","summary":"Sinus rhythm with ventricular extrasystoles.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":100,"min":95,"max":105},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Ventricular extrasystoles are very common. In large groups of people, there is a  correlation between the presence of extrasystoles and heart disease of many types.  However, in young people who are otherwise asymptomatic and whose hearts are  otherwise normal, the chances of a significant cardiac problem are very low. In a young woman it is worth checking the haemoglobin level. An echocardio­ gram might set her mind at rest, but is not essential. The important thing is to advise  her not to smoke and to avoid alcohol, coffee and tea."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_001.png' OR image_url LIKE '%case_1.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man was seen as an outpatient, complaining of rather vague central chest pain on exertion. He had never had pain at rest. What does this ECG show and what would you do next?","ecg_shows":"•\tSinus rhythm, rate 77/min •\tNormal PR interval •\tNormal axis •\tProminent and deep Q waves in leads II, III and VF, indicating an inferior  infarction. There are also small Q waves in leads V5–V6, but these may be septal •\tST segments normal, with no elevation in the leads showing Q waves •\tInverted T waves in leads II, III and VF","clinical_interpretation":"The Q waves in the inferior leads, together with inverted T waves, point to an old  inferior myocardial infarction.","what_to_do":"The patient seems to have had a myocardial infarction at some point in the past,  and by implication his vague chest pain may be due to angina. Attention must be  paid to risk factors (smoking, blood pressure, plasma cholesterol), and he probably  needs long-term treatment with aspirin and a statin. An exercise test or a perfusion  scan will be the best way of deciding whether he has coronary disease that merits  angiography.","summary":"Old inferior myocardial infarction.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":77,"min":72,"max":82},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"The patient seems to have had a myocardial infarction at some point in the past,  and by implication his vague chest pain may be due to angina. Attention must be  paid to risk factors (smoking, blood pressure, plasma cholesterol), and he probably  needs long-term treatment with aspirin and a statin. An exercise test or a perfusion  scan will be the best way of deciding whether he has coronary disease that merits  angiography."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_002.png' OR image_url LIKE '%case_2.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 80-year-old woman, who had previously had a few attacks of dizziness, fell and broke her hip. She was found to have a slow pulse, and this is her ECG. The surgeons want to operate as soon as possible but the anaesthetist is unhappy. What does the ECG show and what should be done?","ecg_shows":"•\tP wave rate 130/min •\tComplete heart block •\tVentricular (QRS complex) rate 23/min •\tThe ventricular ‘escape’ rhythm has wide QRS complexes and abnormal T  waves No further interpretation of the ECG is possible.","clinical_interpretation":"In complete heart block there is no relationship between the P waves (here with  a rate of 120/min) and the QRS complexes.","what_to_do":"In the absence of a history suggesting a myocardial infarction, this woman almost  certainly has chronic heart block: the fall may or may not have been due to a  Stokes–Adams attack. She needs a permanent pacemaker, ideally immediately. If  permanent pacing is not possible immediately, a temporary pacemaker will be  needed preoperatively.","summary":"Complete (third degree) heart block.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":23,"min":20,"max":28},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"3rd Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"IVCD","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"In the absence of a history suggesting a myocardial infarction, this woman almost  certainly has chronic heart block: the fall may or may not have been due to a  Stokes–Adams attack. She needs a permanent pacemaker, ideally immediately. If  permanent pacing is not possible immediately, a temporary pacemaker will be  needed preoperatively."},"qrs_morph":{"hypertrophy":"None","bbb":"IVCD","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_003.png' OR image_url LIKE '%case_3.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man is seen in the A & E department with severe central chest pain which has been present for 18 h. What does this ECG show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 64/min •\tNormal axis •\tQ waves in leads V2–V4 •\tRaised ST segments in leads V2–V4 •\tInverted T waves in leads I, VL, V2–V6","clinical_interpretation":"This is a classic acute ST segment elevation anterior myocardial infarction (STEMI).","what_to_do":"More than 18 h have elapsed since the onset of pain, so this patient is outside the  conventional limit for thrombolysis or percutaneous coronary intervention (PCI).  Nevertheless, if he is still in pain and still looks unwell, PCI or thrombolytic treat­ ment should be given unless there are good reasons not to do so. In any case, he  should be given pain relief and aspirin, and must be admitted to hospital for  observation.","summary":"Acute anterior STEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":64,"min":60,"max":70},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"More than 18 h have elapsed since the onset of pain, so this patient is outside the  conventional limit for thrombolysis or percutaneous coronary intervention (PCI).  Nevertheless, if he is still in pain and still looks unwell, PCI or thrombolytic treat­ ment should be given unless there are good reasons not to do so. In any case, he  should be given pain relief and aspirin, and must be admitted to hospital for  observation."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_004.png' OR image_url LIKE '%case_4.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 60-year-old woman with rheumatic heart disease. She had been in heart failure, but this had been treated and she was no longer breathless. What does the ECG show and what question might you ask her?","ecg_shows":"•\tAtrial fibrillation with a ventricular rate of about 80/min •\tNormal axis •\tNormal QRS complexes •\tDownward-sloping ST segments, best seen in leads V5–V6 •\tProminent U waves in leads V2–V3","clinical_interpretation":"The downward-sloping ST segments (the ‘reverse tick’) indicate that digoxin has  been given. The ventricular rate seems well controlled. The prominent U waves in  leads V2–V3 are probably normal: U waves due to hypokalaemia are associated with  flattened T waves.","what_to_do":"Ask the patient about her appetite: the earliest symptom of digoxin toxicity is  appetite loss, followed by nausea and vomiting. If the patient is being treated with  diuretics, check the serum potassium level – a low potassium level potentiates the  effects of digoxin. If in doubt, the serum digoxin level is easily measured.","summary":"Atrial fibrillation with digoxin effect.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":80,"min":70,"max":90},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Ask the patient about her appetite: the earliest symptom of digoxin toxicity is  appetite loss, followed by nausea and vomiting. If the patient is being treated with  diuretics, check the serum potassium level – a low potassium level potentiates the  effects of digoxin. If in doubt, the serum digoxin level is easily measured."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_005.png' OR image_url LIKE '%case_5.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 26-year-old woman, who has complained of palpitations in the past, is admitted to hospital via the A & E department with palpitations. What does the ECG show and what should you do?","ecg_shows":"•\tNarrow complex tachycardia, rate about 200/min •\tNo P waves visible •\tNormal axis •\tRegular QRS complexes •\tNormal QRS complexes, ST segments and T waves","clinical_interpretation":"This is a supraventricular tachycardia, and since no P waves are visible this is a  junctional, or atrioventricular nodal re-entry, tachycardia (AVNRT).","what_to_do":"AVNRT is the commonest form of paroxysmal tachycardia in young people, and  presumably explains her previous episodes of palpitations. Attacks of AVNRT may  be terminated by any of the manoeuvres that lead to vagal stimulation – Valsalva’s  manoeuvre, carotid sinus pressure, or immersion of the face in cold water. If these  are unsuccessful, intravenous adenosine should be given by bolus injection. Adenos­ ine has a very short half-life, but can cause flushing and occasionally an asthmatic  attack. If adenosine proves unsuccessful, verapamil 5–10 mg given by bolus injec­ tion will usually restore sinus rhythm. Otherwise, DC cardioversion is indicated.","summary":"Atrioventricular nodal re-entry (junctional) tachycardia (AVNRT).","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":200,"min":190,"max":210},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"AVNRT is the commonest form of paroxysmal tachycardia in young people, and  presumably explains her previous episodes of palpitations. Attacks of AVNRT may  be terminated by any of the manoeuvres that lead to vagal stimulation – Valsalva’s  manoeuvre, carotid sinus pressure, or immersion of the face in cold water. If these  are unsuccessful, intravenous adenosine should be given by bolus injection. Adenos­ ine has a very short half-life, but can cause flushing and occasionally an asthmatic  attack. If adenosine proves unsuccessful, verapamil 5–10 mg given by bolus injec­ tion will usually restore sinus rhythm. Otherwise, DC cardioversion is indicated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_006.png' OR image_url LIKE '%case_6.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded in the A & E department from a 55-year-old man who had had chest pain at rest for 6 h. There were no abnormal physical findings, and his plasma troponin level was normal. What does the trace show, and how would you manage him?","ecg_shows":"•\tSinus rhythm, rate 130/min •\tNormal axis •\tNormal QRS complexes •\tST segment depression – slightly upward-sloping in lead V3, downward-sloping  in leads I, VL, V4–V6","clinical_interpretation":"This ECG shows anterior and lateral ischaemia without evidence of infarction.  Taken with the clinical history, the diagnosis is clearly ‘unstable’ angina.","what_to_do":"There is no evidence that he would benefit from thrombolysis: percutaneous coro­ nary intervention (PCI) would probably be the treatment of choice. Immediately,  however, he needs a beta-blocker to bring his heart rate down. Although the normal  troponin level suggests that he has not (yet) had a myocardial infarction, in view  of the length of the history it would be prudent to treat him with aspirin, heparin  and a statin.","summary":"Anterolateral ischaemia.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":130,"min":120,"max":140},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"There is no evidence that he would benefit from thrombolysis: percutaneous coro­ nary intervention (PCI) would probably be the treatment of choice. Immediately,  however, he needs a beta-blocker to bring his heart rate down. Although the normal  troponin level suggests that he has not (yet) had a myocardial infarction, in view  of the length of the history it would be prudent to treat him with aspirin, heparin  and a statin."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_007.png' OR image_url LIKE '%case_7.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 80-year-old woman complained of breathlessness and frequent attacks of dizziness. This was her ECG when she attended the clinic. She lived alone, and it seemed unlikely that she could cope with an ambulatory recorder. What does the ECG show, what might the dizziness be due to, and how would you manage her?","ecg_shows":"•\tSinus rhythm, rate 90/min •\tRight axis deviation •\tRight bundle branch block (RBBB)","clinical_interpretation":"The right axis deviation suggests left posterior hemiblock, and, combined with  RBBB, this suggests bifascicular block. The patient is therefore at risk of complete  (third degree) block, which could cause a Stokes–Adams attack.","what_to_do":"This woman was admitted to hospital and monitored, and had a severe attack of  dizziness and fainting. During this attack, another ECG was recorded (see below).  This ECG shows complete heart block with a ventricular rate of about 15/min. The  patient was immediately given a permanent pacemaker.","summary":"Left posterior hemiblock and RBBB – bifascicular block, followed by complete  heart block (see ECG below).","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":90,"min":85,"max":95},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"This woman was admitted to hospital and monitored, and had a severe attack of  dizziness and fainting. During this attack, another ECG was recorded (see below).  This ECG shows complete heart block with a ventricular rate of about 15/min. The  patient was immediately given a permanent pacemaker."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_008.png' OR image_url LIKE '%case_8.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 40-year-old woman is referred to the outpatient department because of increasing breathlessness. What do this ECG and chest X-ray show, what physical signs might you expect, and what might be the underlying problem? What might you do?","ecg_shows":"•\tSinus rhythm, rate 65/min •\tPeaked P waves, best seen in lead II •\tRight axis deviation •\tDominant R waves in lead V1 •\tDeep S waves in lead V6 •\tInverted T waves in leads II, III, VF, V1–V3","clinical_interpretation":"This combination of right axis deviation, dominant R waves in lead V1 and inverted  T waves spreading from the right side of the heart is classic of severe right vent­ ricular hypertrophy. Right ventricular hypertrophy can result from congenital heart  disease, or from pulmonary hypertension which may be idiopathic, secondary to  mitral valve disease, lung disease, or pulmonary embolism. The physical signs of  right ventricular hypertrophy are a left parasternal heave and a displaced but diffuse  apex beat. There may be a loud pulmonary second sound. The jugular venous pres­ sure may be elevated, and a ‘flicking A’ wave in the jugular venous pulse is charac­ teristic of pulmonary hypertension.","what_to_do":"The two main causes of pulmonary hypertension of this degree in a 40-year-old  woman are recurrent pulmonary emboli, and idiopathic (primary) pulmonary  hypertension. Clinically, it is difficult to differentiate between the two, but a lung  scan and CT pulmonary angiography will help. In either case, anticoagulants are  indicated. In fact, this patient had primary pulmonary hypertension and treatment  with high dose calcium channel blockers, prostanoids, endothelin receptor antago­ nists (bosentan) and phosphodiesterase inhibitors was tried, without success. Even­ tually she needed heart and lung transplantation.","summary":"Severe right ventricular hypertrophy.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":65,"min":60,"max":70},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Peaked (Pulmonale)","atrial_enlargement":"Right Atrial Enlargement","enlargement":"Right Atrial Enlargement"},"qrs":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"The two main causes of pulmonary hypertension of this degree in a 40-year-old  woman are recurrent pulmonary emboli, and idiopathic (primary) pulmonary  hypertension. Clinically, it is difficult to differentiate between the two, but a lung  scan and CT pulmonary angiography will help. In either case, anticoagulants are  indicated. In fact, this patient had primary pulmonary hypertension and treatment  with high dose calcium channel blockers, prostanoids, endothelin receptor antago­ nists (bosentan) and phosphodiesterase inhibitors was tried, without success. Even­ tually she needed heart and lung transplantation."},"qrs_morph":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_009.png' OR image_url LIKE '%case_9.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from an 80-year-old man who complained of breathlessness and ankle swelling which had become slowly worse over the preceding few months. He had had no chest pain and was on no treatment. He had a slow pulse, and signs of heart failure. What does the ECG show and how would you manage him?","ecg_shows":"•\tAtrial fibrillation with a ventricular rate of about 40/min •\tLeft axis deviation •\tLeft bundle branch block (LBBB)","clinical_interpretation":"When an ECG shows LBBB, no further interpretation is usually possible. Here there  is atrial fibrillation, and the ventricular response is very slow, suggesting that there  is conduction delay in the His bundle as well as in the left bundle branch. Alterna­ tively he may be taking too much digoxin.","what_to_do":"It is always important to establish the cause of heart failure. In this patient the slow  ventricular rate may be at least part of the problem. The most important causes of  LBBB are ischaemia, aortic stenosis and cardiomyopathy. In this patient an echo­ cardiogram will show whether he has significant valve disease and how impaired  his left ventricular function is. In the absence of pain, coronary angiography is  probably not indicated. The heart failure needs to be treated with diuretics and an  angiotensin-converting enzyme inhibitor, but digoxin must be avoided as it may  slow the ventricular response still further. He almost certainly needs a permanent  pacemaker.","summary":"Atrial fibrillation and LBBB.","stars":1,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":40,"min":35,"max":45},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"It is always important to establish the cause of heart failure. In this patient the slow  ventricular rate may be at least part of the problem. The most important causes of  LBBB are ischaemia, aortic stenosis and cardiomyopathy. In this patient an echo­ cardiogram will show whether he has significant valve disease and how impaired  his left ventricular function is. In the absence of pain, coronary angiography is  probably not indicated. The heart failure needs to be treated with diuretics and an  angiotensin-converting enzyme inhibitor, but digoxin must be avoided as it may  slow the ventricular response still further. He almost certainly needs a permanent  pacemaker."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_010.png' OR image_url LIKE '%case_10.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG came from a 40-year-old woman who complained of palpitations, which were present when the recording was made. What abnormality does it show?","ecg_shows":"•\tLead II rhythm strip of the ECG •\tThe first beat has a normal P wave and is normal (i.e. a sinus beat) •\tThe next four beats, at about 100/min, have abnormal (inverted) P waves,  and this is an atrial tachycardia •\tAfter a pause the next two beats have normal P waves and are in sinus rhythm  at about 60/min •\tAfter two sinus beats there is an extrasystole with an inverted P wave; this is an  atrial extrasystole •\tNormal axis •\tThe QRS complexes, ST segments and T waves are normal","clinical_interpretation":"Since the patient had her symptoms at the time of the recording, we can be confident  that the ECG findings explain them. Atrial extrasystoles are not a manifestation of  cardiac disease, but the atrial tachycardia may be and will need treating on symp­ tomatic grounds.","what_to_do":"Ensure that there is no other evidence of heart disease. She should stop smoking  and avoid alcohol, coffee and tea. A beta-blocker will probably prevent the  tachycardia.","summary":"Sinus rhythm with atrial tachycardia and one atrial extrasystole.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":65,"min":55,"max":100},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Inverted","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Ensure that there is no other evidence of heart disease. She should stop smoking  and avoid alcohol, coffee and tea. A beta-blocker will probably prevent the  tachycardia."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_011.png' OR image_url LIKE '%case_11.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man had had high blood pressure for many years, but it was now well controlled at 140/85. He had no symptoms, and no abnormalities were detected on physical examination. This ECG was recorded during a routine follow-up appointment. Does it give any cause for concern, and if so, what would you do?","ecg_shows":"•\tSinus rhythm, rate 73/min •\tNormal PR interval •\tLeft axis deviation (left anterior hemiblock) •\tNormal QRS complexes •\tT wave inversion in leads I and VL","clinical_interpretation":"The left axis deviation indicates a conduction defect in the anterior fascicle of the  left bundle branch – left anterior hemiblock. This is due to fibrosis, almost certainly  the result of long-standing hypertension. The T wave inversion in the lateral leads  (I and VL) probably indicates left ventricular hypertrophy, although the QRS  complex in lead V6 is not unusually tall and the ‘voltage criteria’ for left ventricular  hypertrophy are not met. It is, therefore, possible that the T wave inversion is due  to ischaemia.","what_to_do":"This man clearly has ‘target organ’ (heart) damage as the result of his hypertension.  An echocardiogram should be recorded to assess his left ventricular thickness and  function, because the prognosis is worse if there is left ventricular hypertrophy or  if there is any reduction in function. The presence of other risk factors, such as  diabetes and hypercholesterolaemia, must be checked and, if necessary, treated. If  there is any suggestion of angina, an exercise test should be performed, but if he  really is completely asymptomatic this is probably not essential. Careful control of  his blood pressure is the key to management, and since there is evidence of cardiac  damage, an angiotensin-converting enzyme inhibitor should be the basis of  treatment.","summary":"Left anterior hemiblock and either left ventricular hypertrophy or ischaemia.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":73,"min":68,"max":78},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"This man clearly has ‘target organ’ (heart) damage as the result of his hypertension.  An echocardiogram should be recorded to assess his left ventricular thickness and  function, because the prognosis is worse if there is left ventricular hypertrophy or  if there is any reduction in function. The presence of other risk factors, such as  diabetes and hypercholesterolaemia, must be checked and, if necessary, treated. If  there is any suggestion of angina, an exercise test should be performed, but if he  really is completely asymptomatic this is probably not essential. Careful control of  his blood pressure is the key to management, and since there is evidence of cardiac  damage, an angiotensin-converting enzyme inhibitor should be the basis of  treatment."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_012.png' OR image_url LIKE '%case_12.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 40-year-old man who was admitted to hospital as an emergency, with the sudden onset of the symptoms and signs of severe left ventricular failure. What does it show and what would you do?","ecg_shows":"•\tAtrial flutter with 2 : 1 block (best seen in leads II, III, VF) •\tNormal axis •\tNormal QRS complexes •\tThe T waves are difficult to identify because of the flutter waves","clinical_interpretation":"The sudden onset of atrial flutter presumably explains the heart failure. There is  nothing on the ECG to suggest a cause for the arrhythmia.","what_to_do":"When an arrhythmia causes severe heart failure, immediate treatment is more  important than establishing the underlying diagnosis. Carotid sinus pressure and  adenosine may increase the degree of block, but are unlikely to convert the heart  to sinus rhythm. It is worth trying intravenous flecainide, but a patient with severely  compromised circulation is best promptly treated with DC cardioversion. In the  long term, ablation therapy to prevent further episodes of atrial flutter may be  needed.","summary":"Atrial flutter with 2 : 1 block.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"2:1","p_qrs_relation":"2:1","sa_block":"None"},"rate":{"target":150,"min":140,"max":160},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"When an arrhythmia causes severe heart failure, immediate treatment is more  important than establishing the underlying diagnosis. Carotid sinus pressure and  adenosine may increase the degree of block, but are unlikely to convert the heart  to sinus rhythm. It is worth trying intravenous flecainide, but a patient with severely  compromised circulation is best promptly treated with DC cardioversion. In the  long term, ablation therapy to prevent further episodes of atrial flutter may be  needed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_013.png' OR image_url LIKE '%case_13.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man is admitted to hospital as an emergency, having had chest pain characteristic of a myocardial infarction for 4 h. Apart from the features associated with pain there are no abnormal physical findings. What does this ECG show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 72/min •\tNormal axis •\tSmall Q waves in lead III •\tElevated ST segments in leads II, III, VF, with upright T waves •\tSuggestion of ST segment depression in leads V2–V3 •\tT wave inversion in lead VL","clinical_interpretation":"A classic ECG of an acute inferior myocardial infarction, with lead VL indicating  ischaemia. The rate of development of Q waves is very variable: compare this record  with ECG 32, which came from a patient with a similar duration of symptoms.","what_to_do":"Pain relief must take priority. In the absence of contraindications (i.e. risk of bleed­ ing from any important site), the patient should be given aspirin and then percuta­ neous coronary intervention (PCI) or a thrombolytic agent.","summary":"Acute inferior myocardial infarction.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":72,"min":67,"max":77},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"Pain relief must take priority. In the absence of contraindications (i.e. risk of bleed­ ing from any important site), the patient should be given aspirin and then percuta­ neous coronary intervention (PCI) or a thrombolytic agent."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_014.png' OR image_url LIKE '%case_14.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 20-year-old student complains of palpitations. Attacks occur about once per year. They start suddenly, his heart feels very fast and regular, and he quickly feels breathless and faint. The attacks stop suddenly after a few minutes. There are no abnormalities on examination, and this is his ECG. What would you do?","ecg_shows":"•\tSinus rhythm, rate 56/min •\tShort PR interval, most obvious in the chest leads •\tNormal axis •\tWide QRS complexes (136 ms) •\tSlurred upstroke of the QRS complex (delta wave) •\tDominant R wave in lead V1","clinical_interpretation":"This ECG is classic of Wolff–Parkinson–White (WPW) syndrome. The resemblance  to the ECG of right ventricular hypertrophy is because this is WPW type A, with a  left-sided accessory pathway.","what_to_do":"The patient gives a clear story of a paroxysmal tachycardia, and during attacks he  feels dizzy, so the circulation is clearly compromised. The attacks are infrequent, so  there is little point in recording an ambulatory ECG. The patient needs immediate  referral to an electrophysiologist for ablation of the aberrant conducting pathway.","summary":"The WPW syndrome type A.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":56,"min":50,"max":62},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The patient gives a clear story of a paroxysmal tachycardia, and during attacks he  feels dizzy, so the circulation is clearly compromised. The attacks are infrequent, so  there is little point in recording an ambulatory ECG. The patient needs immediate  referral to an electrophysiologist for ablation of the aberrant conducting pathway."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_015.png' OR image_url LIKE '%case_15.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 75-year-old woman who complained of attacks of dizziness. It shows one abnormality: what is its significance?","ecg_shows":"•\tSinus rhythm, 55/min •\tProlonged PR interval of 320 ms •\tNormal axis •\tRSR1 pattern in lead V1, with normal QRS complex duration: partial right  bundle branch block (RBBB) •\tNormal ST segments and T waves","clinical_interpretation":"Sinus rhythm with first degree block. The partial RBBB is probably not  significant.","what_to_do":"First degree block does not cause any haemodynamic impairment, and by itself is  of little significance. However, when a patient has symptoms (in this case dizziness)  which might be due to a bradycardia, there may be episodes of second or third  degree block, or possibly Stokes–Adams attacks, associated with a slow ventricular  rate. The appropriate action is therefore to request an ambulatory ECG, recorded  over 24 h, in the hope that the patient will have one of her attacks of dizziness  during this time. It would then be possible to see whether the dizziness was associ­ ated with a change in heart rhythm. First degree block itself is not an indication for  permanent pacing or for any other intervention.","summary":"Sinus rhythm with first degree block.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":55,"min":50,"max":60},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"1st Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"First degree block does not cause any haemodynamic impairment, and by itself is  of little significance. However, when a patient has symptoms (in this case dizziness)  which might be due to a bradycardia, there may be episodes of second or third  degree block, or possibly Stokes–Adams attacks, associated with a slow ventricular  rate. The appropriate action is therefore to request an ambulatory ECG, recorded  over 24 h, in the hope that the patient will have one of her attacks of dizziness  during this time. It would then be possible to see whether the dizziness was associ­ ated with a change in heart rhythm. First degree block itself is not an indication for  permanent pacing or for any other intervention."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_016.png' OR image_url LIKE '%case_16.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded in the A & E department from a 60-year-old man who had had severe central chest pain for 1 h. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 82/min •\tOne ventricular extrasystole •\tNormal axis •\tQ waves in leads V2–V3; small Q waves in leads VL, V4 •\tRaised ST segments in leads I, VL, V3–V6","clinical_interpretation":"This is an acute anterolateral ST segment elevation myocardial infarction (STEMI).  Although a Q wave is well developed in lead V3, the changes are entirely consistent  with the story of pain for 1 h.","what_to_do":"This patient needs pain relief with diamorphine. The ECG shows ST segments raised  by more than 2 mm in several leads, so he needs immediate percutaneous coronary  intervention (PCI) or thrombolysis once any risk of excessive bleeding has been  excluded. This treatment should not be delayed by waiting for a chest X-ray or any  other investigations. Ventricular extrasystoles do not need treating.","summary":"Acute anterolateral STEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":82,"min":77,"max":87},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"This patient needs pain relief with diamorphine. The ECG shows ST segments raised  by more than 2 mm in several leads, so he needs immediate percutaneous coronary  intervention (PCI) or thrombolysis once any risk of excessive bleeding has been  excluded. This treatment should not be delayed by waiting for a chest X-ray or any  other investigations. Ventricular extrasystoles do not need treating."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_017.png' OR image_url LIKE '%case_17.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old retired orthopaedic surgeon telephones to say that he always gets dizzy playing golf. You find that he has a systolic heart murmur. His ECG and chest X-ray are shown. What is the diagnosis and what do you do next?","ecg_shows":"•\tSinus rhythm, rate 48/min •\tNormal axis •\tQRS complex duration normal, but the R wave height in lead V5 is 30 mm, and  the S wave depth in lead V2 is 25 mm •\tInverted T waves in leads I, VL, V5–V6","clinical_interpretation":"This is the classic ECG appearance of left ventricular hypertrophy.","what_to_do":"The combination of dizziness on exercise, a systolic murmur, and evidence of left  ventricular hypertrophy suggests significant aortic stenosis. The next step is an  echocardiogram: in this patient it showed a gradient across the aortic valve of  140 mmHg, indicating severe stenosis. He needed an urgent aortic valve  replacement.","summary":"Left ventricular hypertrophy.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":48,"min":42,"max":54},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"The combination of dizziness on exercise, a systolic murmur, and evidence of left  ventricular hypertrophy suggests significant aortic stenosis. The next step is an  echocardiogram: in this patient it showed a gradient across the aortic valve of  140 mmHg, indicating severe stenosis. He needed an urgent aortic valve  replacement."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_018.png' OR image_url LIKE '%case_18.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 75-year-old woman complained of central chest discomfort on climbing hills, together with dizziness; on one occasion she had ‘fainted’ while climbing stairs. What abnormality does this ECG show and what physical signs would you look for?","ecg_shows":"•\tSinus rhythm, rate 79/min •\tLeft axis deviation •\tBroad QRS complexes (192 ms) •\t‘M’ pattern in lead V6 •\tInverted T waves in leads I, VL, V6","clinical_interpretation":"This is the characteristic pattern of left bundle branch block (LBBB). The ECG  cannot be interpreted further.","what_to_do":"A patient who has chest pain that could be angina, and who has dizziness and  syncope on exertion, probably has severe aortic stenosis – this was the case with  this woman. Clinically she had a slow rising pulse, a blood pressure of 100/80, and  a slightly enlarged heart. There was a loud ejection systolic murmur, best heard at  the upper right sternal edge and radiating to both carotids. The diagnosis was con­ firmed by an echocardiogram, which showed a gradient across the aortic valve of  about 100 mmHg. A cardiac catheter was necessary to exclude coronary disease.  She then had an aortic valve replacement, and made a complete recovery.","summary":"Sinus rhythm with LBBB.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":79,"min":74,"max":84},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"A patient who has chest pain that could be angina, and who has dizziness and  syncope on exertion, probably has severe aortic stenosis – this was the case with  this woman. Clinically she had a slow rising pulse, a blood pressure of 100/80, and  a slightly enlarged heart. There was a loud ejection systolic murmur, best heard at  the upper right sternal edge and radiating to both carotids. The diagnosis was con­ firmed by an echocardiogram, which showed a gradient across the aortic valve of  about 100 mmHg. A cardiac catheter was necessary to exclude coronary disease.  She then had an aortic valve replacement, and made a complete recovery."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_019.png' OR image_url LIKE '%case_19.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man is admitted to hospital following the onset of severe central chest pain. This is his ECG. What does it show and what treatment is needed?","ecg_shows":"•\tSinus rhythm, rate of sinus beats 75/min •\tSecond degree (Wenckebach) heart block (most obvious in the rhythm strip,  recorded from lead II) •\tVentricular rate 70/min •\tNormal axis •\tSmall Q waves in leads II, III, VF •\tRaised ST segments in leads II, III, VF •\tDepressed ST segments in leads V5–V6","clinical_interpretation":"This patient has second degree block of the Wenckebach type (progressive lengthen­ ing of the PR interval followed by a nonconducted P wave, and then a return to a  short PR interval and repeat of the sequence). There is also clear evidence of a recent  acute inferior ST segment elevation myocardial infarction (STEMI).","what_to_do":"The patient should be treated in the usual way for his acute myocardial infarction,  with pain relief and immediate percutaneous coronary intervention (PCI) or throm­ bolysis. Wenckebach second degree block is usually benign when it occurs with an  inferior infarction, and although he must obviously be monitored until sinus rhythm  with normal conduction returns, temporary pacing is not necessary.","summary":"Second degree (Wenckebach) atrioventricular block with acute inferior STEMI.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"2nd Degree Type I","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The patient should be treated in the usual way for his acute myocardial infarction,  with pain relief and immediate percutaneous coronary intervention (PCI) or throm­ bolysis. Wenckebach second degree block is usually benign when it occurs with an  inferior infarction, and although he must obviously be monitored until sinus rhythm  with normal conduction returns, temporary pacing is not necessary."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_020.png' OR image_url LIKE '%case_20.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a medical student during a practical class. What does it show?","ecg_shows":"•\tSinus rhythm, rate 70/min •\tSinus arrhythmia •\tNormal axis •\tNormal QRS complexes •\tNormal ST segments and T waves","clinical_interpretation":"This is a perfectly normal ECG. There is a beat-to-beat variation in the interval  between QRS complexes, with the heart rate speeding up and slowing down. Com­ parison of the rate recorded in lead VF with that recorded in lead V3 may give a  false impression of a change of rhythm, but the rhythm strip (lead II) clearly shows  the progressive alteration of the R–R interval. This variation in heart rate relates to  respiration and is called sinus arrhythmia, which is normal in young people. Sinus  arrhythmia can be distinguished from atrial extrasystoles because in sinus arrhyth­ mia the morphology of the P waves is unchanged.","what_to_do":"Nothing!","summary":"Normal ECG with sinus arrhythmia.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Nothing!"},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_021.png' OR image_url LIKE '%case_21.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 48-year-old man who had had severe central chest pain for 1 h. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 75/min •\tLeft axis deviation (left anterior hemiblock) •\tNormal QRS complexes, with a small Q wave (probably septal) in lead VL •\tInverted T waves in leads V1–V5","clinical_interpretation":"This is a classic acute anterior non-ST segment elevation myocardial infarction  (NSTEMI).","what_to_do":"This ECG does not meet the conventional criteria for immediate percutaneous coro­ nary intervention (PCI) or thrombolysis, which are raised ST segments or new left  bundle branch block. The treatment is pain relief, aspirin, heparin, a beta-blocker  and a statin – with PCI as soon as possible. The immediate outlook is good but the  patient should be monitored and the ECG repeated after 1 h to see if ST segment  elevation is appearing.","summary":"Acute anterior NSTEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"This ECG does not meet the conventional criteria for immediate percutaneous coro­ nary intervention (PCI) or thrombolysis, which are raised ST segments or new left  bundle branch block. The treatment is pain relief, aspirin, heparin, a beta-blocker  and a statin – with PCI as soon as possible. The immediate outlook is good but the  patient should be monitored and the ECG repeated after 1 h to see if ST segment  elevation is appearing."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_022.png' OR image_url LIKE '%case_22.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and chest X-ray are from a 70-year-old man who had had angina for some time and was being treated with a beta-blocker. He came to the A & E department complaining of pain similar to his angina, but much more severe and persistent for 4 h. He had a heart murmur. What do the ECG and chest X-ray show and what treatment would be appropriate?","ecg_shows":"•\tAtrial fibrillation; ventricular rate 62/min •\tLeft axis deviation (left anterior hemiblock) •\tBroad QRS complexes (160 ms) •\t‘M’ pattern of QRS complexes in leads V5–V6 •\tInverted T waves in leads I, VL, V5–V6","clinical_interpretation":"This ECG shows atrial fibrillation and left bundle branch block (LBBB). No further  interpretation is possible.","what_to_do":"This patient has angina, and the chest X-ray suggests aortic stenosis. LBBB is char­ acteristic of severe aortic stenosis. The problem is deciding whether his episode of  severe pain is due to a bad attack of angina or to a myocardial infarction. An aortic  dissection is also a possibility. Percutaneous coronary intervention (PCI) or throm­ bolytic agents should not be given unless there is evidence from previous records  that the LBBB is new, and treatment will depend on whether the plasma troponin  level is elevated. The patient urgently needs an echocardiogram, and probably needs  early cardiac catheterization with a view to aortic valve replacement. He will need  long-term anticoagulants because of the atrial fibrillation.","summary":"Atrial fibrillation and LBBB.","stars":1,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":62,"min":55,"max":70},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"This patient has angina, and the chest X-ray suggests aortic stenosis. LBBB is char­ acteristic of severe aortic stenosis. The problem is deciding whether his episode of  severe pain is due to a bad attack of angina or to a myocardial infarction. An aortic  dissection is also a possibility. Percutaneous coronary intervention (PCI) or throm­ bolytic agents should not be given unless there is evidence from previous records  that the LBBB is new, and treatment will depend on whether the plasma troponin  level is elevated. The patient urgently needs an echocardiogram, and probably needs  early cardiac catheterization with a view to aortic valve replacement. He will need  long-term anticoagulants because of the atrial fibrillation."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_023.png' OR image_url LIKE '%case_23.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and chest X-ray are from a 60-year-old man being treated as an outpatient for severe congestive cardiac failure. What might be the diagnosis of the underlying heart condition and what would you do?","ecg_shows":"•\tAtrial fibrillation •\tAverage ventricular rate 120/min •\tNormal axis •\tNormal QRS complexes •\tHorizontal ST segment depression in leads V3–V4 •\tDownward-sloping ST segment depression in leads I, II, V5–V6","clinical_interpretation":"The ventricular rate is not adequately controlled, though the downward-sloping ST  segment depression suggests that he is taking digoxin. The horizontal ST segment  depression suggests ischaemia.","what_to_do":"Despite the ECG evidence of ischaemia, possible diagnoses include rheumatic heart  disease, thyrotoxicosis, alcoholic heart disease, and other forms of cardiomyopathy.  The chest X-ray suggests severe mitral regurgitation. Echocardiography is necessary.  The serum digoxin level must be checked and the digoxin dose increased if appro­ priate. In addition to digoxin, the patient will need an angiotensin-converting  enzyme inhibitor, a diuretic and, unless contraindicated, anticoagulants. Beta- blockers must be considered once his cardiac failure is controlled.","summary":"Atrial fibrillation with an uncontrolled ventricular rate, probable ischaemia  and digoxin effect.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":120,"min":110,"max":130},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Despite the ECG evidence of ischaemia, possible diagnoses include rheumatic heart  disease, thyrotoxicosis, alcoholic heart disease, and other forms of cardiomyopathy.  The chest X-ray suggests severe mitral regurgitation. Echocardiography is necessary.  The serum digoxin level must be checked and the digoxin dose increased if appro­ priate. In addition to digoxin, the patient will need an angiotensin-converting  enzyme inhibitor, a diuretic and, unless contraindicated, anticoagulants. Beta- blockers must be considered once his cardiac failure is controlled."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_024.png' OR image_url LIKE '%case_24.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man, who 3 years earlier had had a myocardial infarction followed by mild angina, was admitted to hospital with central chest pain that had been present for 1 h and had not responded to sublingual nitrates. What does his ECG show, and what would you do?","ecg_shows":"•\tSinus rhythm, rate 103/min •\tNormal axis •\tQ waves in leads II, III, VF •\tNormal QRS complexes in the anterior leads •\tMarked ST segment elevation in leads V1–V6","clinical_interpretation":"The Q waves in leads III and VF suggest an old inferior infarction, while the elevated  ST segments in leads V1–V6 indicate an acute anterior ST segment elevation  infarction.","what_to_do":"The patient should be given pain relief, and in the absence of the usual contraindica­ tions should immediately be treated with aspirin, immediate percutaneous coronary  intervention (PCI) or a thrombolytic agent. If he was treated with streptokinase for  his previous infarction, he should be given alteplase or reteplase on this occasion.","summary":"Old inferior and acute anterior myocardial infarctions.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":103,"min":98,"max":108},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The patient should be given pain relief, and in the absence of the usual contraindica­ tions should immediately be treated with aspirin, immediate percutaneous coronary  intervention (PCI) or a thrombolytic agent. If he was treated with streptokinase for  his previous infarction, he should be given alteplase or reteplase on this occasion."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_025.png' OR image_url LIKE '%case_25.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 15-year-old boy was referred to the outpatient department because of a heart murmur. He had no symptoms. What does this ECG show and what physical signs would you look for?","ecg_shows":"•\tSinus rhythm, rate 83/min •\tRight axis deviation •\tBroad QRS complexes (140 ms) •\tRSR1 pattern in leads V1–V3 •\tWide and slurred S waves in lead V6 •\tNormal ST segments •\tT wave inversion in leads III, VF and V1–V4","clinical_interpretation":"Right bundle branch block (RBBB). The right axis deviation suggests left posterior  hemiblock.","what_to_do":"RBBB is seen in a small proportion of people with otherwise perfectly normal hearts.  In the presence of a heart murmur, however, the possibility of an atrial septal defect  should be considered. This is what this patient had. The physical signs were a widely  split pulmonary second sound which did not vary with inspiration (this is typical  of RBBB), and an ejection systolic murmur best heard at the left sternal edge. On  deep inspiration a soft diastolic murmur could be heard at the lower left sternal  edge. The systolic murmur is a pulmonary flow murmur due to the extra flow  through the right side of the heart, and the diastolic murmur that occurs on inspira­ tion is a tricuspid flow murmur. The diagnosis was confirmed by echocardiography,  and the defect was closed with a percutaneous ‘umbrella’ device. Following opera­ tion, the RBBB persisted.","summary":"Sinus rhythm with RBBB.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":83,"min":78,"max":88},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"RBBB is seen in a small proportion of people with otherwise perfectly normal hearts.  In the presence of a heart murmur, however, the possibility of an atrial septal defect  should be considered. This is what this patient had. The physical signs were a widely  split pulmonary second sound which did not vary with inspiration (this is typical  of RBBB), and an ejection systolic murmur best heard at the left sternal edge. On  deep inspiration a soft diastolic murmur could be heard at the lower left sternal  edge. The systolic murmur is a pulmonary flow murmur due to the extra flow  through the right side of the heart, and the diastolic murmur that occurs on inspira­ tion is a tricuspid flow murmur. The diagnosis was confirmed by echocardiography,  and the defect was closed with a percutaneous ‘umbrella’ device. Following opera­ tion, the RBBB persisted."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_026.png' OR image_url LIKE '%case_26.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 40-year-old man who complained of breathlessness on climbing stairs. He was not aware of a fast heart rate and had had no chest pain. Apart from a rapid rate there were no cardiovascular abnormalities, but he looked a little jaundiced and had an enlarged spleen. What would you do?","ecg_shows":"•\tAtrial flutter •\tVentricular rate 148/min •\tNormal axis •\tNormal QRS complexes, ST segments and T waves","clinical_interpretation":"Atrial flutter with 2 : 1 block.","what_to_do":"Provided the patient is not in heart failure, it is always a good idea to identify the  cause of an arrhythmia before treating it. The combination of an atrial arrhythmia,  jaundice and splenomegaly suggests alcoholism. The patient needs anticoagulants,  but his INR (international normalized ratio) may already be high. An echocardio­ gram is needed to assess left ventricular function. Carotid sinus massage will prob­ ably increase the degree of atrioventricular block, but is unlikely to correct the  arrhythmia. Digoxin, a beta-blocker or verapamil could be given in an attempt to  control the ventricular rate. After anticoagulation, cardioversion – either electrical  or with flecainide – will be necessary.","summary":"Atrial flutter with 2 : 1 conduction.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"2:1","p_qrs_relation":"2:1","sa_block":"None"},"rate":{"target":148,"min":140,"max":155},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Provided the patient is not in heart failure, it is always a good idea to identify the  cause of an arrhythmia before treating it. The combination of an atrial arrhythmia,  jaundice and splenomegaly suggests alcoholism. The patient needs anticoagulants,  but his INR (international normalized ratio) may already be high. An echocardio­ gram is needed to assess left ventricular function. Carotid sinus massage will prob­ ably increase the degree of atrioventricular block, but is unlikely to correct the  arrhythmia. Digoxin, a beta-blocker or verapamil could be given in an attempt to  control the ventricular rate. After anticoagulation, cardioversion – either electrical  or with flecainide – will be necessary."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_027.png' OR image_url LIKE '%case_27.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and pulmonary angiogram are from a 39-year-old woman who complained of a recent sudden onset of breathlessness. She had no previous history of breathlessness, and no chest pain. Examination revealed nothing, other than a rapid heart rate. A pulmonary angiogram was carried out as part of a series of investigations immediately after admission. What is the diagnosis?","ecg_shows":"•\tSinus rhythm, rate 140/min •\tNormal conduction •\tNormal axis •\tNormal QRS complexes •\tSlightly depressed ST segments in leads V1–V4 •\tBiphasic or inverted T waves in the inferior leads and all the chest leads","clinical_interpretation":"The ECG shows a marked sinus tachycardia, with no change in the cardiac axis  and normal QRS complexes. The widespread ST segment/T wave changes are clearly  very abnormal, but are not specific for any particular disease. However, the fact  that leads V1–V3 are affected suggests a right ventricular problem. The pulmonary angiogram shows a large central pulmonary embolus and occlu­ sion of the arteries to the right lower lung.","what_to_do":"This is a case where the ECG must be considered in the light of the patient’s history  and physical signs (if any). Clearly something has happened: the sudden onset of  breathlessness without pain suggests a central pulmonary embolus – with pulmo­ nary emboli that do not reach the pleural surface of the lung there may be little  pain. In this patient, an echocardiogram and then a pulmonary angiogram demon­ strated a large pulmonary embolus. Remember that sudden breathlessness with clear  lung fields on a routine chest X-ray is always assumed to be due to a pulmonary  embolus until proved otherwise. Heparin is essential; thrombolysis should be  considered.","summary":"Sinus tachycardia with widespread ST segment/T wave changes,  suggesting pulmonary embolism.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":140,"min":130,"max":150},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"This is a case where the ECG must be considered in the light of the patient’s history  and physical signs (if any). Clearly something has happened: the sudden onset of  breathlessness without pain suggests a central pulmonary embolus – with pulmo­ nary emboli that do not reach the pleural surface of the lung there may be little  pain. In this patient, an echocardiogram and then a pulmonary angiogram demon­ strated a large pulmonary embolus. Remember that sudden breathlessness with clear  lung fields on a routine chest X-ray is always assumed to be due to a pulmonary  embolus until proved otherwise. Heparin is essential; thrombolysis should be  considered."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_028.png' OR image_url LIKE '%case_28.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 50-year-old man who was admitted to hospital as an emergency, having had chest pain characteristic of a myocardial infarction for 3 h. What does the ECG show and how should the patient be treated?","ecg_shows":"•\tSinus rhythm, rate 65/min •\tPR interval markedly prolonged (480 ms) •\tNormal axis •\tNormal QRS complexes •\tT wave inversion in leads V1–V3","clinical_interpretation":"First degree block associated with a non-ST segment elevation anterior myocardial  infarction (NSTEMI). Since the T wave inversion is in leads V1–V3 but not V4, the  possibility of a pulmonary embolus must be considered.","what_to_do":"The ECG changes do not meet the conventional criteria for percutaneous coronary  intervention (PCI) or thrombolysis for myocardial infarction (raised ST segments or  new left bundle branch block), but the patient does need the full range of treatment  for an NSTEMI – heparin, aspirin, clopidogrel, a beta-blocker, possibly a nitrate,  and a statin. Early angiography must be considered. First degree block is not an  indication for temporary pacing, but the patient must be monitored in case higher  degrees of block develop.","summary":"First degree block and anterior NSTEMI.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":65,"min":60,"max":70},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"1st Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"The ECG changes do not meet the conventional criteria for percutaneous coronary  intervention (PCI) or thrombolysis for myocardial infarction (raised ST segments or  new left bundle branch block), but the patient does need the full range of treatment  for an NSTEMI – heparin, aspirin, clopidogrel, a beta-blocker, possibly a nitrate,  and a statin. Early angiography must be considered. First degree block is not an  indication for temporary pacing, but the patient must be monitored in case higher  degrees of block develop."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_029.png' OR image_url LIKE '%case_29.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 65-year-old man is seen in the outpatient department complaining of breathlessness and chest pain that has the characteristics of angina. He is untreated. Does his ECG help with his diagnosis and management?","ecg_shows":"•\tSinus rhythm, rate 48/min •\tNormal axis •\tSmall R waves in leads V2–V4 and a normal (tall) R wave in lead V5","clinical_interpretation":"The small R waves in leads V2–V4 and the ‘sudden’ appearance of a normal R wave  in lead V5 is called ‘poor R wave progression’, and despite the absence of Q waves  this probably indicates an old anterior infarction. An alternative explanation might  be poor lead positioning.","what_to_do":"The ECG should be repeated, to ensure proper positioning of the chest leads. An  echocardiogram and a chest X-ray are needed, to see if left ventricular impairment  is responsible for the breathlessness, and stress echocardiography or perfusion  imaging are needed, to investigate the chest pain.","summary":"Poor R wave progression, suggesting an old anterior myocardial infarction.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":48,"min":42,"max":54},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"The ECG should be repeated, to ensure proper positioning of the chest leads. An  echocardiogram and a chest X-ray are needed, to see if left ventricular impairment  is responsible for the breathlessness, and stress echocardiography or perfusion  imaging are needed, to investigate the chest pain."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_030.png' OR image_url LIKE '%case_30.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded in a coronary care unit from a patient admitted 2 h previously with an acute anterior myocardial infarction. The patient was cold, clammy and confused, and his blood pressure was unrecordable. What does the ECG show and what would you do?","ecg_shows":"•\tBroad complex tachycardia, rate about 215/min •\tRegular QRS complexes •\tQRS complex duration uncertain: probably about 280 ms •\tIndeterminate axis and QRS complex configuration","clinical_interpretation":"In the context of acute myocardial infarction, broad complex tachycardias should  be considered to be ventricular in origin – unless the patient is known to have bundle  branch block when in sinus rhythm. Here the regularity of the rhythm and the very  broad complexes of bizarre configuration leave no room for doubt that this is vent­ ricular tachycardia.","what_to_do":"In cases of severe circulatory failure, immediate DC cardioversion is needed.","summary":"Ventricular tachycardia.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":215,"min":205,"max":225},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Extreme Left Deviation","deviation":"Extreme Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"In cases of severe circulatory failure, immediate DC cardioversion is needed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_031.png' OR image_url LIKE '%case_31.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man is admitted to hospital as an emergency, having had chest pain for 4 h. The pain is characteristic of a myocardial infarction. Apart from signs due to pain, the examination is normal. What does this","ecg_shows":"•\tSinus rhythm, rate 38/min •\tNormal axis •\tSmall Q waves in leads II, III, VF, V4–V6 •\tNormal QRS complexes in the chest leads •\tRaised ST segments in leads II, III, VF and to a lesser extent in V4 and V5 •\tDownward-sloping ST segments in leads VL and V2","clinical_interpretation":"This is an acute ST segment elevation inferior myocardial infarction (STEMI). The  rapidity of Q wave development is extremely variable, but the trace is certainly  consistent with a 4 h history. The depressed and downward-sloping ST segment in  lead V2 suggests involvement of the posterior wall of the left ventricle.","what_to_do":"Pain relief is the most important part of the treatment. In the absence of contra­ indications, the patient should be given aspirin immediately, and then percutaneous  coronary intervention (PCI) or thrombolysis as soon as possible.","summary":"Acute inferior STEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":38,"min":34,"max":44},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Pain relief is the most important part of the treatment. In the absence of contra­ indications, the patient should be given aspirin immediately, and then percutaneous  coronary intervention (PCI) or thrombolysis as soon as possible."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_032.png' OR image_url LIKE '%case_32.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 80-year-old man being observed in the recovery room following a femoral–popliteal bypass operation was noted to have this abnormal ECG. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 68/min •\tNormal axis •\tNormal QRS complexes •\tMarked horizontal ST segment depression (about 8 mm) in leads V2–V4, and  downward-sloping ST segment depression in the lateral leads","clinical_interpretation":"The patient is elderly and has peripheral vascular disease, so coronary disease is  likely to be present. The appearance of the ECG is characteristic of severe cardiac  ischaemia. The lack of a tachycardia is surprising.","what_to_do":"This is not an easy situation to deal with because the patient’s postoperative condi­ tion dictates management. He needs anticoagulation with aspirin and heparin,  though his postoperative state may prevent this, and intravenous nitrates should be  given cautiously.","summary":"Severe anterolateral ischaemia.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":68,"min":62,"max":74},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"This is not an easy situation to deal with because the patient’s postoperative condi­ tion dictates management. He needs anticoagulation with aspirin and heparin,  though his postoperative state may prevent this, and intravenous nitrates should be  given cautiously."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_033.png' OR image_url LIKE '%case_33.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 75-year-old man who complained of breathlessness. He had not had any chest pain or dizziness. Apart from a slow pulse, there were no abnormalities on examination. What three abnormalities are present in this record and how would you treat the patient?","ecg_shows":"•\tSinus rhythm; ventricular rate 45/min •\tSecond degree (2 : 1) block •\tLeft axis deviation •\tPoor R wave progression in the anterior leads •\tNormal T waves","clinical_interpretation":"The second degree block is associated with a ventricular rate of 45/min, which may  well be the cause of his breathlessness. The left axis deviation indicates left anterior  hemiblock. The poor R wave progression (virtually no R wave in lead V3, a small  R wave in lead V4, and a normal R wave in lead V5) suggests an old anterior  infarction.","what_to_do":"This patient needs a permanent pacemaker.","summary":"Second degree (2 : 1) block, left anterior hemiblock, and probable old  anterior infarction.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"2:1","p_qrs_relation":"2:1","sa_block":"None"},"rate":{"target":45,"min":40,"max":50},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"2nd Degree Type II","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"This patient needs a permanent pacemaker."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_034.png' OR image_url LIKE '%case_34.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a fit 22-year-old male medical student. He was worried – should he have been?","ecg_shows":"•\tSinus rhythm, rate 44/min •\tNormal axis •\tTall R waves (23 mm in lead V5) and deep S waves (41 mm in lead V2) •\tNormal ST segments and T waves •\tProminent U waves in leads V2–V5","clinical_interpretation":"This record shows left ventricular hypertrophy by ‘voltage criteria’ (R waves greater  than 25 mm in lead V5 or V6, or the sum of the R wave in lead V5 or V6 plus the  S wave in lead V1 or V2 is greater than 35 mm). There are, however, no T wave  changes. ‘Voltage criteria’ on their own are unreliable, and in a fit young man this  may well be a normal variant. The U waves are perfectly normal, and this pattern  is common in athletes.","what_to_do":"Tell the student to buy a good book on ECG interpretation, but if reassurance  is not enough, echocardiography could be used to measure the left ventricular  thickness.","summary":"Left ventricular hypertrophy on ‘voltage criteria’, but probably normal.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":44,"min":40,"max":50},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Tell the student to buy a good book on ECG interpretation, but if reassurance  is not enough, echocardiography could be used to measure the left ventricular  thickness."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_035.png' OR image_url LIKE '%case_35.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man was seen as an outpatient with symptoms and signs of heart failure. His problem had begun quite suddenly a few weeks previously, when he had had a few hours of dull central chest discomfort. What do his ECG and the enlarged part of his chest X-ray show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 100/min •\tNormal axis •\tQ waves in leads I, VL, V2–V5 •\tRaised ST segments in leads I, VL, V2–V6","clinical_interpretation":"The raised ST segments suggest an acute infarction, but the deep Q waves suggest  that the infarction occurred at least several hours previously. From the patient’s  story it seems clear that he had an infarction several weeks before he was seen, and  there was nothing in the history to suggest a more recent episode. These ECG  changes are therefore probably all old; the anterior changes might indicate a left  ventricular aneurysm.","what_to_do":"An ECG should always be interpreted in the light of the patient’s clinical state. Since  the ECG is compatible with an old infarction it should be assumed that this diag­ nosis is correct, and the patient should be treated for heart failure in the usual way  with diuretics, angiotensin-converting enzyme inhibitors and beta-blockers. Since  the heart failure is clearly due to ischaemia he also needs aspirin and a statin.","summary":"Anterolateral myocardial infarction of uncertain age.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":100,"min":95,"max":105},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"An ECG should always be interpreted in the light of the patient’s clinical state. Since  the ECG is compatible with an old infarction it should be assumed that this diag­ nosis is correct, and the patient should be treated for heart failure in the usual way  with diuretics, angiotensin-converting enzyme inhibitors and beta-blockers. Since  the heart failure is clearly due to ischaemia he also needs aspirin and a statin."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_036.png' OR image_url LIKE '%case_36.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man was referred to the outpatient department because of exercise-induced chest pain. The upper ECG is his record at rest, and the lower one was taken during stage 1 of the Bruce exercise protocol (1.7 mph and 10% grade on the treadmill). What do these ECGs show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 75/min •\tNormal axis •\tNormal QRS complexes •\tSlight ST segment depression in leads II, VF, V6 •\tT wave inversion in lead III","clinical_interpretation":"The ST segment changes in leads II, VF and V6 are nonspecific, and the T wave  inversion in lead III could well be a normal variant. Nevertheless, with the story of  exercise-induced chest pain a diagnosis of angina seems likely, and an exercise test  is the appropriate next step. Lower ECG The ECG shows: •\tSinus rhythm at 140/min •\tNormal axis •\tNormal QRS complexes •\tST segment depression in most leads, the maximum being 4 mm in lead V5 Clinical interpretation The resting ECG shows only nonspecific changes, but the ECG on exercise shows  the classic changes of ischaemia – appearing during the first stage of the Bruce  protocol. Even this light exercise level markedly increased the heart rate. Both the  inferior and the anterior chest leads show definite ischaemia, so widespread coro­ nary disease is likely, possibly including the main stem of the left coronary artery.","what_to_do":"This patient can be treated immediately with short- and long-acting nitrates, beta- blockers and calcium antagonists, but he also needs urgent coronary angiography  with a view to percutaneous coronary intervention (PCI) or coronary artery bypass  graft surgery. Risk factors such as smoking, weight and hypercholesterolaemia must  also be addressed.","summary":"Nonspecific ECG changes at rest; strongly positive exercise test.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"This patient can be treated immediately with short- and long-acting nitrates, beta- blockers and calcium antagonists, but he also needs urgent coronary angiography  with a view to percutaneous coronary intervention (PCI) or coronary artery bypass  graft surgery. Risk factors such as smoking, weight and hypercholesterolaemia must  also be addressed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_037.png' OR image_url LIKE '%case_37.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man with long-standing high blood pressure has had attacks of dizziness over several weeks. His pulse feels irregular but there are no other abnormal signs. This was his ECG. What does it show and what would you do?","ecg_shows":"•\tThe first nine beats with sinus rhythm and a ventricular rate of about 80/min •\tThe PR interval in these nine beats slowly increases, from 240 ms to 360 ms •\tThere is then a nonconducted P wave, followed by a conducted P wave with a  PR interval of 360 ms •\tThere is then a second nonconducted P wave, followed by two conducted P  waves, again with a PR interval of 360 ms •\tNormal axis •\tNormal QRS complexes, ST segments and T waves","clinical_interpretation":"This ECG shows a mixture of different types of heart block. The progressively  increasing PR intervals followed by a nonconducted P wave represent second degree  block of the Wenckebach (Mobitz type 1) type. The next nonconducted P wave  followed by a conducted P wave with a long PR interval is second degree block of  Mobitz type 2. The final beat, with the same prolonged PR interval, shows first  degree block. The changing heart rate is presumably the cause of his attacks of  dizziness.","what_to_do":"Since this man has had no pain, and there is no evidence of ischaemia on the ECG,  it is perhaps unlikely that coronary disease is responsible for the conduction problem.  You should always think about myocarditis, and about infiltrative diseases that  might affect the bundle of His, but in a hypertensive patient the most likely cause  of this sort of heart block is medication. He may well be taking either a beta-blocker  or a calcium-blocker, and the first thing to do would be to discontinue these.","summary":"Second degree block of both the Wenckebach type and Mobitz type 2,  and also first degree block.","stars":3,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":80,"min":75,"max":85},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"2nd Degree Type I","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Since this man has had no pain, and there is no evidence of ischaemia on the ECG,  it is perhaps unlikely that coronary disease is responsible for the conduction problem.  You should always think about myocarditis, and about infiltrative diseases that  might affect the bundle of His, but in a hypertensive patient the most likely cause  of this sort of heart block is medication. He may well be taking either a beta-blocker  or a calcium-blocker, and the first thing to do would be to discontinue these."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_038.png' OR image_url LIKE '%case_38.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old woman, from whom this ECG was recorded, was admitted to hospital with increasing congestive cardiac failure. What does the ECG show and what would you do?","ecg_shows":"•\tAtrial fibrillation, rate about 110/min •\tNormal axis •\tNormal QRS complexes •\tNormal ST segments","clinical_interpretation":"The rhythm could be interpreted as atrial flutter, particularly in lead VL. However,  the flutter-like activity is variable, and the QRS complexes are completely irregular,  so this is atrial fibrillation. The ST segments are normal, with no suggestion of  digoxin effect, and the ventricular rate is not controlled, so the patient is probably  not taking digoxin.","what_to_do":"The ventricular rate in this case is rapid, and the uncontrolled rate may be contrib­ uting to the patient’s heart failure. Her thyroid function tests should be checked,  and she needs an echocardiogram to assess heart size and left ventricular function.  The heart rate needs to be controlled, and digoxin is the first drug to use. Her heart  failure must be treated with a diuretic and probably an angiotensin-converting  enzyme inhibitor, and then a decision has to be taken regarding cardioversion. This  is unlikely to be successful unless some remediable cause of the atrial fibrillation,  such as thyrotoxicosis, is detected. At this age, she will need life-long anticoagula­ tion with warfarin, whatever her echocardiogram shows.","summary":"Atrial fibrillation with an uncontrolled ventricular rate.","stars":1,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":110,"min":100,"max":120},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The ventricular rate in this case is rapid, and the uncontrolled rate may be contrib­ uting to the patient’s heart failure. Her thyroid function tests should be checked,  and she needs an echocardiogram to assess heart size and left ventricular function.  The heart rate needs to be controlled, and digoxin is the first drug to use. Her heart  failure must be treated with a diuretic and probably an angiotensin-converting  enzyme inhibitor, and then a decision has to be taken regarding cardioversion. This  is unlikely to be successful unless some remediable cause of the atrial fibrillation,  such as thyrotoxicosis, is detected. At this age, she will need life-long anticoagula­ tion with warfarin, whatever her echocardiogram shows."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_039.png' OR image_url LIKE '%case_39.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 30-year-old woman who complained of palpitations. Does it help in making a diagnosis?","ecg_shows":"•\tEctopic atrial rhythm, with inverted P waves in leads II, III, VF, V3–V6;  ventricular rate 69/min •\tNormal axis •\tNormal QRS complexes and T waves","clinical_interpretation":"This appears to be a stable rhythm originating in the atrial muscle rather than the  SA node – hence the abnormal P wave and the slightly short PR interval (130 ms).  This rhythm is not uncommon, and is usually of no clinical significance. It is unlikely  to be the cause of her symptoms unless at times she has a paroxysmal atrial  tachycardia.","what_to_do":"Take a careful history and attempt to determine whether her symptoms sound like  a paroxysmal tachycardia – ask about any sudden onset and ending of the palpita­ tions; associated symptoms like breathlessness; precipitating and terminating factors;  and so on. If in doubt, some sort of ambulatory recording will be needed.","summary":"Ectopic atrial rhythm.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":69,"min":64,"max":74},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Inverted","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Take a careful history and attempt to determine whether her symptoms sound like  a paroxysmal tachycardia – ask about any sudden onset and ending of the palpita­ tions; associated symptoms like breathlessness; precipitating and terminating factors;  and so on. If in doubt, some sort of ambulatory recording will be needed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_040.png' OR image_url LIKE '%case_40.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a healthy 25-year-old man during a routine medical examination. Any comments?","ecg_shows":"•\tA very odd appearance •\tSinus rhythm, rate 70/min •\tInverted P waves in lead I •\tRight axis deviation •\tDominant R waves in lead VR •\tNo R wave development in the chest leads, with lead V6 still showing a right  ventricular pattern •\tNormal-width QRS complexes","clinical_interpretation":"This is dextrocardia. A normal trace would be obtained with the limb leads reversed  and the chest leads attached in the usual rib spaces but on the right side of the chest.","what_to_do":"Ensure that the leads are properly attached – for example, inverted P waves in lead  I will be seen if the right and left arm attachments are reversed. Of course, this  would not affect the appearance of the ECG in the chest leads.","summary":"Dextrocardia.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Inverted","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Ensure that the leads are properly attached – for example, inverted P waves in lead  I will be seen if the right and left arm attachments are reversed. Of course, this  would not affect the appearance of the ECG in the chest leads."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_041.png' OR image_url LIKE '%case_41.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 80-year-old woman, who has apparently been treated for heart failure for years, complains of nausea and vomiting. No previous records are available. Does her ECG help her management?","ecg_shows":"•\tAtrial fibrillation, ventricular rate 80/min •\tNormal axis •\tNormal QRS complexes •\tDownward-sloping ST segment depression, especially in leads V4–V6 •\tT waves probably upright •\tProminent U waves in leads V2–V3","clinical_interpretation":"The ECG shows atrial fibrillation with a controlled ventricular rate. There is nothing  on the ECG to suggest a cause for the arrhythmia or the patient’s heart failure. The  ‘reversed tick’ ST segment depression suggests that she is being treated with digoxin.  The ECG does not suggest digoxin toxicity, but nevertheless this is the most likely  cause of her nausea. The U waves may be normal, but raise the possibility of  hypokalaemia.","what_to_do":"Digoxin therapy should be temporarily discontinued, and her plasma potassium and  digoxin levels should be checked.","summary":"Atrial fibrillation and digoxin effect.","stars":1,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":80,"min":75,"max":85},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Digoxin therapy should be temporarily discontinued, and her plasma potassium and  digoxin levels should be checked."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_042.png' OR image_url LIKE '%case_42.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man, whose heart and preoperative ECG had been normal, developed a cough with pleuritic chest pain a few days after a cholecystectomy. These are his ECG and chest X-ray: what do they show and what might be the problem?","ecg_shows":"•\tAtrial fibrillation •\tNormal axis •\tRSR1 pattern in leads V1–V3, indicating right bundle branch block (RBBB)","clinical_interpretation":"In this ECG the usual ‘irregular baseline’ of atrial fibrillation is not apparent, but  the QRS complexes are so irregular that this must be the rhythm. The rhythm  change, together with the development of RBBB, could be due to a chest infection  but is more likely to have been caused by a pulmonary embolus. The right-sided  pleural effusion could also be due to either infection or embolism, but the patient  clearly has heart failure because the effusions are bilateral (although asymmetrical)  and there is diversion of blood flow to the upper zones of the lungs.","what_to_do":"In a postoperative patient, anticoagulation can always cause haemorrhage. Never­ theless, the risk of death from a pulmonary embolus is so high that the patient  should immediately be given heparin while steps are taken (white blood cell count,  sputum culture, CT scan) to differentiate between a chest infection and a pulmonary  embolus.","summary":"Atrial fibrillation with RBBB.","stars":3,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":90,"min":80,"max":100},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"In a postoperative patient, anticoagulation can always cause haemorrhage. Never­ theless, the risk of death from a pulmonary embolus is so high that the patient  should immediately be given heparin while steps are taken (white blood cell count,  sputum culture, CT scan) to differentiate between a chest infection and a pulmonary  embolus."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_043.png' OR image_url LIKE '%case_43.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and chest X-ray were recorded in the A & E department from a 50-year-old man with severe central chest pain that radiated into his back. The pain had been present for 6 h. What do the ECG and X-ray show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 88/min •\tPR interval 320 ms – first degree block •\tQ waves in leads II, III, VF •\tRaised ST segments in leads II, III, VF •\tInverted T waves in leads III, VF","clinical_interpretation":"This ECG shows an acute inferior myocardial infarction, which often causes first  degree block. The Q waves and raised ST segments are consistent with the story of  6 h of chest pain, and the first degree block is not important.","what_to_do":"Chest pain radiating through to the back has to raise the possibility of aortic dis­ section, which can occlude the opening of the coronary arteries and so cause a  myocardial infarction. However, this is relatively rare compared with back pain  associated with myocardial infarction, which is common. In this case, the chest  X-ray suggests that blood has leaked into the left pleural cavity from a dissection  of the aorta. Thrombolysis for the myocardial infarction is obviously contraindi­ cated, and the patient needs immediate investigation by CT or MR scanning to see  if surgical repair of the dissection is possible.","summary":"Acute inferior myocardial infarction with first degree block, due to dissection of  the aorta.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":88,"min":80,"max":95},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"1st Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"Chest pain radiating through to the back has to raise the possibility of aortic dis­ section, which can occlude the opening of the coronary arteries and so cause a  myocardial infarction. However, this is relatively rare compared with back pain  associated with myocardial infarction, which is common. In this case, the chest  X-ray suggests that blood has leaked into the left pleural cavity from a dissection  of the aorta. Thrombolysis for the myocardial infarction is obviously contraindi­ cated, and the patient needs immediate investigation by CT or MR scanning to see  if surgical repair of the dissection is possible."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_044.png' OR image_url LIKE '%case_44.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 23-year-old pregnant woman who had complained of palpitations, and who had been found to have a heart murmur. What does it show and what might be the problem?","ecg_shows":"•\tSinus rhythm, underlying rate 61/min •\tSupraventricular (atrial) extrasystoles •\tNormal PR interval •\tNormal axis •\tWide QRS complex (160 ms) •\tRSR1 pattern in lead V1 •\tBroad slurred S wave in lead V6 •\tInverted T waves in leads V1–V3","clinical_interpretation":"The broad QRS complex with an RSR1 pattern in lead V1 and a slurred S wave in  lead V6, together with the inverted T waves in leads V1–V3, indicate right bundle  branch block (RBBB). The extrasystoles are supraventricular because they have the  same (abnormal) QRS pattern as the sinus beats; they are atrial in origin because  each is preceded by a T wave of slightly different shape from the sinus beats.","what_to_do":"The palpitations of which the patient complains may well be due to the extrasys­ toles: it is important to ensure that they correspond to her symptoms. RBBB in a  young person may indicate an atrial septal defect, and she should have an echocar­ diogram. The heart murmur could be due to a septal defect, but could well be a  ‘flow murmur’ due to the increased cardiac output associated with pregnancy.","summary":"RBBB and atrial extrasystoles.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":61,"min":55,"max":68},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"The palpitations of which the patient complains may well be due to the extrasys­ toles: it is important to ensure that they correspond to her symptoms. RBBB in a  young person may indicate an atrial septal defect, and she should have an echocar­ diogram. The heart murmur could be due to a septal defect, but could well be a  ‘flow murmur’ due to the increased cardiac output associated with pregnancy."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_045.png' OR image_url LIKE '%case_45.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 9-year-old girl who was asymptomatic but who had been found to have a heart murmur at a school medical examination. What does it tell you about the murmur?","ecg_shows":"•\tSinus rhythm, rate 107/min •\tNormal axis •\tNormal QRS complexes, but narrow, deep Q waves in leads I, II, V4–V6 •\tInverted T waves in lead V1","clinical_interpretation":"A sinus tachycardia with normal QRS complexes, showing prominent ‘septal’ Q  waves, is characteristic of ECGs of children. The inverted T wave in lead V1 is  normal at any age. A normal ECG helps to exclude serious causes of heart murmurs,  but the record has not been very helpful in this case.","what_to_do":"If in doubt, an echocardiogram will show whether there is any important structural  abnormality of the heart.","summary":"Normal ECG in a 9-year-old child.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":107,"min":100,"max":115},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"If in doubt, an echocardiogram will show whether there is any important structural  abnormality of the heart."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_046.png' OR image_url LIKE '%case_46.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and chest X-ray were recorded from a diabetic man who was admitted to hospital because of the sudden onset of pulmonary oedema. What do you think has happened?","ecg_shows":"•\tAtrial fibrillation with a ventricular rate of about 180/min •\tLeft axis deviation •\tProbable Q waves in leads V2–V4 •\tQRS complexes of normal width and height •\tRaised ST segments in leads I, VL, V2–V4","clinical_interpretation":"This ECG shows uncontrolled atrial fibrillation with left anterior hemiblock and an  acute anterolateral ST segment elevation myocardial infarction (STEMI). The onset  of atrial fibrillation may have been the cause or the consequence of the myocardial  infarction, and the rapid ventricular rate will at least in part explain the pulmonary  oedema. The left anterior hemiblock is probably a consequence of the infarction.  The patient may not have experienced pain because of his diabetes.","what_to_do":"The most important thing is to relieve the patient’s distress and the pulmonary  oedema. He needs diamorphine, an intravenous diuretic, intravenous nitrates, and  intravenous digoxin to control the ventricular rate – all with careful monitoring.  Attention can then be turned to the treatment of his myocardial infarction. He will  need anticoagulation with heparin.","summary":"Atrial fibrillation, left anterior hemiblock and acute anterolateral STEMI.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":180,"min":170,"max":190},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The most important thing is to relieve the patient’s distress and the pulmonary  oedema. He needs diamorphine, an intravenous diuretic, intravenous nitrates, and  intravenous digoxin to control the ventricular rate – all with careful monitoring.  Attention can then be turned to the treatment of his myocardial infarction. He will  need anticoagulation with heparin."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_047.png' OR image_url LIKE '%case_47.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a young man seen in the outpatient department because of chest pain which appeared to be nonspecific. How would you interpret the ECG and what action would you take?","ecg_shows":"•\tSinus rhythm, rate 71/min •\tNormal axis •\tNormal QRS complexes •\tInverted T waves in leads III, VF; biphasic T waves in lead V4; flattened T  waves in leads V5–V6 •\tU waves in leads V2–V3 (normal)","clinical_interpretation":"These T wave changes, particularly those in the inferior leads, could well be caused  by ischaemia. The flattened T waves in the lateral leads can only be described as  ‘nonspecific’.","what_to_do":"When confronted with an ECG showing this sort of ‘nonspecific’ abnormality,  action depends primarily on the clinical diagnosis. If the patient is asymptomatic it  is fair to report the ECG as showing ‘nonspecific changes’; if the patient has symp­ toms at all – as in this case – it is probably worth proceeding to an exercise test. In  this patient, the exercise test was perfectly normal, and his symptoms cleared  without any intervention. A repeat ECG, recorded purely out of interest a month  later, showed similar changes.","summary":"Nonspecific ST segment and T wave changes.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":71,"min":66,"max":76},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Flattened"},"management":{"urgency":"Routine","notes":"When confronted with an ECG showing this sort of ‘nonspecific’ abnormality,  action depends primarily on the clinical diagnosis. If the patient is asymptomatic it  is fair to report the ECG as showing ‘nonspecific changes’; if the patient has symp­ toms at all – as in this case – it is probably worth proceeding to an exercise test. In  this patient, the exercise test was perfectly normal, and his symptoms cleared  without any intervention. A repeat ECG, recorded purely out of interest a month  later, showed similar changes."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_048.png' OR image_url LIKE '%case_48.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 65-year-old woman admitted to hospital as an emergency because of severe chest pain for 1 h. What does the ECG show? What other investigations would you order?","ecg_shows":"•\tSinus rhythm, rate 111/min •\tNormal axis •\tProbably normal QRS complexes •\tGross elevation of ST segments in anterior and lateral leads •\tDepressed ST segments in the inferior leads (III, VF)","clinical_interpretation":"Acute ST segment elevation anterolateral myocardial infarction (STEMI). In the  lateral leads I, VL and V4–V6, it is difficult to see where the QRS complexes end  and the ST segments begin, but in lead II it is clear that the QRS complex is of  normal width.","what_to_do":"If the patient gives a history suggestive of a myocardial infarction and has this ECG,  no further investigations are needed in the acute phase of the illness, and in parti­ cular there is no place for a chest X-ray. Routine treatment for a myocardial  infarction – pain relief, aspirin and percutaneous coronary intervention (PCI) or  thrombolysis – should be commenced immediately.","summary":"Acute anterolateral STEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":111,"min":105,"max":118},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Elevation","t_wave":"Hyperacute T Waves"},"management":{"urgency":"Emergency","notes":"If the patient gives a history suggestive of a myocardial infarction and has this ECG,  no further investigations are needed in the acute phase of the illness, and in parti­ cular there is no place for a chest X-ray. Routine treatment for a myocardial  infarction – pain relief, aspirin and percutaneous coronary intervention (PCI) or  thrombolysis – should be commenced immediately."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_049.png' OR image_url LIKE '%case_49.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 45-year-old woman had complained of occasional attacks of palpitations for 20 years, and eventually this ECG was recorded during an attack. What are the palpitations due to, and what would you do?","ecg_shows":"•\tNarrow complex tachycardia at 188/min •\tNo P waves visible •\tNormal axis •\tQRS complexes normal •\tSome ST segment depression","clinical_interpretation":"This ECG shows supraventricular tachycardia. This rhythm is usually due to a  re-entry pathway within, or near to, the atrioventricular node, so the rhythm is  properly called AV nodal re-entry tachycardia (AVNRT), although the term ‘supra­ ventricular tachycardia’ is often (inappropriately) used. The ST segment depression  could indicate ischaemia, but the ST segments are not horizontally depressed, nor  is the depression greater than 2 mm, so it is probably of no significance.","what_to_do":"The first action is carotid sinus pressure, which may terminate the attack. If this  fails it will almost certainly respond to adenosine. As with any tachycardia, electrical  cardioversion must be considered if there is haemodynamic compromise. Once sinus  rhythm has been restored, the patient must be taught the various methods (e.g. the  Valsalva manoeuvre) with which she might try to terminate an attack. Prophylactic  medication may not be needed if attacks are infrequent, but most patients with this  problem should have an electrophysiological study to try to identify a re-entry  pathway that can be ablated.","summary":"AV nodal re-entry (junctional) tachycardia (AVNRT).","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":188,"min":180,"max":195},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The first action is carotid sinus pressure, which may terminate the attack. If this  fails it will almost certainly respond to adenosine. As with any tachycardia, electrical  cardioversion must be considered if there is haemodynamic compromise. Once sinus  rhythm has been restored, the patient must be taught the various methods (e.g. the  Valsalva manoeuvre) with which she might try to terminate an attack. Prophylactic  medication may not be needed if attacks are infrequent, but most patients with this  problem should have an electrophysiological study to try to identify a re-entry  pathway that can be ablated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_050.png' OR image_url LIKE '%case_50.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 35-year-old woman who complained of breathlessness but not of pain. She was anxious, but there were no abnormalities on examination. Does this ECG help with her diagnosis and management?","ecg_shows":"•\tSinus rhythm, rate 106/min •\tNormal axis •\tNormal QRS complexes (septal Q waves in leads I and VL) •\tSlight ST segment depression, especially in leads II and V6 •\tT wave flattening in leads II, III, VF, V6 •\tT wave inversion in lead III","clinical_interpretation":"A sinus rate of over 100/min would be compatible with anxiety, though other  causes of ‘high output’ (e.g. pregnancy, thyrotoxicosis, anaemia, volume loss, CO2  retention, beri-beri) have to be considered. The widespread ST segment and T wave  changes have to be described as ‘nonspecific’; in an anxious patient they could  be due to hyperventilation. The ECG does not help with the diagnosis and  management.","what_to_do":"If a full history and examination fail to suggest any underlying physical disease,  further investigations are unlikely to be helpful.","summary":"Nonspecific ST segment and T wave changes.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"If a full history and examination fail to suggest any underlying physical disease,  further investigations are unlikely to be helpful."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_051.png' OR image_url LIKE '%case_51.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 60-year-old man seen in the clinic because of severe breathlessness, which had developed over several years. His jugular venous pressure is raised. What do you think the problem is?","ecg_shows":"•\tSinus rhythm, rate 140/min •\tOne ventricular extrasystole •\tPeaked P waves (best seen in leads II, III, VF) •\tNormal PR interval •\tRight axis deviation •\tDominant R wave in lead V1 •\tDeep S wave in lead V6 •\tNormal ST segments and T waves","clinical_interpretation":"The sinus tachycardia suggests a major problem. The peaked P waves indicate right  atrial hypertrophy. The right axis deviation and dominant R wave in lead V1 suggest  right ventricular hypertrophy. The deep S wave in lead V6, with no ‘left ventricular’  complexes in the chest leads, indicates ‘clockwise rotation’ of the heart, with the  right ventricle occupying the precordium. These changes suggest lung disease.","what_to_do":"Since the ECG is entirely ‘right-sided’, one can assume that the problem is due to  chronic lung disease or recurrent pulmonary embolism. The story sounds more in  keeping with a lung problem. The raised jugular venous pressure is presumably due  to cor pulmonale. The sinus tachycardia is worrying, and suggests respiratory  failure.","summary":"Sinus tachycardia and one ventricular extrasystole; right atrial and right ventricular  hypertrophy; and clockwise rotation – suggesting chronic lung disease.","stars":2,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":105,"min":100,"max":112},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Peaked (Pulmonale)","atrial_enlargement":"Right Atrial Enlargement","enlargement":"Right Atrial Enlargement"},"qrs":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Since the ECG is entirely ‘right-sided’, one can assume that the problem is due to  chronic lung disease or recurrent pulmonary embolism. The story sounds more in  keeping with a lung problem. The raised jugular venous pressure is presumably due  to cor pulmonale. The sinus tachycardia is worrying, and suggests respiratory  failure."},"qrs_morph":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_052.png' OR image_url LIKE '%case_52.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man is seen in the outpatient department complaining of breathlessness which began quite suddenly 2 months previously. He had had no chest pain. Examination revealed a raised jugular venous pressure, basal crackles in the lungs and a third sound at the cardiac apex. These are his does this fit the clinical picture? What would you do?","ecg_shows":"•\tSinus rhythm, rate 72/min •\tNormal axis •\tLarge Q waves in leads V1–V4 and small Q waves in leads I, VL •\tElevated ST segments and inverted T waves in leads V2–V5 •\tFlattened T waves in leads I and V6; inverted T waves in lead VL","clinical_interpretation":"This ECG would be compatible with an acute anterior myocardial infarction, but  this does not fit the clinical picture: it appears that an event occurred 2 months  previously. This pattern of ST segment elevation in the anterior leads can persist  following a large infarction, and is often seen in the presence of a ventricular aneur­ ysm. This is confirmed by the chest X-ray.","what_to_do":"An echocardiogram will show the extent of the aneurysm and whether the remaining  left ventricular function is impaired, which it almost certainly will be. The patient  should be treated with diuretics and an angiotensin-converting enzyme inhibitor,  and surgical resection of the aneurysm might be considered.","summary":"Old anterior myocardial infarction with a left ventricular aneurysm.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":72,"min":67,"max":77},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"An echocardiogram will show the extent of the aneurysm and whether the remaining  left ventricular function is impaired, which it almost certainly will be. The patient  should be treated with diuretics and an angiotensin-converting enzyme inhibitor,  and surgical resection of the aneurysm might be considered."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_053.png' OR image_url LIKE '%case_53.png';
UPDATE ecg_cases SET findings_json = '{"history":"The senior house officer in the A & E department is puzzled by this ECG which was recorded from an 80-year-old admitted unconscious with a stroke. What has the house officer missed? Perhaps he did not make a proper examination and did not look at the chest X-ray?","ecg_shows":"•\tRegular rhythm at 60/min •\tOccasional P waves, not related to QRS complexes (e.g. in lead I) •\tLeft axis deviation •\tQRS complexes preceded by a sharp ‘spike’ •\tBroad QRS complexes (160 ms) •\tDeep S wave in lead V6 •\tInverted T waves in leads I, VL","clinical_interpretation":"The broad QRS complexes show that this is either a supraventricular rhythm with  bundle branch block, or a ventricular rhythm. This rhythm is ventricular. The sharp  spikes preceding each QRS complex are due to the pacemaker. The P waves that  can occasionally be seen indicate that the underlying rhythm is complete heart  block – presumably the reason why the pacemaker was inserted.","what_to_do":"The house officer has missed the pacemaker, which is usually buried below the left  clavicle. There is no particular reason why the pacemaker should be related to the  stroke, except that patients with vascular disease in one territory usually have it in  others – this man probably has both coronary and cerebrovascular disease.","summary":"Permanent pacemaker and underlying complete block.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":60,"min":58,"max":62},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"3rd Degree","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"The house officer has missed the pacemaker, which is usually buried below the left  clavicle. There is no particular reason why the pacemaker should be related to the  stroke, except that patients with vascular disease in one territory usually have it in  others – this man probably has both coronary and cerebrovascular disease."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_054.png' OR image_url LIKE '%case_54.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old woman who complained of ‘dizzy turns’ was found to have an irregular pulse, and this ECG was recorded. There are three abnormalities. What advice would you give her?","ecg_shows":"•\tSinus rhythm; sinus rate 100/min •\tNormal and constant PR intervals in the conducted beats •\tOccasional nonconducted P waves (best seen in lead I) •\tLeft axis deviation •\tRight bundle branch block (RBBB)","clinical_interpretation":"This ECG shows second degree block (Mobitz type 2) and bifascicular block – left  axis deviation (left anterior hemiblock) and RBBB. This combination of conduction  abnormalities indicates disease throughout the conduction system, and is sometimes  called ‘trifascicular’ block.","what_to_do":"The ‘dizzy turns’ may represent intermittent complete block. Permanent pacing is  essential.","summary":"Second degree block (Mobitz type 2) and bifascicular block.","stars":2,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":85,"min":75,"max":95},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"2nd Degree Type II","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The ‘dizzy turns’ may represent intermittent complete block. Permanent pacing is  essential."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_055.png' OR image_url LIKE '%case_55.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man, who had come to the A & E department with chest pain, collapsed while his ECG was being recorded. What happened and what would you do?","ecg_shows":"•\tSinus rhythm initially 55/min, with ventricular extrasystoles •\tThe third extrasystole occurs on the peak of the T wave of the preceding sinus  beat •\tAfter three or four beats of ventricular tachycardia, ventricular fibrillation  develops •\tIn the sinus beats there is a Q wave in lead III; and there are raised ST segments  in leads II and III, and ST segment depression and T wave inversion in lead I","clinical_interpretation":"Although only leads I, II and III are available, it looks as if the chest pain was due  to an inferior myocardial infarction. This was probably the cause of the ventricular  extrasystoles, and an ‘R on T’ extrasystole caused ventricular tachycardia, which  rapidly decayed into ventricular fibrillation. It might be argued that in lead III, and  perhaps also in lead I, ‘torsade de pointes’ ventricular tachycardia is present, but  this is not apparent in lead II.","what_to_do":"Precordial thump and immediate defibrillation, but if no defibrillator is at hand then  cardiopulmonary resuscitation should be performed, and the usual procedure for  the management of cardiac arrest instituted.","summary":"Probable inferior myocardial infarction; R on T ventricular extrasystole, causing  ventricular fibrillation.","stars":1,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":250,"min":200,"max":300},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Precordial thump and immediate defibrillation, but if no defibrillator is at hand then  cardiopulmonary resuscitation should be performed, and the usual procedure for  the management of cardiac arrest instituted."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_056.png' OR image_url LIKE '%case_56.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man complained of severe central chest pain, and a few minutes later became extremely breathless and collapsed. He was brought to the A & E department, where his heart rate was found to be 165/min, his blood pressure was unrecordable and he had signs of left ventricular failure. This is his ECG. What has happened and what would you do?","ecg_shows":"•\tBroad complex tachycardia at 165/min •\tNo P waves visible •\tQRS complex duration about 200 ms •\tConcordance of QRS complexes (i.e. all point upwards) in the chest leads","clinical_interpretation":"A broad complex tachycardia can be ventricular in origin, or can be due to a supra­ ventricular tachycardia with aberrant conduction (i.e. bundle branch block). Here  the very broad complexes and the QRS complex concordance suggest a ventricular  tachycardia. In a patient with a myocardial infarction it is always safe to assume  that such a rhythm is ventricular. From the story, one would guess that this patient  had a myocardial infarction and then developed ventricular tachycardia, but it is  possible that the chest pain was due to the arrhythmia.","what_to_do":"This patient has haemodynamic compromise – low blood pressure and heart  failure – and needs immediate cardioversion. While preparations are being made it  would be reasonable to try intravenous lidocaine or amiodarone.","summary":"Ventricular tachycardia.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":165,"min":155,"max":175},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"This patient has haemodynamic compromise – low blood pressure and heart  failure – and needs immediate cardioversion. While preparations are being made it  would be reasonable to try intravenous lidocaine or amiodarone."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_057.png' OR image_url LIKE '%case_57.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man gave a history of several years of chest pain on exertion. These are his ECGs at rest (upper trace) and on exercise (lower trace). What do they show?","ecg_shows":"","clinical_interpretation":"The widespread T wave inversion suggests a non-ST segment elevation myocardial  infarction, although there is nothing in the history to suggest when this occurred.  The S wave in lead V6 suggests the possibility of chronic lung disease. The change  in the T waves in the anterior leads, from inverted at rest to normal on exercise, is  an example of ‘pseudonormalization’, which is an indication of ischaemia.","what_to_do":"‘Pseudonormalization’ must be regarded in the same way as the usual ST segment  response to ischaemia, which is depression. This patient’s exercise test was positive  (i.e. indicates ischaemia) at a relatively low level – so although his symptoms can  be treated medically in the usual way, a coronary angiogram with a view to inter­ vention is indicated. The risk factors for coronary disease must be assessed and  treated, whatever course of action is chosen.","summary":"Ischaemia with ‘pseudonormalization’ of the ECG on exercise.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":85},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"‘Pseudonormalization’ must be regarded in the same way as the usual ST segment  response to ischaemia, which is depression. This patient’s exercise test was positive  (i.e. indicates ischaemia) at a relatively low level – so although his symptoms can  be treated medically in the usual way, a coronary angiogram with a view to inter­ vention is indicated. The risk factors for coronary disease must be assessed and  treated, whatever course of action is chosen."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_058.png' OR image_url LIKE '%case_58.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 70-year-old woman who complained of an irregular heartbeat. What does it show and what would you do?","ecg_shows":"•\tAtrial fibrillation, rate about 110/min •\tFrequent multifocal ventricular extrasystoles •\tNormal axis in the sinus beats •\tLoss of R waves in leads V3–V4 •\tThere is downward-sloping ST segment depression in lead V6","clinical_interpretation":"This ECG shows an old anterior myocardial infarction, so ischaemia is probably  (but not certainly) the cause of the patient’s atrial fibrillation and extrasystoles. The  ventricular rate is not well controlled. The ST segment depression suggests that she  is taking digoxin.","what_to_do":"It would be prudent to check the patient’s serum potassium and digoxin levels to  make sure that the extrasystoles are not a manifestation of digoxin toxicity. An  echocardiogram should be recorded to check her heart size and left ventricular  function; remember that atrial fibrillation may be the only indication of thyrotoxi­ cosis in the elderly. Her complaint of palpitations may be due to her atrial fibrillation  or to the extrasystoles (or both). The extrasystoles themselves are not important,  but she should avoid smoking, alcohol and caffeine. A beta-blocker may reduce the  extrasystoles as well as control her ventricular rate. It is unlikely that cardioversion  would be successful, and she will need long-term treatment with digoxin, possibly  a beta-blocker, probably an angiotensin-converting enzyme inhibitor, and certainly  anticoagulants.","summary":"Atrial fibrillation, multifocal ventricular extrasystoles, and an old anterior  myocardial infarction.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":110,"min":100,"max":120},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"It would be prudent to check the patient’s serum potassium and digoxin levels to  make sure that the extrasystoles are not a manifestation of digoxin toxicity. An  echocardiogram should be recorded to check her heart size and left ventricular  function; remember that atrial fibrillation may be the only indication of thyrotoxi­ cosis in the elderly. Her complaint of palpitations may be due to her atrial fibrillation  or to the extrasystoles (or both). The extrasystoles themselves are not important,  but she should avoid smoking, alcohol and caffeine. A beta-blocker may reduce the  extrasystoles as well as control her ventricular rate. It is unlikely that cardioversion  would be successful, and she will need long-term treatment with digoxin, possibly  a beta-blocker, probably an angiotensin-converting enzyme inhibitor, and certainly  anticoagulants."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_059.png' OR image_url LIKE '%case_59.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man who was being treated in hospital complained of palpitations, and this ECG was recorded. What do you think the underlying disease was, and what were the palpitations due to?","ecg_shows":"•\tAtrial fibrillation •\tVentricular extrasystoles with two distinct morphologies (best seen in lead II) •\tA four-beat run of ventricular tachycardia •\tRight axis deviation •\tSmall QRS complexes •\tNo R wave development in the chest leads; lead V6 shows a dominant S wave •\tT wave inversion in leads V5–V6","clinical_interpretation":"This ECG suggests chronic lung disease – small complexes, right axis deviation, and  marked ‘clockwise rotation’, with lead V6 still showing a right ventricular type of  complex (i.e. a complex with a small R wave and a deeper S wave, as normally seen  in lead V1). The atrial fibrillation is probably secondary to the lung disease, though  the other possibilities must be considered. The patient’s lung condition is probably  being treated with a beta-agonist, such as salbutamol, and this could be the cause  of the extrasystoles and ventricular tachycardia.","what_to_do":"Stop the beta-agonist but do not give a beta-blocker. Check the electrolyte levels;  consider the possibility of digoxin toxicity.","summary":"Atrial fibrillation with ventricular extrasystoles and ventricular tachycardia;  changes suggesting chronic lung disease.","stars":3,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":120,"min":110,"max":130},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Stop the beta-agonist but do not give a beta-blocker. Check the electrolyte levels;  consider the possibility of digoxin toxicity."},"qrs_morph":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_060.png' OR image_url LIKE '%case_60.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 45-year-old man complained of palpitations, weight loss and anxiety. His blood pressure was 180/110, and his heart seemed normal. This is his ECG. His thyroid function tests, measured several times, were normal. What might be going on?","ecg_shows":"•\tNarrow complex rhythm at 110/minute •\tOne P wave per QRS complex – sinus tachycardia •\tNormal PR interval •\tNormal axis •\tNormal QRS complexes","clinical_interpretation":"The most common causes of a sinus tachycardia are exercise and anxiety, but this  patient was losing weight, and although he was anxious it is necessary to think  about other diagnoses. His diastolic blood pressure was high, which should not  happen with anxiety. He was not thyrotoxic but there must have been some other  physical cause of his problems – it turned out he had a phaeochromocytoma. See p. 57, 8E See p. 3, 6E","what_to_do":"","summary":"Sinus tachycardia.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":110,"min":105,"max":115},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":""},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_061.png' OR image_url LIKE '%case_61.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man is sent to the clinic because of rather vague attacks of dizziness, which occur approximately once per week. Otherwise he is well, and there are no abnormalities on examination. Does this ECG help with his management?","ecg_shows":"•\tSinus rhythm, rate 94/min •\tPR interval at the upper limit of normal (200 ms) •\tLeft axis deviation •\tQRS complex duration prolonged (160 ms) •\tRSR1 pattern in leads V1–V2; wide S wave in lead V6 •\tInverted T waves in leads VL, V1–V4","clinical_interpretation":"The left axis deviation is characteristic of left anterior hemiblock. There is also right  bundle branch block (RBBB), so two of the main conducting pathways are blocked,  resulting in ‘bifascicular block’. The fact that the PR interval is at the upper limit  of normal raises the possibility of delayed conduction in the remaining pathway; if  the PR interval were definitely prolonged, this would indicate ‘trifascicular block’.","what_to_do":"Bifascicular block is not an indication for pacing if the patient is asymptomatic. The  problem here is to decide if the attacks of dizziness are due to intermittent complete  heart block. Ideally an ECG would be recorded during an attack – since they occur  only every week or so, ambulatory ECG recording may not be helpful, but an event  recorder would be worth trying. In the absence of clear evidence, the decision  whether or not to insert a permanent pacemaker is a matter of judgement, but in a  patient with this story and ECG it would be a perfectly reasonable thing to do.","summary":"Left anterior hemiblock and RBBB – bifascicular block.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":94,"min":88,"max":98},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Bifascicular block is not an indication for pacing if the patient is asymptomatic. The  problem here is to decide if the attacks of dizziness are due to intermittent complete  heart block. Ideally an ECG would be recorded during an attack – since they occur  only every week or so, ambulatory ECG recording may not be helpful, but an event  recorder would be worth trying. In the absence of clear evidence, the decision  whether or not to insert a permanent pacemaker is a matter of judgement, but in a  patient with this story and ECG it would be a perfectly reasonable thing to do."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_062.png' OR image_url LIKE '%case_62.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 25-year-old black professional footballer. What does it show, and what would you do?","ecg_shows":"•\tSinus rhythm, rate 61/min •\tNormal axis •\tNormal QRS complexes •\tWidespread T wave inversion, particularly in leads V2–V5","clinical_interpretation":"Repolarization (T wave) abnormalities are quite common in black people, but  alternative explanations for this ECG appearance would be a non-ST segment  elevation myocardial infarction, or a cardiomyopathy.","what_to_do":"This man is a professional football player, so it is important to exclude hypertrophic  cardiomyopathy, and this can be done by echocardiography. Because his career  depended upon coronary disease being excluded, a coronary angiogram was per­ formed and was entirely normal.","summary":"Widespread T wave inversion, probably normal in a black man.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":61,"min":56,"max":66},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"This man is a professional football player, so it is important to exclude hypertrophic  cardiomyopathy, and this can be done by echocardiography. Because his career  depended upon coronary disease being excluded, a coronary angiogram was per­ formed and was entirely normal."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_063.png' OR image_url LIKE '%case_63.png';
UPDATE ecg_cases SET findings_json = '{"history":"These ECGs were recorded from a 20-year-old man who had had attacks of a fast and irregular heartbeat for several years. The upper trace was recorded when he was asymptomatic; the lower trace (rhythm strips only) was recorded during one of his attacks. What is the diagnosis and what would you do next?","ecg_shows":"","clinical_interpretation":"This is the Wolff–Parkinson–White (WPW) syndrome: the accessory pathway is on  the right side, and this is sometimes called ‘type B’. The irregular tachycardia is due  to atrial fibrillation.","what_to_do":"Atrial fibrillation in the WPW syndrome can lead to sudden death due to ventricular  fibrillation, so ablation of the abnormal pathway is needed urgently. Immediate  treatment of the atrial fibrillation should be by cardioversion if there is haemo­ dynamic compromise; otherwise flecaidine can be used. Digoxin, verapamil and  diltiazem should be avoided because these block the atrioventricular node and  encourage conduction through the accessory pathway.","summary":"The WPW syndrome type B.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":60,"max":100},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Atrial fibrillation in the WPW syndrome can lead to sudden death due to ventricular  fibrillation, so ablation of the abnormal pathway is needed urgently. Immediate  treatment of the atrial fibrillation should be by cardioversion if there is haemo­ dynamic compromise; otherwise flecaidine can be used. Digoxin, verapamil and  diltiazem should be avoided because these block the atrioventricular node and  encourage conduction through the accessory pathway."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_064.png' OR image_url LIKE '%case_64.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old woman is seen in the outpatient department, complaining of breathlessness. There are no abnormal physical findings. What does this ECG show, what might be the underlying problem, and how would you treat her?","ecg_shows":"•\tAtrial flutter, best seen in lead III •\t4 : 1 block •\tNormal axis •\tNormal QRS complexes •\tSloping ST segment depression, best seen in leads V5–V6","clinical_interpretation":"This shows atrial flutter with what appears to be a stable 4 : 1 block. The ST segment  depression suggests digoxin effect.","what_to_do":"The stable 4 : 1 block has caused a regular heartbeat, so the arrhythmia was not  suspected at the time of the clinical examination. There is nothing in this ECG to  indicate the underlying disease, which could be ischaemic, rheumatic or a cardio­ myopathy: echocardiography is needed. The downward-sloping ST segments suggest  digoxin treatment. Digoxin will tend to maintain a fairly high degree of block but  will not affect the underlying rhythm. Intravenous flecainide may convert the heart  to sinus rhythm, but DC cardioversion may be necessary.","summary":"Atrial flutter with 4 : 1 block.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The stable 4 : 1 block has caused a regular heartbeat, so the arrhythmia was not  suspected at the time of the clinical examination. There is nothing in this ECG to  indicate the underlying disease, which could be ischaemic, rheumatic or a cardio­ myopathy: echocardiography is needed. The downward-sloping ST segments suggest  digoxin treatment. Digoxin will tend to maintain a fairly high degree of block but  will not affect the underlying rhythm. Intravenous flecainide may convert the heart  to sinus rhythm, but DC cardioversion may be necessary."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_065.png' OR image_url LIKE '%case_65.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 30-year-old man at a medical examination required by the Civil Aviation Authority. Is it normal?","ecg_shows":"•\tSinus rhythm, rate 52/min •\tProminent U waves, especially in leads V2–V4","clinical_interpretation":"U waves can indicate hypokalaemia, but when associated with normal T waves (as  here) they are a normal variant.","what_to_do":"Provide reassurance – he is fit to fly.","summary":"Normal ECG, with prominent U waves.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":52,"min":48,"max":56},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Provide reassurance – he is fit to fly."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_066.png' OR image_url LIKE '%case_66.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded as part of the ‘screening’ examination of a young professional football player. Is it normal?","ecg_shows":"•\tRegular narrow complex rhythm at 35/min •\tP waves sometimes, but not always, visible just before the QRS complexes •\tPR interval, when measurable, is always short but varies •\tHeight of R wave in lead V4 plus depth of S wave in lead V2 = 49 mm •\tNormal QRS complexes and ST segments •\tPeaked T waves, especially in lead V4","clinical_interpretation":"The short PR interval raises the possibility of pre-excitation, but the interval varies,  and in the first complex of leads V1–V3 no P wave can be seen. The slow, narrow  complex rhythm suggests atrioventricular nodal escape. Here there is a pronounced  slowing of the sinoatrial node, presumably due to athletic training, and an acceler­ ated idionodal rhythm has taken over. This pattern used to be called a ‘wandering  atrial pacemaker’. The tall R waves are perfectly normal in young fit people, and  so are the peaked T waves.","what_to_do":"This is a normal variant in athletes, and no action is required.","summary":"Accelerated idionodal rhythm.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":35,"min":30,"max":40},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Peaked"},"management":{"urgency":"Routine","notes":"This is a normal variant in athletes, and no action is required."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_067.png' OR image_url LIKE '%case_67.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 45-year-old patient is admitted to the A & E department having had severe central chest pain for 1 h. There are no signs of heart failure, and this is his ECG. What does the ECG show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 100/min •\tLeft axis deviation •\tQ waves in leads V2–V4 •\tRaised ST segments in leads I, VL, V2–V5","clinical_interpretation":"This ECG shows left anterior hemiblock, with an acute ST segment elevation antero- lateral myocardial infarction (STEMI).","what_to_do":"Unless there are any potential risks of bleeding (previous stroke, peptic ulcer, dia­ betic retinopathy, etc.), this patient should be given aspirin, 300 mg to be chewed,  and immediate percutaneous coronary intervention (PCI), or immediate thromboly­ sis if PCI is not available.","summary":"Acute antero-lateral STEMI and left anterior hemiblock.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":100,"min":95,"max":105},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Unless there are any potential risks of bleeding (previous stroke, peptic ulcer, dia­ betic retinopathy, etc.), this patient should be given aspirin, 300 mg to be chewed,  and immediate percutaneous coronary intervention (PCI), or immediate thromboly­ sis if PCI is not available."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_068.png' OR image_url LIKE '%case_68.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old man, who had complained of palpitations for many years without anything abnormal being found, came to the A & E department during an attack, and this ECG was recorded. Apart from signs of marked anxiety there were no unusual findings except a heart rate of 140/min. What does the ECG show?","ecg_shows":"•\tNarrow complex tachycardia at 140/min •\tInverted P waves, most obvious in leads II, III, VF •\tShort PR interval (about 100 ms) •\tNormal axis •\tNormal QRS complexes, ST segments and T waves","clinical_interpretation":"The story of attacks of palpitations could indicate episodes of sinus tachycardia due  to anxiety, but the heart rate of 140/min suggests that a rhythm other than sinus  rhythm is likely. This ECG clearly shows a supraventricular tachycardia of some  sort, with one P wave per QRS complex. It could be sinus tachycardia, and the  short PR interval could indicate pre-excitation, but the abnormal P waves in the  inferior leads show that this is an atrial tachycardia.","what_to_do":"Carotid sinus massage may terminate the attack, but if not it will almost certainly  respond to adenosine. Further attacks may be prevented by a beta-blocker, but the  patient should be referred for an electrophysiological study in the hope that a  re-entry pathway can be identified and ablated.","summary":"Atrial tachycardia.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":140,"min":135,"max":145},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Inverted","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Carotid sinus massage may terminate the attack, but if not it will almost certainly  respond to adenosine. Further attacks may be prevented by a beta-blocker, but the  patient should be referred for an electrophysiological study in the hope that a  re-entry pathway can be identified and ablated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_069.png' OR image_url LIKE '%case_69.png';
UPDATE ecg_cases SET findings_json = '{"history":"A confused 80-year-old woman was sent to hospital from a nursing home because of a collapse. No other history was available, except that she was said to be having treatment for her heart. There were no obvious physical signs. The upper ECG was recorded on admission, and the lower ECG was recorded shortly afterwards. What is going on?","ecg_shows":"","clinical_interpretation":"In the upper trace the inferolateral Q waves could represent an old infarction, but  they are narrow and are probably septal in origin. The prolonged QT interval and  abnormal T waves suggest either an electrolyte abnormality or that the patient is  being treated with one of the many drugs that have these effects. A collapse in a  patient with an ECG with a long QT interval suggests episodes of torsade de pointes  ventricular tachycardia.","what_to_do":"The electrolyte levels, including magnesium, must be checked, and in this case were  found to be normal. It is essential immediately to establish what medication the  patient is taking, and pending that information it would be sensible to leave her  untreated and simply to monitor her for arrhythmias. It turned out that this woman  was taking sotalol – a beta-blocker with class III antiarrhythmic activity which is  known to cause QT interval prolongation. When this drug was stopped, her ECG  returned to normal.","summary":"Drug-induced QT interval prolongation and polymorphic ventricular tachycardia.","stars":3,"rhythm":{"regularity":"Irregular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":150,"min":140,"max":160},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The electrolyte levels, including magnesium, must be checked, and in this case were  found to be normal. It is essential immediately to establish what medication the  patient is taking, and pending that information it would be sensible to leave her  untreated and simply to monitor her for arrhythmias. It turned out that this woman  was taking sotalol – a beta-blocker with class III antiarrhythmic activity which is  known to cause QT interval prolongation. When this drug was stopped, her ECG  returned to normal."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_070.png' OR image_url LIKE '%case_70.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded as part of a routine health check on a 50-year-old woman who said she was asymptomatic. The only abnormality detected in the other usual screening tests was a serum cholesterol level of 7.2 mmol/l. What would you do?","ecg_shows":"•\tSinus rhythm, rate 45/min •\tNormal axis •\tNormal QRS complexes •\tWidespread T wave flattening and inversion •\tProminent U waves, especially in leads V2–V5","clinical_interpretation":"Flattened T waves with prominent U waves usually result from hypokalaemia. The  serum potassium level is usually checked during health screening, but the same ECG  changes can result from hypomagnesaemia; hypocalcaemia causes a long QT inter­ val but not U waves. A high cholesterol level can be a marker for coronary disease,  but elevated cholesterol levels can also be secondary to thyroid or renal disease.","what_to_do":"Check the thyroid function. This woman had myxoedema, and her ECG became  normal when it was treated.","summary":"Widespread T wave flattening with prominent U waves – classically due to  hypokalaemia, but in this case due to myxoedema.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":45,"min":40,"max":50},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Flattened"},"management":{"urgency":"Urgent","notes":"Check the thyroid function. This woman had myxoedema, and her ECG became  normal when it was treated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_071.png' OR image_url LIKE '%case_71.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from an asymptomatic 45-year-old man at a ‘health screening’ examination. Is it normal, and what advice would you give him?","ecg_shows":"•\tSinus rhythm, rate 64/min •\tProlonged PR interval (360 ms) •\tNormal QRS complexes, ST segments, and T waves","clinical_interpretation":"This ECG shows first degree atrioventricular block but is otherwise entirely normal.","what_to_do":"Although the upper limit of the PR interval is usually taken to be 220 ms, longer  durations (technically first degree block) are frequently seen in healthy people.  Provided you can be sure that this patient has no symptoms, and provided the  physical examination is normal, no further action is required. Some individuals in  occupations that require a totally normal ECG may have to have an ambulatory  ECG recording to demonstrate that there are no episodes of higher-degree block.","summary":"First degree atrioventricular block.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":64,"min":58,"max":68},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"1st Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Although the upper limit of the PR interval is usually taken to be 220 ms, longer  durations (technically first degree block) are frequently seen in healthy people.  Provided you can be sure that this patient has no symptoms, and provided the  physical examination is normal, no further action is required. Some individuals in  occupations that require a totally normal ECG may have to have an ambulatory  ECG recording to demonstrate that there are no episodes of higher-degree block."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_072.png' OR image_url LIKE '%case_72.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 80-year-old man is found at routine examination to have a slow heart rate and a harsh systolic murmur. This is his ECG. What does it show, and what is the likely diagnosis? Is treatment necessary?","ecg_shows":"•\tSinus rhythm, P wave rate 75/min •\tSecond degree (2 : 1) block •\tLeft axis deviation •\tQRS complex duration 140 ms, with an RSR1 pattern in lead V1, indicating  right bundle branch block (RBBB)","clinical_interpretation":"This is second degree block and not complete (third degree) block because the PR  interval in the conducted beats is normal: at times it appears to vary but in fact this  variation is due to lead changes (shown by the small spikes). Left axis deviation  (left anterior hemiblock) and RBBB constitute bifascicular block, but the 2 : 1 block  shows that there is also disease in either the His bundle or the remaining posterior  fascicle. This combination is sometimes called ‘trifascicular’ block.","what_to_do":"The combination of a heart murmur and heart block suggests aortic stenosis. The  severity of this can be assessed with echocardiography, though the slow rate (and  thus high stroke volume) will accentuate the recorded valve gradient. Aortic valve  replacement may or may not be needed, but the patient certainly needs a permanent  pacemaker to prolong his survival.","summary":"Second degree (2 : 1) block and trifascicular block.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"2:1","p_qrs_relation":"2:1","sa_block":"None"},"rate":{"target":37,"min":34,"max":42},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"2nd Degree Type II","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The combination of a heart murmur and heart block suggests aortic stenosis. The  severity of this can be assessed with echocardiography, though the slow rate (and  thus high stroke volume) will accentuate the recorded valve gradient. Aortic valve  replacement may or may not be needed, but the patient certainly needs a permanent  pacemaker to prolong his survival."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_073.png' OR image_url LIKE '%case_73.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old woman, who had been breathless for several months, was admitted to hospital with chest pain, and this is her ECG. What does it show and what would you do?","ecg_shows":"•\tAtrial fibrillation, with one ventricular extrasystole •\tVentricular rate about 110/min •\tNormal axis •\tNormal QRS complexes •\tHorizontal ST segment depression of 7 mm in lead V2 •\tDownward-sloping ST segment depression in leads V3–V6 •\tInverted T waves in leads I, VL, V6; indeterminate T waves elsewhere","clinical_interpretation":"The anterior horizontal ST segment depression indicates severe ischaemia, which is  presumably the cause of the chest pain. The downward-sloping ST segment in lead  V6 could be due to digoxin therapy. The ventricular rate is not too fast, and although  the heart rate may be contributing to the ischaemia it seems unlikely that it is the  main problem.","what_to_do":"The patient should be treated for an acute coronary syndrome with heparin, a beta- blocker and nitrates. If the pain does not settle, early angiography with a view to  revascularization by a coronary artery bypass graft (CABG) or percutaneous coro­ nary intervention (PCI) will have to be considered.","summary":"Atrial fibrillation and anterior ischaemia.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":110,"min":100,"max":120},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The patient should be treated for an acute coronary syndrome with heparin, a beta- blocker and nitrates. If the pain does not settle, early angiography with a view to  revascularization by a coronary artery bypass graft (CABG) or percutaneous coro­ nary intervention (PCI) will have to be considered."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_074.png' OR image_url LIKE '%case_74.png';
UPDATE ecg_cases SET findings_json = '{"history":"An elderly woman is admitted to hospital unconscious, evidently having had a stroke. No cardiac abnormalities are noted, but this is her ECG. What has been missed?","ecg_shows":"•\tNo P waves; irregular baseline suggesting atrial fibrillation •\tRegular QRS complexes; rate 73/min •\tLeft axis deviation •\tWide QRS complexes of an indeterminate pattern, with inverted T waves in  some leads •\tEach QRS complex is preceded by a deep and narrow spike","clinical_interpretation":"The narrow spike is due to a pacemaker, and someone has not noticed the perma­ nent pacing battery, which is probably below the left clavicle. The pacing wire will  be stimulating the right ventricle, giving rise to broad QRS complexes resembling  a bundle branch block pattern. The underlying rhythm here is atrial fibrillation: the  patient may have had atrial fibrillation with complete block, or there may simply  have been a slow ventricular response to the atrial fibrillation.","what_to_do":"The stroke may have been due to an embolus arising in the left heart as a result of  atrial fibrillation. There may have been temporary pacemaker failure, but probably  the stroke was not related to the pacemaker.","summary":"Ventricular-paced rhythm and atrial fibrillation.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":73,"min":70,"max":76},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"3rd Degree","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"The stroke may have been due to an embolus arising in the left heart as a result of  atrial fibrillation. There may have been temporary pacemaker failure, but probably  the stroke was not related to the pacemaker."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_075.png' OR image_url LIKE '%case_75.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old man is seen in the A & E department with left-sided chest pain that appears to be pleuritic in nature. What does his ECG show?","ecg_shows":"•\tSinus rhythm, rate 63/min •\tNormal axis •\tNormal QRS complexes •\tRaised ST segments in leads II, V3–V6, in each case preceded by an S wave","clinical_interpretation":"When a raised ST segment follows an S wave as shown here, it is called ‘high take- off’ of the ST segment. This is a normal variant, which must be distinguished from  the changes associated with an acute infarction or pericarditis.","what_to_do":"If the patient has chest pain that appears to be pleuritic, then pulmonary rather than  cardiac causes of pain should be considered – infection, pulmonary embolus and  pneumothorax. The ECG is completely unhelpful here.","summary":"Normal ECG showing ‘high take-off’ ST segment.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":63,"min":58,"max":68},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"If the patient has chest pain that appears to be pleuritic, then pulmonary rather than  cardiac causes of pain should be considered – infection, pulmonary embolus and  pneumothorax. The ECG is completely unhelpful here."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_076.png' OR image_url LIKE '%case_76.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man returned from holiday in Spain saying that while there he had had some bad indigestion, but was now perfectly well. This is his ECG: what does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 72/min •\tNormal conduction •\tNormal axis •\tQ waves in leads V2–V3 •\tElevated ST segments in leads V2–V4 •\tInverted T waves in leads VL, V1–V5","clinical_interpretation":"This ECG shows an old anterior myocardial infarction with lateral ischaemia. The  elevation of ST segments might suggest an acute process if the pain were recent, but  with this story the changes are almost certainly old. The persistence of ST segment  elevation in the anterior leads may be due to a left ventricular aneurysm.","what_to_do":"The assumption has to be that the ‘indigestion’ was actually a myocardial infarction.  Since he is now well, the important thing is to ensure that he takes the appropriate  steps to prevent a further attack – he must stop smoking and reduce weight if neces­ sary, and he should be treated with aspirin, a beta-blocker, an angiotensin-converting  enzyme inhibitor and a statin. In view of his age it might be worth doing an exercise  test to ensure that there is no evidence of ischaemia at a low workload – if there  were, an angiogram would be indicated.","summary":"Old anterior myocardial infarction.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":72,"min":67,"max":77},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"The assumption has to be that the ‘indigestion’ was actually a myocardial infarction.  Since he is now well, the important thing is to ensure that he takes the appropriate  steps to prevent a further attack – he must stop smoking and reduce weight if neces­ sary, and he should be treated with aspirin, a beta-blocker, an angiotensin-converting  enzyme inhibitor and a statin. In view of his age it might be worth doing an exercise  test to ensure that there is no evidence of ischaemia at a low workload – if there  were, an angiogram would be indicated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_077.png' OR image_url LIKE '%case_77.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from an asymptomatic 30-year-old man at a routine examination. Is it normal?","ecg_shows":"•\tSinus rhythm, rate 73/min •\tRight axis deviation (S wave bigger than R wave in lead I, large R wave in lead  VR, very small R wave and deep S wave in lead VL) •\tNotched QRS complexes in lead III •\tOtherwise entirely normal QRS complexes and T waves","clinical_interpretation":"Right axis deviation can be a feature of right ventricular hypertrophy, but in tall,  thin people it is a normal variant. The notched QRS complexes in lead III are  normal, though if present in all leads they could be the ‘J’ waves of hypothermia.","what_to_do":"Examine the patient and exclude right ventricular hypertrophy (you should have  done this before recording the ECG!).","summary":"Normal ECG with right axis deviation.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":73,"min":68,"max":78},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Examine the patient and exclude right ventricular hypertrophy (you should have  done this before recording the ECG!)."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_078.png' OR image_url LIKE '%case_78.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 70-year-old woman who had complained of attacks of dizziness for about a year. What is the problem, what might be its cause, and how should this woman be treated?","ecg_shows":"•\tSinus rhythm with complete (third degree) block, rate 55/min •\tNormal axis •\tNormal QRS complexes and T waves","clinical_interpretation":"This ECG shows complete heart block with a relatively low ventricular rate. The  attacks of dizziness may be due to further slowing of the heart rate. Although at  times there appears to be second degree (2 : 1) block, the lead II rhythm strip shows  that what could be the PR interval is continually changing, and that there is actually  no relationship between the P waves and QRS complexes. The QRS complex is  narrow, and so must originate in the His bundle.","what_to_do":"An ambulatory ECG, recorded over 24 h, may reveal the rhythm associated with  the dizziness – but whatever the findings, the patient needs a permanent pacemaker.  There are many causes of heart block, including ischaemia; association with aortic  valve calcification; Lyme disease (Borrelia burgdorferi); His bundle interruption (due  to surgery, trauma, parasites, tumours, abscesses, granulomata); and drugs (digoxin,  beta-blockers, calcium-channel blockers). However, most cases of heart block are  due to His bundle fibrosis, for which hypertension is a risk factor. An echocardio­ gram is necessary to study left ventricular function, and if this is impaired the patient  needs an angiotensin-converting enzyme inhibitor.","summary":"Complete (third degree) block.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":55,"min":50,"max":60},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"3rd Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"An ambulatory ECG, recorded over 24 h, may reveal the rhythm associated with  the dizziness – but whatever the findings, the patient needs a permanent pacemaker.  There are many causes of heart block, including ischaemia; association with aortic  valve calcification; Lyme disease (Borrelia burgdorferi); His bundle interruption (due  to surgery, trauma, parasites, tumours, abscesses, granulomata); and drugs (digoxin,  beta-blockers, calcium-channel blockers). However, most cases of heart block are  due to His bundle fibrosis, for which hypertension is a risk factor. An echocardio­ gram is necessary to study left ventricular function, and if this is impaired the patient  needs an angiotensin-converting enzyme inhibitor."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_079.png' OR image_url LIKE '%case_79.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded in the A & E department from a 60-year-old man who had had intermittent central chest pain for 24 h. What does it show and how should he be managed?","ecg_shows":"•\tSinus rhythm, rate 81/min •\tNormal conduction intervals •\tNormal axis •\tNormal QRS complexes •\tNormal ST segments, with ST segment depression in lead V4 •\tT wave inversion in leads VL, V2–V4","clinical_interpretation":"This ECG shows an anterior non-ST segment elevation myocardial infarction  (NSTEMI) of uncertain age.","what_to_do":"This patient clearly has an acute coronary syndrome. He must be admitted to hos­ pital and treated with low-molecular-weight heparin, a nitrate and a beta-blocker.  If the pain does not settle quickly, the use of a glycoprotein IIb/IIIa inhibitor such  as tirofiban or abciximab should be considered as a prelude to early percutaneous  coronary intervention (PCI).","summary":"Anterior NSTEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":81,"min":76,"max":86},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"This patient clearly has an acute coronary syndrome. He must be admitted to hos­ pital and treated with low-molecular-weight heparin, a nitrate and a beta-blocker.  If the pain does not settle quickly, the use of a glycoprotein IIb/IIIa inhibitor such  as tirofiban or abciximab should be considered as a prelude to early percutaneous  coronary intervention (PCI)."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_080.png' OR image_url LIKE '%case_80.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 25-year-old man, known to have a heart problem for which he had refused surgery, was admitted to hospital as an emergency because of palpitations. His heart rate was 170/min, his blood pressure was 140/80 and there were no signs of heart failure. What is the cardiac rhythm and what would you do?","ecg_shows":"•\tBroad complex tachycardia, rate 170/min •\tNo clear P waves but possibly some P waves visible in lead VR •\tNormal axis •\tRight bundle branch block (RBBB) pattern •\tHorizontal ST segment depression, best seen in lead V4","clinical_interpretation":"The QRS complex duration is 120 ms, the axis is normal, and the QRS complexes  show the classic RBBB pattern. It is likely that this is a supraventricular tachycardia  with RBBB, and this diagnosis would be certain if we were sure of the existence of  P waves in lead VR. This is either an atrial or an atrioventricular nodal re-entry  (junctional) tachycardia (AVNRT). The ST segment depression suggests  ischaemia.","what_to_do":"If the patient has an atrial septal defect, he is likely to have RBBB, and this could  be confirmed from pre-existing hospital records. The initial treatment is carotid  sinus massage, and if this proves ineffective, intravenous adenosine.","summary":"Supraventricular tachycardia (possibly atrial, possibly AVNRT) with RBBB;  atrial septal defect.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":170,"min":160,"max":180},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"If the patient has an atrial septal defect, he is likely to have RBBB, and this could  be confirmed from pre-existing hospital records. The initial treatment is carotid  sinus massage, and if this proves ineffective, intravenous adenosine."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_081.png' OR image_url LIKE '%case_81.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old woman, who had a baby 3 months previously, complains of breathlessness, and this is her ECG. What is the problem?","ecg_shows":"•\tSinus rhythm, rate 64/min •\tShort PR interval at 100 ms •\tNormal axis •\tNormal QRS complex duration •\tSlurred upstroke to QRS complexes (delta wave) •\tDominant R wave in lead V1 •\tNormal ST segments and T waves","clinical_interpretation":"This ECG shows the Wolff–Parkinson–White (WPW) syndrome type A, which is  characterized by a dominant R wave in lead V1.","what_to_do":"The catch here is that the dominant R wave in lead V1 may be mistakenly thought  to be due to right ventricular hypertrophy. In a young woman who complains of  breathlessness after a pregnancy, pulmonary embolism is obviously a possibility, and  this might well cause ECG evidence of right ventricular hypertrophy – but in the  presence of the WPW syndrome this would be very difficult to diagnose from the  ECG. The only thing that might help the diagnosis would be the appearance of right  axis deviation, which is not part of the WPW syndrome, and is not present here.  So, look for another cause of breathlessness, such as anaemia.","summary":"The WPW syndrome type A.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":64,"min":58,"max":70},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"The catch here is that the dominant R wave in lead V1 may be mistakenly thought  to be due to right ventricular hypertrophy. In a young woman who complains of  breathlessness after a pregnancy, pulmonary embolism is obviously a possibility, and  this might well cause ECG evidence of right ventricular hypertrophy – but in the  presence of the WPW syndrome this would be very difficult to diagnose from the  ECG. The only thing that might help the diagnosis would be the appearance of right  axis deviation, which is not part of the WPW syndrome, and is not present here.  So, look for another cause of breathlessness, such as anaemia."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_082.png' OR image_url LIKE '%case_82.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old man, who had had brief episodes of palpitations for at least 10 years, was seen during an attack in the A & E department and this is his ECG. What is the rhythm, and what would you do immediately, and in the long term?","ecg_shows":"•\tBroad complex tachycardia at about 230–240/min •\tNo P waves visible •\tRight axis deviation •\tQRS complex duration of about 180 ms •\tQRS complexes point upwards in lead V1 and downwards in lead V6 – no  concordance •\tQRS complex configuration characteristic of right bundle branch block – but in  lead V1 the first R wave peak is higher than the second peak","clinical_interpretation":"There are essentially three causes of a broad complex tachycardia: ventricular tachy­ cardia, supraventricular tachycardia with bundle branch block, and the Wolff– Parkinson–White (WPW) syndrome. The key to the diagnosis lies in the ECG when  the heart is in sinus rhythm, but this is not always available. Patients with a broad  complex tachycardia in the context of an acute myocardial infarction must be  assumed to have a ventricular tachycardia, but that does not apply here. In this  record the QRS complexes are not very broad, the axis is to the right, and there is  no concordance of the QRS complexes – all pointing to a supraventricular origin.  In favour of a ventricular tachycardia is the fact that the height of the primary R  wave in lead V1 is greater than that of the secondary R wave. However, taking these  features together with the clinical picture, the rhythm is probably supraventricular.","what_to_do":"Carotid sinus pressure is the first move. If there is severe haemodynamic compromise  the patient may need urgent electrical cardioversion, but intravenous flecainide  would be a reasonable first choice. In fact, in this case the arrhythmia terminated  spontaneously, revealing a short PR interval and a QRS complex with a delta wave.  So this patient had the WPW syndrome, and needed an electrophysiological study  with a view to ablation of the accessory tract.","summary":"Broad complex tachycardia (eventually shown to be due to the WPW syndrome).","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":235,"min":225,"max":245},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Carotid sinus pressure is the first move. If there is severe haemodynamic compromise  the patient may need urgent electrical cardioversion, but intravenous flecainide  would be a reasonable first choice. In fact, in this case the arrhythmia terminated  spontaneously, revealing a short PR interval and a QRS complex with a delta wave.  So this patient had the WPW syndrome, and needed an electrophysiological study  with a view to ablation of the accessory tract."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_083.png' OR image_url LIKE '%case_83.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 65-year-old woman with rheumatic heart disease, who had had severe heart failure for years, was admitted to hospital with increasing breathlessness and ankle swelling. Despite having been treated with angiotensin-converting enzyme inhibitors and diuretics, there was evidence of severe heart failure. Having seen the ECG and chest X-ray, what more do you want to know?","ecg_shows":"•\tUncertain rhythm – no P waves; irregular QRS complexes; but no ‘fibrillation’  activity •\tRight axis deviation •\tNormal QRS complexes except for a small Q wave in lead V1 and a deep S  wave in lead V6 •\tSymmetrically peaked T waves •\tInverted T waves in leads III, VF The X-ray shows the right lung base. There is interstitial pulmonary oedema and  ‘Kerley B’ lines (fluid in the lymphatics) can be seen, indicating left heart failure.","clinical_interpretation":"The absence of atrial activity and the peaked T waves are consistent with hyper­ kalaemia. The right axis deviation and deep S waves in lead V6 could indicate right  ventricular hypertrophy and could result from chronic lung disease. The inverted T  waves in leads III and VF suggest ischaemia.","what_to_do":"Find out what the patient’s medication has been and check her serum electrolyte  levels. This woman had been treated with a combination of captopril 25 mg, three  times daily (which tends to raise the serum potassium level) and three co-amilofruse  tablets per 24 h (furosemide 40 mg plus amiloride 5 mg in each tablet). The com­ bination of captopril and amiloride causes marked potassium retention, and in this  case the serum potassium level was 7.4 mmol/l. When the hyperkalaemia was corrected, sinus rhythm with clear P waves was  restored and the peaked T waves became normal. The right axis deviation, clockwise  rotation and inverted T waves in the inferior leads persisted.","summary":"Hyperkalaemia.","stars":3,"rhythm":{"regularity":"Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"Sinus Arrest"},"rate":{"target":70,"min":60,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"Sinus Arrest"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Peaked"},"management":{"urgency":"Emergency","notes":"Find out what the patient’s medication has been and check her serum electrolyte  levels. This woman had been treated with a combination of captopril 25 mg, three  times daily (which tends to raise the serum potassium level) and three co-amilofruse  tablets per 24 h (furosemide 40 mg plus amiloride 5 mg in each tablet). The com­ bination of captopril and amiloride causes marked potassium retention, and in this  case the serum potassium level was 7.4 mmol/l. When the hyperkalaemia was corrected, sinus rhythm with clear P waves was  restored and the peaked T waves became normal. The right axis deviation, clockwise  rotation and inverted T waves in the inferior leads persisted."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_084.png' OR image_url LIKE '%case_84.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 55-year-old man who was admitted to hospital as an emergency with severe central chest pain that had been present for about an hour. He was pale, cold and clammy; his blood pressure was 100/80, but there were no signs of heart failure. What does this ECG show? Does anything about it surprise you?","ecg_shows":"•\tSinus rhythm, rate 50/min •\tFirst degree block (PR interval 350 ms) •\tNormal axis •\tSmall Q waves in leads II, III, VF •\tRaised ST segments in leads II, III, VF •\tDepressed ST segments and inverted T waves in leads I, VL •\tSlight ST segment depression in the chest leads","clinical_interpretation":"Acute inferior ST segment elevation myocardial infarction (STEMI) with antero­ lateral ischaemia, and first degree block. Patients who are in pain with an acute  myocardial infarction usually have a sinus tachycardia, but here vagal overactivity  is causing a bradycardia.","what_to_do":"First degree block is not important in itself, but with evidence of vagal overactivity,  atropine should be given. Otherwise this patient can be treated in the usual way  with pain relief, aspirin, and percutaneous coronary intervention (PCI) or  thrombolytics.","summary":"Acute inferior STEMI with first degree block.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":50,"min":45,"max":55},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"1st Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"First degree block is not important in itself, but with evidence of vagal overactivity,  atropine should be given. Otherwise this patient can be treated in the usual way  with pain relief, aspirin, and percutaneous coronary intervention (PCI) or  thrombolytics."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_085.png' OR image_url LIKE '%case_85.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 35-year-old woman, who had had attacks of what sounded like a paroxysmal tachycardia for many years, was seen in the A & E department, and this ECG was recorded. What is the diagnosis?","ecg_shows":"•\tNarrow complex tachycardia at about 170/min •\tNo P waves visible •\tNormal axis •\tQRS complex duration 112 ms •\tSlurred upstroke to QRS complexes, best seen in leads V3–V6 •\tDepressed ST segments in leads V3–V6 •\tInverted T waves in the lateral leads","clinical_interpretation":"This is a narrow complex tachycardia, so it is supraventricular. The slurred upstroke  to the QRS complex suggests the Wolff–Parkinson–White (WPW) syndrome, so this  is a re-entry tachycardia, with depolarization spreading down the accessory pathway.  The absence of a dominant R wave in lead V1 indicates that this is WPW syndrome  type B. This diagnosis is consistent with the patient’s history.","what_to_do":"Carotid sinus pressure is always the first thing to try in patients with a supravent­ ricular tachycardia. In most such patients, adenosine is the first drug to use, but in  cases of the WPW syndrome it must be used with caution. It can block the atrio­ ventricular node and increase conduction through the accessory pathway, and if  atrial fibrillation is present this can lead to ventricular fibrillation. Digoxin, verap­ amil and lidocaine can have the same effect. The safe drugs in this situation are the  beta-blockers, flecainide and amiodarone.","summary":"Supraventricular tachycardia and the WPW syndrome type B.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":170,"min":160,"max":180},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Carotid sinus pressure is always the first thing to try in patients with a supravent­ ricular tachycardia. In most such patients, adenosine is the first drug to use, but in  cases of the WPW syndrome it must be used with caution. It can block the atrio­ ventricular node and increase conduction through the accessory pathway, and if  atrial fibrillation is present this can lead to ventricular fibrillation. Digoxin, verap­ amil and lidocaine can have the same effect. The safe drugs in this situation are the  beta-blockers, flecainide and amiodarone."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_086.png' OR image_url LIKE '%case_86.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man complains of pain in the front of his chest, which is predictably induced by walking uphill, especially in cold weather. The pain is sometimes caused by excitement. He has never had any pain without some precipitating cause. The upper ECG shows a recording made at rest, and the lower record comes from his exercise test, after 5 min of the Bruce protocol. What do the ECGs show?","ecg_shows":"","clinical_interpretation":"The T wave changes are very nonspecific, and the trace could well be normal.  However, since the patient’s story is highly suggestive of angina, an exercise test is  necessary. Exercise test The lower ECG shows: •\tSinus rhythm with a rate of about 110/min •\tST segment depression in leads V2–V4, with a maximum in lead V3 •\tST segment elevation in leads II, III, VF Clinical interpretation The ST segment depression in leads V2–V4 is upward-sloping, so does not allow a  confident diagnosis of ischaemia. The ST segment elevation in leads II, III and VF  is suggestive of an acute inferior myocardial infarction. In this case, the ST segment  elevation cleared immediately on resting – elevation like this is an occasional mani­ festation of ischaemia rather than infarction.","what_to_do":"The patient’s angina can be treated medically in the usual way. He needs long-term  management with aspirin, and probably a statin and an angiotensin-converting  enzyme inhibitor, and risk factors must be addressed. Since the exercise test was  positive at a low exercise level, a coronary angiogram is indicated.","summary":"Normal ECG at rest; ST segment elevation on exercise.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":60,"max":100},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The patient’s angina can be treated medically in the usual way. He needs long-term  management with aspirin, and probably a statin and an angiotensin-converting  enzyme inhibitor, and risk factors must be addressed. Since the exercise test was  positive at a low exercise level, a coronary angiogram is indicated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_087.png' OR image_url LIKE '%case_87.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man, who had been well apart from mild breathlessness on exertion, was admitted to hospital with the sudden onset of pulmonary oedema, and this is his ECG. He had no pain. What is the rhythm, and how would you treat him?","ecg_shows":"•\tBroad complex rhythm at 120/min •\tNo P waves •\tLeft axis deviation •\tQRS complex duration 200 ms •\tQRS complexes show a right bundle branch block (RBBB) configuration •\tQRS complexes in the anterior leads are not concordant","clinical_interpretation":"The very broad QRS complexes and left axis deviation suggest that this is a vent­ ricular tachycardia. However, the lack of concordance (i.e. the QRS complexes in  leads V1–V3 are upright, while those in leads V5–V6 are predominantly downward)  and the RBBB pattern, with the secondary R wave peak taller than the primary  peak, suggest that this could be a supraventricular rhythm with bundle branch  block. Comparison with the patient’s ECG when in sinus rhythm is the only way  of being certain what the rhythm is.","what_to_do":"If the patient has pulmonary oedema, preparations for DC cardioversion should be  made immediately. While waiting for this he should be treated with diamorphine,  intravenous diuretics and lidocaine or intravenous amiodarone. The ECG following  cardioversion is shown in the next example (ECG 89).","summary":"Broad complex tachycardia of uncertain aetiology.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":120,"min":115,"max":125},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"If the patient has pulmonary oedema, preparations for DC cardioversion should be  made immediately. While waiting for this he should be treated with diamorphine,  intravenous diuretics and lidocaine or intravenous amiodarone. The ECG following  cardioversion is shown in the next example (ECG 89)."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_088.png' OR image_url LIKE '%case_88.png';
UPDATE ecg_cases SET findings_json = '{"history":"This is another ECG from the 60-year-old man who was admitted to hospital with a broad complex tachycardia (see the previous example – ECG 88). This ECG was recorded after cardioversion, when he was well. His serum troponin level remained normal following admission, so he had not had a myocardial infarction. How would you report on this ECG, and what do you think the underlying disease is?","ecg_shows":"•\tSinus rhythm, rate 63/min •\tFirst degree block (PR interval 220 ms) •\tNormal axis •\tBroad QRS complexes (200 ms) •\tLeft bundle branch block (LBBB)","clinical_interpretation":"Comparison with this patient’s previous ECG (see ECG 88) shows that when he  had the tachycardia there was a change in axis and in QRS complex configuration.  The broad complex tachycardia was therefore almost certainly ventricular in origin.  He now has evidence of conduction tissue disease, with first degree block and LBBB.  Since chest pain has not been a feature of his illness, it seems likely that he has a  dilated cardiomyopathy.","what_to_do":"If after treatment with an angiotensin-converting enzyme inhibitor and amiodarone  the patient has another episode of ventricular tachycardia, an implanted defibrillator  may be needed.","summary":"First degree block and LBBB.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":63,"min":58,"max":68},"conduction":{"pr_interval":240,"pr_category":"Prolonged","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"1st Degree","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"If after treatment with an angiotensin-converting enzyme inhibitor and amiodarone  the patient has another episode of ventricular tachycardia, an implanted defibrillator  may be needed."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_089.png' OR image_url LIKE '%case_89.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 50-year-old man admitted to hospital following 2 h of central chest pain that was characteristic of a myocardial infarction. His ECG had been normal 6 months ago. What does this record show and what would you do?","ecg_shows":"•\tSinus rhythm, rate about 107/min •\tVentricular extrasystoles •\tNormal axis •\tWide QRS complexes, with ‘M’ pattern in lead V6, and inverted T waves in  leads I, VL, V5–V6 – indicating left bundle branch block (LBBB) in the sinus  beats","clinical_interpretation":"The ventricular extrasystoles can be identified because they have a different mor­ phology from the LBBB pattern, and because they have no preceding P waves. LBBB  masks any changes there might be as the result of a myocardial infarction.","what_to_do":"The LBBB has evidently developed in the last 6 months, and the history suggests a  myocardial infarction. Provided there are no contraindications, percutaneous coro­ nary intervention (PCI) or a thrombolytic agent is indicated. The ventricular extra­ systoles should not be treated.","summary":"Sinus rhythm with LBBB and ventricular extrasystoles.","stars":3,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":107,"min":102,"max":112},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The LBBB has evidently developed in the last 6 months, and the history suggests a  myocardial infarction. Provided there are no contraindications, percutaneous coro­ nary intervention (PCI) or a thrombolytic agent is indicated. The ventricular extra­ systoles should not be treated."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_090.png' OR image_url LIKE '%case_90.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man was admitted to hospital as an emergency, having had central chest pain for 1 h. By the time he was seen in the A & E department he was pain-free and there were no abnormalities on examination. This is his ECG. What does it show, and what would you do?","ecg_shows":"•\tSinus rhythm, average rate 75/min, with one supraventricular extrasystole; there  appears to be an abnormal P wave in lead V1, so the extrasystole is atrial in  origin •\tNormal axis •\tNormal QRS complexes •\tInverted T waves in leads VL, V1–V6","clinical_interpretation":"There are many causes of inverted T waves, and ECGs should always be interpreted  as part of the overall clinical picture. In this case the history suggests a myocardial  infarction, and the ECG is characteristic of an acute anterior non-ST segment eleva­ tion myocardial infarction (NSTEMI).","what_to_do":"The immediate risk is low and there is no evidence for the likelihood of benefit from  thrombolysis. Although the patient is now asymptomatic he should remain in hos­ pital for observation and the plasma troponin level should be checked 12 h after  the onset of pain. The risk of reinfarction in the next 3 months is relatively high  compared with the risk following an ST segment elevation myocardial infarction,  and coronary angiography is needed.","summary":"Anterolateral NSTEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"The immediate risk is low and there is no evidence for the likelihood of benefit from  thrombolysis. Although the patient is now asymptomatic he should remain in hos­ pital for observation and the plasma troponin level should be checked 12 h after  the onset of pain. The risk of reinfarction in the next 3 months is relatively high  compared with the risk following an ST segment elevation myocardial infarction,  and coronary angiography is needed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_091.png' OR image_url LIKE '%case_91.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded as part of the routine preoperative assessment of a 65-year-old man who had no cardiovascular symptoms, and whose heart was clinically normal. What does it show? Is any action necessary?","ecg_shows":"•\tSinus rhythm, rate 50/min •\tNormal axis •\tQRS complex duration 110 ms, with an RSR1 pattern in leads V1 and V2 –  partial right bundle branch block (RBBB)","clinical_interpretation":"The QRS complex duration is at the upper limit of normal, so this is partial rather  than complete RBBB. It is seldom of any clinical significance.","what_to_do":"In the absence of symptoms or abnormal signs, no action is necessary.","summary":"Partial RBBB.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":50,"min":46,"max":55},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"In the absence of symptoms or abnormal signs, no action is necessary."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_092.png' OR image_url LIKE '%case_92.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 50-year-old man who had had severe chest pain for 1 h. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 70/min, with ventricular extrasystoles •\tNormal axis •\tQ waves in leads V3–V5; small Q waves in leads VL and V6 •\tRaised ST segments in leads I, VL, V3–V6 •\tDepressed ST segments in leads III, VF","clinical_interpretation":"Ventricular extrasystoles associated with an acute anterolateral ST segment eleva­ tion myocardial infarction (STEMI).","what_to_do":"The patient should be given diamorphine and aspirin immediately, and percutaneous  coronary intervention (PCI) or thrombolysis as soon as possible. The extrasystoles  should not be treated.","summary":"Acute anterolateral STEMI with ventricular extrasystoles.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The patient should be given diamorphine and aspirin immediately, and percutaneous  coronary intervention (PCI) or thrombolysis as soon as possible. The extrasystoles  should not be treated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_093.png' OR image_url LIKE '%case_93.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 30-year-old man who complained of chest pain: the pain did not appear to be cardiac in origin, and the physical examination was normal. Can this man be allowed to hold a commercial driving licence?","ecg_shows":"•\tSinus rhythm, rate 62/min •\tNormal axis •\tSmall Q waves, especially prominent in leads II, III, VF, V4–V6 •\tOtherwise normal QRS complexes, ST segments and T waves","clinical_interpretation":"These Q waves are quite deep but only 40 ms in duration, and they are most promi­ nent in the lateral leads. They represent septal depolarization, not an old lateral  infarction.","what_to_do":"The ECG is normal, and if the man has no other evidence of heart disease he  can hold a commercial driving licence. If in doubt, an exercise test should be  performed.","summary":"Normal ECG.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":62,"min":58,"max":68},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"The ECG is normal, and if the man has no other evidence of heart disease he  can hold a commercial driving licence. If in doubt, an exercise test should be  performed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_094.png' OR image_url LIKE '%case_94.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from an 80-year-old woman who had been found unconscious with physical signs suggesting a stroke. Any comments?","ecg_shows":"•\tAtrial fibrillation with a ventricular rate of about 55/min •\tQRS complex duration prolonged at 200 ms •\tProminent ‘J’ waves, best seen in leads V3–V6 •\tWidespread but nonspecific ST segment/T wave changes","clinical_interpretation":"The atrial fibrillation may or may not be related to her stroke – she may have had  a cerebral embolus, or she may have both coronary and cerebrovascular disease.  The slow ventricular rate and the ‘J’ waves indicate hypothermia, and her core  temperature was 25°C. ECGs from hypothermic patients seldom show ‘J’ waves as  clearly as this because there are too many artefacts due to shivering – but this patient  was too cold to shiver. She did not survive.  See p.317, 6E","what_to_do":"","summary":"Atrial fibrillation and hypothermia.","stars":3,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":55,"min":48,"max":60},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":""},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_095.png' OR image_url LIKE '%case_95.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 32-year-old woman, who had had a normal pregnancy and delivery 3 months previously, was seen in the outpatient department complaining of severe breathlessness and dizziness on exertion. She had some chest pain on both sides, which sounded pleuritic. Does her ECG help with her diagnosis and treatment? A pulmonary angiogram was performed as part of a series of investigations.","ecg_shows":"•\tSinus rhythm, rate 79/min •\tRight axis deviation •\tNormal QRS complexes, except for an RSR1 pattern in lead V1 and deep  S waves in lead V6 •\tInverted T waves in leads V1–V4 The pulmonary angiogram shows clots within the main pulmonary arteries. The  right mid-zone is perfused, but the rest of the lung fields have poor or no perfusion  due to multiple pulmonary emboli.","clinical_interpretation":"The right axis deviation, the deep S waves in lead V6 (‘clockwise rotation’) and the  inverted T waves in the chest leads are all characteristic of marked right ventricular  hypertrophy: the only missing feature is the absence of dominant R waves in lead  V1. Note how the T wave inversion is at a maximum in lead V1 and becomes pro­ gressively less marked from lead V2 to V4.","what_to_do":"In the context of a delivery 3 months previously, this ECG pattern of right ventri­ cular hypertrophy almost certainly indicates multiple pulmonary emboli causing  pulmonary hypertension. The pulmonary angiogram confirms this diagnosis. Anti­ coagulants, and possibly thrombolysis, are needed urgently.","summary":"Right ventricular hypertrophy due to pulmonary embolism.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":79,"min":74,"max":84},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"In the context of a delivery 3 months previously, this ECG pattern of right ventri­ cular hypertrophy almost certainly indicates multiple pulmonary emboli causing  pulmonary hypertension. The pulmonary angiogram confirms this diagnosis. Anti­ coagulants, and possibly thrombolysis, are needed urgently."},"qrs_morph":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_096.png' OR image_url LIKE '%case_96.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a fit 60-year-old man at a routine medical examination. What does it show and what would you recommend?","ecg_shows":"•\tSinus rhythm, rate 65/min •\tNormal PR interval •\tLeft axis deviation – left anterior hemiblock •\tQRS complex duration just over 120 ms, with an RSR1 complex in lead V1 –  right bundle branch block (RBBB)","clinical_interpretation":"The combination of left anterior hemiblock and RBBB is called bifascicular block.  Atrioventricular conduction occurs via the posterior fascicle of the left bundle  branch.","what_to_do":"Progression to complete block can occur but is relatively rare. In the absence of  symptoms, standard UK practice would be not to insert a permanent pacemaker;  however, any symptoms suggestive of a bradycardia should be investigated  immediately.","summary":"Left axis deviation and RBBB – bifascicular block.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":65,"min":60,"max":70},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Progression to complete block can occur but is relatively rare. In the absence of  symptoms, standard UK practice would be not to insert a permanent pacemaker;  however, any symptoms suggestive of a bradycardia should be investigated  immediately."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_097.png' OR image_url LIKE '%case_97.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded as part of a routine examination of a healthy 25-year-old professional athlete. There were no abnormal physical findings. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, average rate 44/min •\tNormal axis •\tNormal QRS complexes, apart from narrow Q waves in lead VL •\tMarked T wave inversion in leads I, VL, V2–V6","clinical_interpretation":"If this ECG had been recorded from a middle-aged man presenting with acute chest  pain, the diagnosis would be an anterior non-ST segment elevation myocardial  infarction. The ECGs of athletes can show ST segment and T wave changes due to  left vent­ricular hypertrophy, but anteroseptal T wave inversion of this degree in a  healthy young man almost certainly represents hypertrophic cardiomyopathy.","what_to_do":"Echocardiography will confirm the diagnosis. Ambulatory ECG recording will show  whether the patient is having ventricular arrhythmias. He must not play competitive  sports, and his close relatives should be screened.","summary":"Probable hypertrophic cardiomyopathy.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":44,"min":40,"max":50},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Echocardiography will confirm the diagnosis. Ambulatory ECG recording will show  whether the patient is having ventricular arrhythmias. He must not play competitive  sports, and his close relatives should be screened."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_098.png' OR image_url LIKE '%case_98.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 45-year-old man, who had been admitted to a coronary care unit with a myocardial infarction and who was recovering well. What is the rhythm, and what would you do?","ecg_shows":"•\tBroad complex rhythm, rate 90/min •\tNo P waves •\tMarked left axis deviation •\tQRS complex duration 160 ms •\tAll chest leads show a downward QRS complex (concordance)","clinical_interpretation":"If the heart rate were fast there would be little difficulty in recognizing this as vent­ ricular tachycardia, and this rhythm used to be called ‘slow VT’. It is, however, an  accelerated idioventricular rhythm.","what_to_do":"This rhythm is quite commonly seen in patients with an acute myocardial infarction,  and indeed is not uncommon in ambulatory ECG records from normal people. It  never causes problems, and it is important not to attempt to treat it: suppressing  any ‘escape’ rhythm may lead to a dangerous bradycardia.","summary":"Accelerated idioventricular rhythm.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":90,"min":85,"max":95},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"This rhythm is quite commonly seen in patients with an acute myocardial infarction,  and indeed is not uncommon in ambulatory ECG records from normal people. It  never causes problems, and it is important not to attempt to treat it: suppressing  any ‘escape’ rhythm may lead to a dangerous bradycardia."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_099.png' OR image_url LIKE '%case_99.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 40-year-old man who had hypertension but was otherwise well and ran marathons. Despite showing four possible ‘abnormalities’, is the trace actually normal?","ecg_shows":"•\tSinus rhythm, average rate 39/min •\tBifid P waves, best seen in the anterior chest leads •\tNormal axis •\tQRS complexes show left ventricular hypertrophy on voltage criteria (R wave in  lead V4 = 25 mm) •\tPeaked T waves","clinical_interpretation":"Sinus bradycardia can be due to physical fitness, vagal overactivity or myxoedema.  In a hypertensive patient, beta-blocker treatment is a possible explanation. The bifid  P waves may indicate left atrial hypertrophy (‘P mitrale’), but can be normal. Voltage  criteria for left ventricular hypertrophy are extremely unreliable when there is no  other evidence of this. The peaked T waves could be due to hyperkalaemia but are  more often a normal variant.","what_to_do":"All these possible abnormalities are seen in normal athletes, and the likelihood is  that they are of no significance. In a patient with hypertension, beta-blocker treat­ ment could be the cause of the bradycardia.","summary":"Normal ECG for an athlete.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":39,"min":35,"max":45},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Bifid (Mitrale)","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Peaked"},"management":{"urgency":"Routine","notes":"All these possible abnormalities are seen in normal athletes, and the likelihood is  that they are of no significance. In a patient with hypertension, beta-blocker treat­ ment could be the cause of the bradycardia."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_100.png' OR image_url LIKE '%case_100.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 48-year-old man is seen in the A & E department with a history of severe chest pain which began 24 h previously, but has now cleared. He is now breathless. What does this ECG show and what treatment is needed?","ecg_shows":"•\tSinus rhythm, rate 103/min •\tNormal axis •\tNormal QRS complexes •\tRaised ST segments in leads I, VL, V1–V6","clinical_interpretation":"The ECG has the classic appearance of an acute anterolateral ST segment elevation  myocardial infarction (STEMI).","what_to_do":"Since this patient’s chest pain began more than 24 h ago, immediate percutaneous  coronary intervention (PCI) or thrombolysis is not indicated. The breathlessness  suggests that he may have developed left ventricular failure, and he must be admit­ ted to hospital and treated with diuretics and if necessary intravenous nitrates to  induce vasodilation. The patient will need long-term treatment with an angiotensin- converting enzyme inhibitor: the best time to begin treatment is a matter for debate  but it should be within 2 or 3 days of the onset of the infarction. He will also need  long-term treatment with aspirin, as a prophylactic against further infarction.","summary":"Acute anterolateral STEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":103,"min":98,"max":108},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Since this patient’s chest pain began more than 24 h ago, immediate percutaneous  coronary intervention (PCI) or thrombolysis is not indicated. The breathlessness  suggests that he may have developed left ventricular failure, and he must be admit­ ted to hospital and treated with diuretics and if necessary intravenous nitrates to  induce vasodilation. The patient will need long-term treatment with an angiotensin- converting enzyme inhibitor: the best time to begin treatment is a matter for debate  but it should be within 2 or 3 days of the onset of the infarction. He will also need  long-term treatment with aspirin, as a prophylactic against further infarction."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_101.png' OR image_url LIKE '%case_101.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old woman, admitted to hospital because of increasing heart failure of uncertain cause, collapsed and was found to have a very rapid pulse and a low blood pressure. This is her ECG. She recovered spontaneously. What is this rhythm, and what would you do?","ecg_shows":"•\tBroad complex tachycardia at about 188/min •\tNo P waves visible •\tLeft axis deviation •\tQRS complex duration about 140 ms •\tNarrow fourth and fifth QRS complexes •\tQRS complexes that are probably concordant (in the chest leads all point  upwards) though it is difficult to be certain","clinical_interpretation":"Broad complex tachycardias may be ventricular, supraventricular with bundle  branch block, or due to the Wolff–Parkinson–White syndrome. We have no ECG  from this patient recorded in sinus rhythm, which is always the most helpful thing  in deciding between these possibilities. The complexes are not very wide, which  would be consistent with a supraventricular origin with aberrant conduction, but  the left axis deviation and (probable) concordance point to ventricular tachycardia.  The key is the two narrow complexes near the beginning of the record: these are  slightly early and are probably capture beats. They indicate that with an early  supraventricular beat the conducting system can function normally; by implication,  the broad complexes must be due to ventricular tachycardia.","what_to_do":"An elderly patient with heart failure is more likely to have ischaemic disease than  anything else, but all the possible causes of heart failure must be considered. The  sudden onset of an arrhythmia could be due to a myocardial infarction. Pulmonary  emboli can cause sudden arrhythmias, though these are more often supraventricular  than ventricular. It is important to consider whether this rhythm change is related  to treatment, in which case it could be due to an electrolyte imbalance or to the  pro-arrhythmic effect of a drug the patient is taking.","summary":"Ventricular tachycardia.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":188,"min":180,"max":195},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"An elderly patient with heart failure is more likely to have ischaemic disease than  anything else, but all the possible causes of heart failure must be considered. The  sudden onset of an arrhythmia could be due to a myocardial infarction. Pulmonary  emboli can cause sudden arrhythmias, though these are more often supraventricular  than ventricular. It is important to consider whether this rhythm change is related  to treatment, in which case it could be due to an electrolyte imbalance or to the  pro-arrhythmic effect of a drug the patient is taking."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_102.png' OR image_url LIKE '%case_102.png';
UPDATE ecg_cases SET findings_json = '{"history":"This is the ECG from a 25-year-old man who complained of episodes of fast, regular, palpitations associated with breathlessness and dizziness. There were no abnormalities on examination other than a slow and irregular pulse. What is the diagnosis and how can his problem be treated?","ecg_shows":"•\tVariable QRS complex rate, average 31/min •\tNormal P waves in the first three beats; in the fourth beat the P wave  immediately follows the QRS complex •\tNormal QRS complexes and T waves","clinical_interpretation":"This is the ‘sick sinus syndrome’ or ‘sinoatrial disease’. The record shows sinus  rhythm with a junctional escape beat, in which the atrium is activated retrogradely.  The palpitations described by the patient are probably due to a paroxysmal supra­ ventricular tachycardia, so he probably has the ‘bradycardia–tachycardia’ variant  of sinoatrial disease.","what_to_do":"Ambulatory ECG recording will confirm the cause of the patient’s palpitations. Even  though his bradycardia is asymptomatic, he will need a permanent pacemaker  because antiarrhythmic agents given for the tachycardia may make his bradycardia  worse.","summary":"Sinoatrial disease with sinus rhythm and a junctional escape beat.","stars":3,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"Sinus Arrest"},"rate":{"target":31,"min":25,"max":38},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"Sinus Arrest"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Ambulatory ECG recording will confirm the cause of the patient’s palpitations. Even  though his bradycardia is asymptomatic, he will need a permanent pacemaker  because antiarrhythmic agents given for the tachycardia may make his bradycardia  worse."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_103.png' OR image_url LIKE '%case_103.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from an 80-year-old man during a routine preoperative assessment. What does it show? What are the implications for surgery?","ecg_shows":"•\tSinus rhythm, rate about 77/min, with ventricular extrasystoles •\tVentricular extrasystoles are of two types, seen best in lead V3 •\tNormal axis •\tNormal QRS complexes in the sinus beats •\tST segments and T waves are normal in the sinus beats","clinical_interpretation":"Sinus rhythm, with multifocal ventricular extrasystoles but otherwise normal.","what_to_do":"In large groups of patients, ventricular extrasystoles are correlated with heart disease  of all types. In individuals, however, extrasystoles may well occur in a perfectly  normal heart – indeed, virtually everyone has extrasystoles at times. Ventricular  extrasystoles become more common with increasing age, and this patient is 80 years  old. In the absence of symptoms or clinical signs suggesting cardiovascular disease,  the extrasystoles do not have any great significance and should not materially affect  the patient’s fitness for surgery. They should not be treated.","summary":"Sinus rhythm with multifocal ventricular extrasystoles.","stars":1,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":77,"min":72,"max":82},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"In large groups of patients, ventricular extrasystoles are correlated with heart disease  of all types. In individuals, however, extrasystoles may well occur in a perfectly  normal heart – indeed, virtually everyone has extrasystoles at times. Ventricular  extrasystoles become more common with increasing age, and this patient is 80 years  old. In the absence of symptoms or clinical signs suggesting cardiovascular disease,  the extrasystoles do not have any great significance and should not materially affect  the patient’s fitness for surgery. They should not be treated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_104.png' OR image_url LIKE '%case_104.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man was admitted to hospital as an emergency with chest pain; he was not aware of a rapid heart rate. He had had several episodes of pain that appeared to be due to ischaemia, but they had no clear relationship with exertion. Shortly after this ECG was recorded, his heart rate suddenly slowed and his ECG was then normal. What does this record show, and what would you do?","ecg_shows":"•\tNarrow complex tachycardia, rate about 230/min •\tNo P waves •\tNormal axis •\tNormal QRS complexes •\tHorizontal ST segment depression, most marked in leads V4–V6","clinical_interpretation":"Narrow complex tachycardia without P waves – atrioventricular nodal re-entry  (junctional) tachycardia (AVNRT). Ischaemic ST segment depression, accounting  for his pain.","what_to_do":"Not all patients with a paroxysmal tachycardia complain of palpitations; this  patient’s recurrent chest pain may well have been due to this arrhythmia. He should  be taught the methods of inducing vagal activity, but prophylactic drug therapy will  be needed: a beta-blocker or verapamil should be tried first. Electrophysiological  investigation, with a view to ablating an abnormal pathway, may be needed.","summary":"Atrioventricular nodal re-entry (junctional) tachycardia (AVNRT) with ischaemia.","stars":1,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":230,"min":220,"max":240},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Not all patients with a paroxysmal tachycardia complain of palpitations; this  patient’s recurrent chest pain may well have been due to this arrhythmia. He should  be taught the methods of inducing vagal activity, but prophylactic drug therapy will  be needed: a beta-blocker or verapamil should be tried first. Electrophysiological  investigation, with a view to ablating an abnormal pathway, may be needed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_105.png' OR image_url LIKE '%case_105.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 40-year-old man is seen in the outpatient department with a history that suggests a myocardial infarction 3 weeks previously. There are no abnormalities on examination, and this is his ECG. There are two possible explanations for the abnormality it shows, though only one of these would explain his history. What is the likely diagnosis?","ecg_shows":"•\tSinus rhythm, rate 71/min •\tNormal axis •\tDominant R waves in lead V1 •\tST segment depression in leads V2–V3 •\tNonspecific T wave flattening in leads I, VL","clinical_interpretation":"The dominant R waves in lead V1 might indicate right ventricular hypertrophy, but  there are none of the other features that would be associated with this – right axis  deviation, and T wave inversion in leads V1, V2 and possibly V3. The changes are  therefore probably due to a posterior myocardial infarction, which would fit the  history of chest pain 3 weeks previously.","what_to_do":"It is important not to miss a diagnosis of pulmonary embolism. The patient should  be re-examined to ensure that there is no clinical evidence of right ventricular  hypertrophy. A chest X-ray examination should be carried out, and an echocardio­ gram may be helpful.","summary":"Probable posterior myocardial infarction.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":71,"min":66,"max":76},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Flattened"},"management":{"urgency":"Urgent","notes":"It is important not to miss a diagnosis of pulmonary embolism. The patient should  be re-examined to ensure that there is no clinical evidence of right ventricular  hypertrophy. A chest X-ray examination should be carried out, and an echocardio­ gram may be helpful."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_106.png' OR image_url LIKE '%case_106.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 60-year-old man with no symptoms, who wanted a private pilot’s licence. Is the","ecg_shows":"•\tSinus rhythm, rate 88/min •\tNormal conduction •\tNormal axis •\tQ wave in lead III but not in lead VF •\tInverted T wave in lead III but not in lead VF •\tU waves in leads V2–V3 (normal)","clinical_interpretation":"A Q wave and/or an inverted T wave in lead III, but not in lead VF, is a normal  variant. If lead III is recorded with the patient taking a deep breath in, the changes  will often normalize as shown below. Inspiration III","what_to_do":"","summary":"Normal record with Q waves and inverted T waves in lead III.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":88,"min":82,"max":94},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":""},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_107.png' OR image_url LIKE '%case_107.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 55-year-old black woman who had been complaining for several years of chest pain, and was admitted to hospital with persistent pain that was not characteristic of ischaemia. How would you have managed her?","ecg_shows":"•\tSinus rhythm, rate 60/min •\tNormal axis •\tNormal QRS complexes; variation in the complexes in lead V6 is probably due  to an artefact •\tT wave inversion in leads I, VL, V2–V6","clinical_interpretation":"With this history, an anterolateral non-ST segment elevation myocardial infarction  has to be the first diagnosis, but T wave ‘abnormalities’ are common in black people,  and this ECG could be normal.","what_to_do":"In this patient the diagnosis of an acute infarction was excluded when the plasma  troponin levels were found to be normal. An exercise test was performed, but was  limited by breathlessness without further ECG change. A coronary angiogram was  completely normal. The chest pain was therefore thought to be musculoskeletal in  origin, and the T wave changes were presumably due to her ethnicity.","summary":"Widespread T wave ‘abnormalities’, normal in a black woman.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":60,"min":55,"max":65},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"In this patient the diagnosis of an acute infarction was excluded when the plasma  troponin levels were found to be normal. An exercise test was performed, but was  limited by breathlessness without further ECG change. A coronary angiogram was  completely normal. The chest pain was therefore thought to be musculoskeletal in  origin, and the T wave changes were presumably due to her ethnicity."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_108.png' OR image_url LIKE '%case_108.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man, who had complained of attacks of dizziness and palpitations for several years, collapsed at work and was brought to the A & E department. He was cold and clammy. His heart rate was rapid and his blood pressure was unrecordable. There were signs of left ventricular failure. These are his ECG and chest X-ray. What do they show and what would you do?","ecg_shows":"•\tNarrow complex tachycardia, rate just under 300/min •\tNo definite P waves •\tNormal QRS complexes •\tST segment depression in leads V4–V6","clinical_interpretation":"A regular narrow complex tachycardia at 300/min probably represents atrial flutter  with 1 : 1 conduction (i.e. each atrial activation causes ventricular activation).","what_to_do":"The cardiovascular collapse results from the rapid heart rate, with a loss of diastolic  filling. Carotid sinus pressure may temporarily increase the degree of block and  establish the diagnosis, but it is unlikely to convert atrial flutter to sinus rhythm.  Intravenous adenosine is likely to have the same effect as carotid sinus pressure. A  patient who is haemodynamically compromised by a tachycardia should be treated  with immediate DC cardioversion.","summary":"Probable atrial flutter with 1 : 1 conduction.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":250,"min":240,"max":260},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The cardiovascular collapse results from the rapid heart rate, with a loss of diastolic  filling. Carotid sinus pressure may temporarily increase the degree of block and  establish the diagnosis, but it is unlikely to convert atrial flutter to sinus rhythm.  Intravenous adenosine is likely to have the same effect as carotid sinus pressure. A  patient who is haemodynamically compromised by a tachycardia should be treated  with immediate DC cardioversion."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_109.png' OR image_url LIKE '%case_109.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man, who had had angina for several years, began to complain of attacks of dizziness. This is his ECG. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 88/min, with frequent multifocal ventricular extrasystoles •\tNormal PR interval •\tNormal axis •\tQ waves in leads II, III, VF •\tT waves flattened or inverted in the sinus beats in leads II, III, V5–V6","clinical_interpretation":"The ECG shows a probable old inferior myocardial infarction, which accounts for  his angina. Ventricular extrasystoles are in themselves usually not important, but  in a patient complaining of attacks of dizziness, ventricular extrasystoles that are  frequent and multifocal may be causing haemodynamic impairment.","what_to_do":"It would be worth recording an ambulatory ECG to see if the patient is having runs  of ventricular tachycardia, but the extrasystoles probably do need suppressing.  A beta-blocker would be the first drug to try, and then amiodarone.","summary":"Old inferior myocardial infarction and frequent multifocal ventricular extrasystoles.","stars":2,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":88,"min":83,"max":93},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"It would be worth recording an ambulatory ECG to see if the patient is having runs  of ventricular tachycardia, but the extrasystoles probably do need suppressing.  A beta-blocker would be the first drug to try, and then amiodarone."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_110.png' OR image_url LIKE '%case_110.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 50-year-old woman who complained of breathlessness and palpitations. What physical signs would you look for, and what is the next stage in her management?","ecg_shows":"•\tSinus rhythm, rate 52/min •\tBroad notched P waves, best seen in leads V2 and V3 •\tNormal axis •\tQRS complexes exhibiting left ventricular hypertrophy on voltage criteria – the  S wave in lead V2 is 20 mm deep and the R wave in lead V5 is 30 mm tall;  septal Q waves in leads V4–V6 •\tPartial RBBB pattern (RSR in V1) •\tNormal ST segments and T waves, apart from high take-off ST segments in  leads V4–V5","clinical_interpretation":"The broad P waves suggest left atrial hypertrophy. There is nothing other than the  voltage criteria (which are unreliable) to suggest left ventricular hypertrophy, so  mitral stenosis must be considered – although significant mitral stenosis usually  causes right ventricular hypertrophy. The palpitations could be due to atrial fibril­ lation if the patient has mitral stenosis.","what_to_do":"Look for the tapping apex beat, the loud first sound, the opening snap and the  mid-diastolic murmur that are characteristic of mitral stenosis. Echocardiography  will be helpful in distinguishing between valve disease and left ventricular hypertro­ phy as a cause of left atrial hypertrophy. Ambulatory ECG recording may be neces­ sary to identify the cause of the palpitations. Treatments to be considered if she has  mitral valve disease and atrial fibrillation are digoxin or a beta-blocker, anticoagu­ lants, and mitral valve surgery. If the breathlessness turns out to be due to poor left  ventricular function, an angiotensin-converting enzyme inhibitor is needed.","summary":"Sinus rhythm with left atrial hypertrophy.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Bifid (Mitrale)","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Look for the tapping apex beat, the loud first sound, the opening snap and the  mid-diastolic murmur that are characteristic of mitral stenosis. Echocardiography  will be helpful in distinguishing between valve disease and left ventricular hypertro­ phy as a cause of left atrial hypertrophy. Ambulatory ECG recording may be neces­ sary to identify the cause of the palpitations. Treatments to be considered if she has  mitral valve disease and atrial fibrillation are digoxin or a beta-blocker, anticoagu­ lants, and mitral valve surgery. If the breathlessness turns out to be due to poor left  ventricular function, an angiotensin-converting enzyme inhibitor is needed."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_111.png' OR image_url LIKE '%case_111.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man who complains of ankle swelling is found to have an irregular pulse, a blood pressure of 115/70, an enlarged heart, and signs of congestive cardiac failure. These are his ECG and chest X-ray. What do they show? He is untreated – how would you manage him?","ecg_shows":"•\tAtrial fibrillation, ventricular rate about 100/min, with one ventricular  extrasystole •\tNormal axis •\tBroad QRS complexes, with ‘M’ pattern in the lateral leads indicating left  bundle branch block (LBBB); bottom of S waves flattened in leads V1–V3 due to  artefacts •\tT waves inverted in lateral leads, as expected in LBBB","clinical_interpretation":"Atrial fibrillation and LBBB in a patient with an enlarged heart.","what_to_do":"This patient has had no chest pain, but has developed a very large heart with atrial  fibrillation; the ECG shows LBBB, which prevents any further interpretation. Isch­ aemia seems unlikely, and the diagnosis is almost certainly dilated cardiomyopathy  of unknown cause. An echocardiogram may show some mitral regurgitation due to  left ventricular dilatation, but the valves will probably be structurally normal. There  will probably be globally reduced left ventricular function with a low ejection frac­ tion. It is unlikely that a primary cause will be found, though alcoholism is the  important one to exclude. A coronary angiogram should probably be performed to  exclude ‘silent’ coronary disease, and an endomyocardial biopsy could be consid­ ered, to exclude the remote chance of a primary cardiomyopathy. Treatment would  be the usual combination of diuretics, an angiotensin-converting enzyme inhibitor,  digoxin, anticoagulants and ultimately cardiac transplantation.","summary":"Atrial fibrillation and LBBB in a patient with dilated cardiomyopathy.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":75,"min":70,"max":85},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"This patient has had no chest pain, but has developed a very large heart with atrial  fibrillation; the ECG shows LBBB, which prevents any further interpretation. Isch­ aemia seems unlikely, and the diagnosis is almost certainly dilated cardiomyopathy  of unknown cause. An echocardiogram may show some mitral regurgitation due to  left ventricular dilatation, but the valves will probably be structurally normal. There  will probably be globally reduced left ventricular function with a low ejection frac­ tion. It is unlikely that a primary cause will be found, though alcoholism is the  important one to exclude. A coronary angiogram should probably be performed to  exclude ‘silent’ coronary disease, and an endomyocardial biopsy could be consid­ ered, to exclude the remote chance of a primary cardiomyopathy. Treatment would  be the usual combination of diuretics, an angiotensin-converting enzyme inhibitor,  digoxin, anticoagulants and ultimately cardiac transplantation."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_112.png' OR image_url LIKE '%case_112.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man is sent to the outpatient department because of attacks of dizziness. What abnormalities does his ECG show, and what treatment is needed?","ecg_shows":"•\tThe rhythm is basically sinus, with a rate varying between 65/min and 100/min •\tOne ventricular extrasystole, at the beginning of the record •\tBroad complex tachycardia with an obviously different morphology from the  sinus beats. The QRS complex duration is 160 ms, and in lead V1 the R peak is  higher that the R1 peak. These features make it likely that the tachycardia is  ventricular in origin •\tLeft axis deviation in the sinus beats (left anterior hemiblock) •\tQRS complexes in the sinus beats otherwise appear normal •\tSlight ST segment depression in leads II, III, V5–V6 •\tT wave inversion in leads II, III","clinical_interpretation":"This ECG shows paroxysmal ventricular tachycardia, and probably underlying  ischaemic disease.","what_to_do":"This patient’s attacks of dizziness may be due to the paroxysmal arrhythmia, which  is life-threatening. The results of an ambulatory ECG recording and an exercise test  would be interesting, but the patient needs immediate treatment, and amiodarone  would probably be the drug of choice. A coronary angiogram should be considered  because there may be one or more critical stenoses amenable to percutaneous coro­ nary intervention (PCI), and this might abolish the ventricular tachycardia.","summary":"Sinus rhythm with paroxysmal ventricular tachycardia, and probable ischaemia.","stars":3,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"This patient’s attacks of dizziness may be due to the paroxysmal arrhythmia, which  is life-threatening. The results of an ambulatory ECG recording and an exercise test  would be interesting, but the patient needs immediate treatment, and amiodarone  would probably be the drug of choice. A coronary angiogram should be considered  because there may be one or more critical stenoses amenable to percutaneous coro­ nary intervention (PCI), and this might abolish the ventricular tachycardia."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_113.png' OR image_url LIKE '%case_113.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 30-year-old woman with severe rheumatoid arthritis, who was admitted to hospital with central chest pain. She was a non-smoker and had no risk factors for coronary artery disease. What do you think is going on?","ecg_shows":"•\tAtrial fibrillation, average rate about 100/min •\tNormal axis •\tNormal QRS complexes •\tRaised ST segments in leads I, II, III, VF, V2–V6 •\tIn leads V3 and V4 the raised ST segments seem to be due to ‘high take-off’","clinical_interpretation":"In a young woman with chest pain but no risk factors for a myocardial infarction,  an ST segment elevation infarction is obviously possible, but other causes of raised  ST segments must be considered. The ‘high take-off’ ST segments in leads V3–V4  (raised ST segment following an S wave) are a normal variant. The other raised ST  segments, which are widespread, could well be due to pericarditis.","what_to_do":"The patient should be examined lying flat, because this gives the best chance of  hearing a pericardial friction rub – and this is what was found here. The pericarditis  could, of course, be due to an infarction, but repeated ECGs showed no develop­ ment of an infarction pattern, and the raised ST segments persisted for several days.  An echocardiogram showed a pericardial effusion. The pericarditis, and presumably  the associated atrial fibrillation, were due to the rheumatoid arthritis.","summary":"Atrial fibrillation; ST segment elevation, partly ‘high take-off’ but mainly due  to pericarditis.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":100,"min":90,"max":110},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The patient should be examined lying flat, because this gives the best chance of  hearing a pericardial friction rub – and this is what was found here. The pericarditis  could, of course, be due to an infarction, but repeated ECGs showed no develop­ ment of an infarction pattern, and the raised ST segments persisted for several days.  An echocardiogram showed a pericardial effusion. The pericarditis, and presumably  the associated atrial fibrillation, were due to the rheumatoid arthritis."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_114.png' OR image_url LIKE '%case_114.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 18-year-old student complains of occasional attacks of palpitations. These start suddenly without provocation; the heartbeat seems regular and is ‘too fast to count’. During attacks she does not feel dizzy or breathless, and the palpitations stop suddenly after a few seconds. Physical examination is normal, and this is her ECG. What is the diagnosis and what advice would you give?","ecg_shows":"•\tSinus rhythm, rate 64/min, with ventricular extrasystoles •\tVery short PR interval •\tNormal axis •\tNormal QRS complexes and T waves, apart from a small Q wave and an  inverted T wave in lead III","clinical_interpretation":"This is the Lown–Ganong–Levine (LGL) syndrome. Unlike the Wolff–Parkinson– White (WPW) syndrome, in which there is an accessory pathway separate from the  atrioventricular node and His bundle, in the LGL syndrome there is a bypass close  to the atrioventricular node, connecting the left atrium and the His bundle. In the  WPW syndrome the QRS complex shows an early delta wave, but in the LGL  syndrome the QRS complex is normal.","what_to_do":"Ambulatory ECG recording may confirm the diagnosis if attacks are frequent  enough. Infrequent and short-lived attacks such as this patient describes are not  dangerous, but she should be taught vagal-stimulating procedures such as Valsalva’s  manoeuvre and carotid sinus pressure. An electrophysiological study and ablation  of the abnormal tract may be necessary. The ventricular extrasystoles are not impor­ tant, but she should be advised not to smoke, and to avoid alcohol and caffeine.","summary":"The LGL syndrome.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":64,"min":58,"max":70},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"Ambulatory ECG recording may confirm the diagnosis if attacks are frequent  enough. Infrequent and short-lived attacks such as this patient describes are not  dangerous, but she should be taught vagal-stimulating procedures such as Valsalva’s  manoeuvre and carotid sinus pressure. An electrophysiological study and ablation  of the abnormal tract may be necessary. The ventricular extrasystoles are not impor­ tant, but she should be advised not to smoke, and to avoid alcohol and caffeine."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_115.png' OR image_url LIKE '%case_115.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 37-year-old man admitted to hospital for a routine orthopaedic operation. The anaesthetist asks for comments.","ecg_shows":"•\tSinus rhythm, average 45/min •\tNormal axis •\tNormal QRS complexes •\tST segment depression in lead VF •\tInverted T waves in leads III, VR, V1 •\tPeaked T waves in the anterior leads","clinical_interpretation":"Provided the patient is not taking a beta-blocker, the slow heart rate is probably a  reflection of physical fitness. Inverted T waves in leads III, VR and V1, and the  depressed ST segments in lead VF, are probably normal. Peaked T waves are char­ acteristic of hyperkalaemia, and are sometimes described as ‘hyperacute’ in isch­ aemia. However, when as large as this – and particularly when the patient is  asymptomatic – peaked T waves are nearly always perfectly normal.","what_to_do":"Ensure that the patient has no cardiac symptoms, and check his electrolyte levels  preoperatively.","summary":"Normal ECG.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":45,"min":40,"max":50},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Peaked"},"management":{"urgency":"Routine","notes":"Ensure that the patient has no cardiac symptoms, and check his electrolyte levels  preoperatively."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_116.png' OR image_url LIKE '%case_116.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old man, who had had attacks of palpitations for several years, was seen during an attack, and this how should he be treated?","ecg_shows":"•\tBroad complex tachycardia at 200/min •\tNo P waves visible •\tRight axis deviation •\tQRS complex duration 200 ms •\tQRS complexes show no concordance •\tLeft bundle branch block (LBBB) pattern – QRS complexes show ‘M’ pattern,  best seen in lead V4","clinical_interpretation":"A broad complex tachycardia like this is probably of ventricular origin. In this case,  features against the rhythm being ventricular tachycardia are the right axis deviation  and the lack of concordance in the QRS complexes (i.e. the complexes point down­ wards in leads V1–V2 and upwards in the other chest leads). The combination of  right axis deviation and an LBBB pattern in a broad complex tachycardia suggests  that the origin is in the right ventricular outflow tract.","what_to_do":"Any patient with an arrhythmia and evidence of haemodynamic compromise (in  this case, breathlessness and a very low blood pressure) needs immediate cardiover­ sion. While preparations are being made, it would be reasonable to try intravenous  lidocaine or amiodarone. Once the arrhythmia has been corrected, an electrophysi­ ological study is needed, because right ventricular outflow tract tachycardia is the  one variety of ventricular tachycardia that should be amenable to ablation therapy.","summary":"Ventricular tachycardia, probably originating in the right ventricular outflow tract.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":200,"min":190,"max":210},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"Any patient with an arrhythmia and evidence of haemodynamic compromise (in  this case, breathlessness and a very low blood pressure) needs immediate cardiover­ sion. While preparations are being made, it would be reasonable to try intravenous  lidocaine or amiodarone. Once the arrhythmia has been corrected, an electrophysi­ ological study is needed, because right ventricular outflow tract tachycardia is the  one variety of ventricular tachycardia that should be amenable to ablation therapy."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_117.png' OR image_url LIKE '%case_117.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 75-year-old man with heart failure. He did not complain of chest pain. There are three main abnormalities. How should he be treated?","ecg_shows":"•\tSinus rhythm, rate 60/min, with one ventricular extrasystole •\tLeft axis deviation •\tQ waves in leads V1–V5 in the sinus beats •\tRaised ST segments in the anterior leads •\tInverted T wave in lead VL; flattened T waves in leads I, V6","clinical_interpretation":"A ‘silent’ anterior infarction of uncertain age has caused left anterior hemiblock,  which explains the left axis deviation. The lateral T wave changes are presumably  due to ischaemia.","what_to_do":"Ventricular extrasystoles should not be treated, and left anterior hemiblock is not  an indication for pacing. In the absence of pain, the anterior infarction cannot be  assumed to be new, so percutaneous coronary intervention (PCI) or thrombolysis  should not be given. He needs an angiotensin-converting enzyme inhibitor and a  diuretic.","summary":"Left anterior hemiblock and anterior infarction of uncertain age; one ventricular  extrasystole.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":60,"min":55,"max":65},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Ventricular extrasystoles should not be treated, and left anterior hemiblock is not  an indication for pacing. In the absence of pain, the anterior infarction cannot be  assumed to be new, so percutaneous coronary intervention (PCI) or thrombolysis  should not be given. He needs an angiotensin-converting enzyme inhibitor and a  diuretic."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Anterior"}}'::jsonb WHERE image_url LIKE '%case_118.png' OR image_url LIKE '%case_118.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 35-year-old woman, who had had palpitations for many years without any diagnosis being made, was eventually seen in the A & E department during an attack. She looked well and was not in heart failure, and her blood pressure was 120/70. This is her ECG. What is the rhythm, and what would you do?","ecg_shows":"•\tBroad complex tachycardia (QRS complex duration 200 ms), rate nearly  200/min •\tNo P waves visible •\tRight axis deviation •\tIn lead V1, the R1 peak is higher than the R peak •\tRight bundle branch block (RBBB) pattern •\tNo concordance of QRS complexes in the V leads","clinical_interpretation":"The problem here is to distinguish between a supraventricular tachycardia with  bundle branch block and a ventricular tachycardia. The clinical history is not  helpful, nor is the fact that the patient is haemodynamically stable. The combination  of right axis deviation, RBBB and the R1 peak being higher than the R peak in lead  V1 make it likely that this is a supraventricular tachycardia with RBBB rather than  ventricular tachycardia. However, the very broad QRS complex (>140 ms) would  favour a ventricular origin for the arrhythmia.","what_to_do":"Carotid sinus massage. If this has no effect, try intravenous adenosine, and if this  is ineffective, try intravenous lidocaine.","summary":"Broad complex tachycardia with RBBB pattern, probably supraventricular in origin.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":195,"min":185,"max":205},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Carotid sinus massage. If this has no effect, try intravenous adenosine, and if this  is ineffective, try intravenous lidocaine."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_119.png' OR image_url LIKE '%case_119.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded as part of the routine investigation of a 40-year-old man who was admitted to hospital following a first seizure. He was unconscious and had a stiff neck and bilateral extensor plantar responses. His heart was clinically normal. What do you think has happened?","ecg_shows":"","clinical_interpretation":"The appearances here are suggestive of an anterolateral non-ST segment elevation  myocardial infarction, but this does not correspond with the clinical picture and  would not explain the long QT interval.","what_to_do":"It is possible that this patient had a myocardial infarction which caused a cerebro­ vascular accident because of an arrhythmia or a cerebral embolus, and that the  cerebrovascular accident caused the seizure. The unconsciousness and the bilateral  extensor plantar responses could simply be post-ictal. However, such a sequence  would not explain the stiff neck, which would seem to point to either a subarach­ noid haemorrhage or meningitis. Changes like those in this ECG are common in  subarachnoid haemorrhage, probably because of intense coronary vasospasm result­ ing from catecholamine release. Measurements of the blood troponin level are  unlikely to help to differentiate between a primarily cardiac and a primarily neuro­ logical event. This patient did indeed have a subarachnoid haemorrhage, and the  ECG eventually returned to normal.","summary":"Anterolateral T wave inversion due to subarachnoid haemorrhage.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"It is possible that this patient had a myocardial infarction which caused a cerebro­ vascular accident because of an arrhythmia or a cerebral embolus, and that the  cerebrovascular accident caused the seizure. The unconsciousness and the bilateral  extensor plantar responses could simply be post-ictal. However, such a sequence  would not explain the stiff neck, which would seem to point to either a subarach­ noid haemorrhage or meningitis. Changes like those in this ECG are common in  subarachnoid haemorrhage, probably because of intense coronary vasospasm result­ ing from catecholamine release. Measurements of the blood troponin level are  unlikely to help to differentiate between a primarily cardiac and a primarily neuro­ logical event. This patient did indeed have a subarachnoid haemorrhage, and the  ECG eventually returned to normal."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_120.png' OR image_url LIKE '%case_120.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man with lung cancer is admitted to hospital with abdominal pain and ankle swelling. He has a raised jugular venous pressure, a tender and distended liver, and marked peripheral oedema. Does this ECG help with the diagnosis and what might you need to do? What does the chest X-ray show?","ecg_shows":"•\tSinus rhythm, rate 97/min •\tNormal axis •\tQRS complexes of normal width, but generally small •\tT wave inversion in leads I, II, III, VF, V5–V6 •\tLoss of signal in lead VL – artefact","clinical_interpretation":"Small QRS complexes are seen with a pericardial effusion, and sometimes in patients  with chronic lung disease. The widespread T wave changes would be consistent with  pericardial disease. There is nothing in this record to suggest pulmonary disease.","what_to_do":"The physical findings, the ECG and the chest X-ray would fit with a pericardial  effusion associated with malignancy. You should look carefully at the jugular venous  pressure to see if it rises with inspiration, indicating pericardial tamponade. Echo­ cardiography is essential, and if there is evidence of right ventricular collapse in  diastole, a pericardial drain should be inserted. The patient had a malignant peri­ cardial effusion.","summary":"Small QRS complexes and widespread T wave changes consistent with a  pericardial effusion.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":97,"min":92,"max":102},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The physical findings, the ECG and the chest X-ray would fit with a pericardial  effusion associated with malignancy. You should look carefully at the jugular venous  pressure to see if it rises with inspiration, indicating pericardial tamponade. Echo­ cardiography is essential, and if there is evidence of right ventricular collapse in  diastole, a pericardial drain should be inserted. The patient had a malignant peri­ cardial effusion."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_121.png' OR image_url LIKE '%case_121.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 65-year-old woman who had had a mitral valve replacement to treat rheumatic valve disease, and who was admitted to hospital with generalized lethargy, nausea and vomiting. What does the","ecg_shows":"•\tAtrial fibrillation •\tRight axis deviation •\tNormal QRS complexes, except for a tall R wave in lead V1 •\tDownward-sloping ST segments, best seen in leads II, III, VF •\tGenerally flattened T waves •\tU waves, best seen in leads V4–V5","clinical_interpretation":"The atrial fibrillation, and the right axis deviation and tall R waves in lead V1  (indicating right ventricular hypertrophy) probably pre-date the valve replacement.  The flat T waves with obvious U waves suggest hypokalaemia. The downward- sloping ST segments suggest digoxin effect.","what_to_do":"The clinical picture fits hypokalaemia and digoxin toxicity. Since the electrolyte  and digoxin levels cannot be measured, stop the digoxin and any potassium-losing  diuretics. Give the patient potassium orally. Monitoring the T and U waves is a  crude but effective way of judging the serum potassium level.","summary":"Atrial fibrillation, hypokalaemia and digoxin effect.","stars":3,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":80,"min":70,"max":90},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Flattened"},"management":{"urgency":"Urgent","notes":"The clinical picture fits hypokalaemia and digoxin toxicity. Since the electrolyte  and digoxin levels cannot be measured, stop the digoxin and any potassium-losing  diuretics. Give the patient potassium orally. Monitoring the T and U waves is a  crude but effective way of judging the serum potassium level."},"qrs_morph":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_122.png' OR image_url LIKE '%case_122.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 20-year-old man is seen in the A & E department with a head injury; there is a vague story of a collapse. What does the ECG show?","ecg_shows":"•\tSinus rhythm, rate 55/min – P waves best seen in lead V1 •\tThe first complex is probably a ventricular systole •\tShort PR interval •\tLeft axis deviation •\tBroad QRS complexes (160 ms) with a slurred upstroke (delta wave), best seen  in leads V2–V4 •\tInverted T waves in leads I, II, VL; biphasic T waves in leads V5–V6 •\tThe small second and third complexes in lead II appear to be due to a technical  error","clinical_interpretation":"The short PR intervals and the delta waves are characteristic of the Wolff–Parkinson– White (WPW) syndrome. Superficially, leads I, VL and V5–V6 might mistakenly be  interpreted as suggesting left bundle branch block, but it is important to look at all  the leads because the diagnosis here is best seen in lead V2. In this case there is no  dominant R wave in lead V1, so the accessory conducting bundle is on the right  side, and this is the WPW syndrome type B.","what_to_do":"The WPW syndrome is associated with paroxysmal tachyarrhythmia, which may  cause collapse. Asymptomatic WPW syndrome should be left untreated, but it is  important in this case to establish – perhaps by ambulatory ECG recording and  exercise testing – whether the patient was having paroxysmal tachycardia or not. If there is reason to suppose that an arrhythmia caused his collapse and head  injury he needs electrophysiological ablation of the abnormal conducting pathway.","summary":"The WPW syndrome type B.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":55,"min":50,"max":60},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"The WPW syndrome is associated with paroxysmal tachyarrhythmia, which may  cause collapse. Asymptomatic WPW syndrome should be left untreated, but it is  important in this case to establish – perhaps by ambulatory ECG recording and  exercise testing – whether the patient was having paroxysmal tachycardia or not. If there is reason to suppose that an arrhythmia caused his collapse and head  injury he needs electrophysiological ablation of the abnormal conducting pathway."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_123.png' OR image_url LIKE '%case_123.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 85-year-old man, who has had high blood pressure for many years, is seen in the outpatient department complaining of typical angina and of occasional dizziness when walking up hills. These are his ECG and chest X-ray. What is the diagnosis, and what would you do?","ecg_shows":"•\tSinus rhythm, rate 71/min •\tNormal axis •\tTall R waves and deep S waves in the chest leads •\tST segment depression in leads V4–V6 •\tInverted T waves in leads I, II, VL, V3–V6","clinical_interpretation":"This is marked left ventricular hypertrophy. It can be difficult to distinguish between  T wave inversion due to ischaemia and the T wave inversion of left ventricular  hypertrophy, and when the T wave is inverted in the septal leads (V3–V4), ischaemia  has to be considered. However, here the change is most marked in the lateral leads,  and is associated with the ‘voltage criteria’ for left ventricular hypertrophy. Angina,  dizziness and left ventricular hypertrophy in an 85-year-old may be due to tight  aortic stenosis, though hypertension is a possibility.","what_to_do":"Look for the signs of aortic stenosis (‘plateau’ pulse, narrow pulse pressure, dis­ placed apex beat, aortic ejection systolic murmur) and confirm the valve gradient  with echocardiography. In this patient the aortic valve gradient was 20 mmHg,  indicating trivial stenosis of the valve, so the left ventricular hypertrophy must be  due to the long-standing hypertension. The angina may well improve with adequate  blood pressure control and the usual anti-anginal medication, but if it does not,  then 85 years is not too old for coronary angiography with a view to percutaneous  coronary intervention (PCI) or bypass surgery.","summary":"Left ventricular hypertrophy.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":71,"min":66,"max":76},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Look for the signs of aortic stenosis (‘plateau’ pulse, narrow pulse pressure, dis­ placed apex beat, aortic ejection systolic murmur) and confirm the valve gradient  with echocardiography. In this patient the aortic valve gradient was 20 mmHg,  indicating trivial stenosis of the valve, so the left ventricular hypertrophy must be  due to the long-standing hypertension. The angina may well improve with adequate  blood pressure control and the usual anti-anginal medication, but if it does not,  then 85 years is not too old for coronary angiography with a view to percutaneous  coronary intervention (PCI) or bypass surgery."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_124.png' OR image_url LIKE '%case_124.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 15-year-old boy who collapsed while playing football, but was well by the time he was seen. What are the possible diagnoses?","ecg_shows":"•\tSinus rhythm, rate 75/min •\tNormal PR interval and QRS complex duration •\tNormal axis •\tNormal QRS complexes •\tInverted T waves in leads V1–V3 •\tLong QT interval (520 ms)","clinical_interpretation":"A collapse during exercise raises the possibility of aortic stenosis, hypertrophic  cardiomyopathy, or an exercise-induced arrhythmia. This ECG does not show the  pattern of left ventricular hypertrophy, so aortic stenosis is unlikely. Anterior T wave  inversion is characteristic of hypertrophic cardiomyopathy, but this does not nor­ mally cause a prolonged QT interval. Exercise-induced arrhythmias are typical of  the familial long QT syndrome, and this boy’s sister had died suddenly.","what_to_do":"Initial treatment is with a beta-blocker, but an ICD (implantable cardioverter defib­ rillator) must be considered.","summary":"The congenital long QT syndrome.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"Initial treatment is with a beta-blocker, but an ICD (implantable cardioverter defib­ rillator) must be considered."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_125.png' OR image_url LIKE '%case_125.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 70-year-old man, who has had angina for 10 years, is admitted to hospital with severe central chest pain that has been present for 4 h. This is his ECG. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, average rate 70/min •\tNormal axis •\tQ waves in leads III, VF •\tNormal QRS complexes elsewhere •\tRaised ST segments in leads II (following small S waves), III, VF •\tBiphasic T waves in leads V2–V3 •\tInverted T waves in leads V4–V5","clinical_interpretation":"The inferior Q waves suggest an old infarction. The raised ST segments in leads III  and VF would be compatible with an acute infarction, though the raised ST segment  in lead II is a ‘high take-off’ segment because it follows an S wave, and this raises  the possibility that the changes in leads III and VF may not be significant. The  anterior changes suggest a non-ST segment elevation myocardial infarction  (NSTEMI).","what_to_do":"There is enough evidence here from leads III and VF to justify percutaneous coro­ nary intervention (PCI) or thrombolysis – which should, of course, be combined  with pain relief and aspirin.","summary":"Possible old and/or possible new inferior myocardial infarction; anterior NSTEMI.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"There is enough evidence here from leads III and VF to justify percutaneous coro­ nary intervention (PCI) or thrombolysis – which should, of course, be combined  with pain relief and aspirin."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_126.png' OR image_url LIKE '%case_126.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man is admitted to hospital as an emergency, having had chest pain for 4 h. The pain is characteristic of a myocardial infarction. Apart from signs due to pain, the examination is normal. What does this","ecg_shows":"•\tSinus rhythm •\tNormal axis •\tQ waves in leads II, III, VF •\tElevated ST segments in leads II, III, VF, with biphasic T waves •\tDownward-sloping ST segments in lead VL •\tNormal QRS complexes, ST segments and T waves in the chest leads","clinical_interpretation":"This is an acute ST segment elevation inferior myocardial infarction. The rapidity  of Q wave development is extremely variable, but the trace is certainly consistent  with a 4 h history.","what_to_do":"Pain relief is the most important part of the treatment. In the absence of contra­ indications, the patient should be given aspirin immediately, and then thrombolysis  or percutaneous coronary intervention (angioplasty) as soon as possible.","summary":"Acute inferior myocardial infarction.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"},"st_t":{"ischemia":"ST Elevation","t_wave":"Biphasic"},"management":{"urgency":"Emergency","notes":"Pain relief is the most important part of the treatment. In the absence of contra­ indications, the patient should be given aspirin immediately, and then thrombolysis  or percutaneous coronary intervention (angioplasty) as soon as possible."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_127.png' OR image_url LIKE '%case_127.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 60-year-old man admitted to hospital with severe heart failure and a heart murmur. What does it show and what would you do?","ecg_shows":"•\tSinus rhythm, rate 60/min •\tBifid P wave (best seen in lead V3) suggesting left atrial hypertrophy •\tLeft ventricular hypertrophy by ‘voltage criteria’ (height of R wave in lead V6  plus depth of S wave in lead V2 = 50 mm) •\tLateral T wave inversion","clinical_interpretation":"These are the classic changes of left atrial and left ventricular hypertrophy. In a  patient with heart failure and a heart murmur the likely diagnosis is severe aortic  valve disease.","what_to_do":"The heart failure must be treated with diuretics, but it is essential to establish the  cause of the left ventricular hypertrophy before selecting long-term treatment. It  could be due to aortic stenosis or regurgitation, to mitral regurgitation or to hyper­ tension. While an angiotensin-converting enzyme inhibitor would be appropriate  treatment for a patient with hypertension or mitral regurgitation, it would be poten­ tially dangerous in a patient with aortic stenosis. An echocardiogram is the essential  next step. This patient had severe aortic stenosis, and needed an aortic valve  replacement.","summary":"Left atrial and left ventricular hypertrophy.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":60,"min":55,"max":65},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Bifid (Mitrale)","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"The heart failure must be treated with diuretics, but it is essential to establish the  cause of the left ventricular hypertrophy before selecting long-term treatment. It  could be due to aortic stenosis or regurgitation, to mitral regurgitation or to hyper­ tension. While an angiotensin-converting enzyme inhibitor would be appropriate  treatment for a patient with hypertension or mitral regurgitation, it would be poten­ tially dangerous in a patient with aortic stenosis. An echocardiogram is the essential  next step. This patient had severe aortic stenosis, and needed an aortic valve  replacement."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_128.png' OR image_url LIKE '%case_128.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old man had complained of occasional episodes of palpitations for several years. Between attacks he was well, there were no physical abnormalities, and his ECG was normal. Eventually this ECG was recorded during one of his attacks. What is the arrhythmia and what would you do?","ecg_shows":"","clinical_interpretation":"Without a full 12-lead record of the tachycardia it is difficult to be certain, but the  complexes are very broad and have a totally different appearance from those in  sinus rhythm, so this is almost certainly ventricular tachycardia. The ST segment  depression in sinus rhythm is mild and not sufficient to make a confident diagnosis  of ischaemia, but because the depression is horizontal, ischaemia seems likely.","what_to_do":"Patients who have only occasional episodes of an arrhythmia, and who are other­ wise well, are always difficult to manage. This patient should certainly have  an echocardiogram to exclude a cardiomyopathy, and an exercise test to investi­ gate the possibility of ischaemia and exercise-induced arrhythmias. At the age of  60 years, coronary angiography is probably indicated. Electrophysiological studies  can be carried out to determine which antiarrhythmic agent to use in individual  cases; however, in practice, amiodarone is just as effective as the agent selected by  means of these studies. If the episodes were causing syncope, an implanted defibril­ lator could be considered.","summary":"Paroxysmal ventricular tachycardia.","stars":2,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"Dissociated","p_qrs_relation":"Dissociated","sa_block":"None"},"rate":{"target":150,"min":140,"max":160},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Patients who have only occasional episodes of an arrhythmia, and who are other­ wise well, are always difficult to manage. This patient should certainly have  an echocardiogram to exclude a cardiomyopathy, and an exercise test to investi­ gate the possibility of ischaemia and exercise-induced arrhythmias. At the age of  60 years, coronary angiography is probably indicated. Electrophysiological studies  can be carried out to determine which antiarrhythmic agent to use in individual  cases; however, in practice, amiodarone is just as effective as the agent selected by  means of these studies. If the episodes were causing syncope, an implanted defibril­ lator could be considered."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_129.png' OR image_url LIKE '%case_129.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 25-year-old woman, who had had episodes of what sound like a paroxysmal tachycardia for 10 years, produced this ECG when seen during an attack. What is the rhythm, and what is the underlying problem?","ecg_shows":"•\tIrregular tachycardia at about 200/min •\tNo consistent P waves visible •\tLeft axis deviation •\tQRS complex duration varies between about 120 and 160 ms •\tQRS complexes show a dominant R wave in lead V1 and a prominent S wave in  lead V6 •\tAfter the longer pauses, the upstroke of the QRS complexes appears slurred","clinical_interpretation":"The marked irregularity of this rhythm must be explained by atrial fibrillation. The  broad QRS complexes might be due to right bundle branch block, but the dominant  R wave in lead V1, together with the slurred upstroke of the QRS complex in at  least some leads, indicate the Wolff–Parkinson–White (WPW) syndrome type A.","what_to_do":"A combination of the WPW syndrome and atrial fibrillation is very dangerous,  because it can degenerate into ventricular fibrillation. The arrhythmia needs treating  as an emergency, whatever the clinical state of the patient. It is important not to  use drugs that may block the atrioventricular node and increase conduction through  the accessory pathway, because this will increase the risk of ventricular fibrillation.  Therefore, adenosine, digoxin, verapamil and lidocaine are contraindicated. The  drugs that slow conduction in the accessory pathway, and are therefore safe, are  the beta-blockers, flecainide and amiodarone. Thereafter, an electrophysiological  study to identify and ablate the accessory pathway is essential.","summary":"Atrial fibrillation and the WPW syndrome type A.","stars":3,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":200,"min":190,"max":210},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Left Deviation","deviation":"Left Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"A combination of the WPW syndrome and atrial fibrillation is very dangerous,  because it can degenerate into ventricular fibrillation. The arrhythmia needs treating  as an emergency, whatever the clinical state of the patient. It is important not to  use drugs that may block the atrioventricular node and increase conduction through  the accessory pathway, because this will increase the risk of ventricular fibrillation.  Therefore, adenosine, digoxin, verapamil and lidocaine are contraindicated. The  drugs that slow conduction in the accessory pathway, and are therefore safe, are  the beta-blockers, flecainide and amiodarone. Thereafter, an electrophysiological  study to identify and ablate the accessory pathway is essential."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_130.png' OR image_url LIKE '%case_130.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 35-year-old white man is seen in the outpatient department complaining of chest pain on exertion, sometimes with exertion-induced dizziness, and this is his ECG. What is the likely diagnosis? What physical signs would you look for?","ecg_shows":"•\tSinus rhythm •\tNormal axis •\tNormal QRS complexes •\tMarked T wave inversion in leads I, II, VL, V4–V6","clinical_interpretation":"Anterolateral T wave inversion as gross as this may be due to a non-ST segment  elevation myocardial infarction, or even to left ventricular hypertrophy. However,  there are no other features of left ventricular hypertrophy on this trace, which is  fairly characteristic of hypertrophic cardiomyopathy. Myocardial infarction is  uncommon in people of this age.","what_to_do":"Physical signs of hypertrophic cardiomyopathy include a ‘jerky pulse’; an aortic flow  murmur which is characteristically louder after the pause that follows an extrasys­ tole; and mitral regurgitation. Hypertrophic cardiomyopathy is best diagnosed by  echocardiography, which will show asymmetric septal hypertrophy, systolic anterior  movement of the mitral valve apparatus, and sometimes early closure of the aortic  valve. This patient’s echocardiogram showed all these features, confirming the diag­ nosis of hypertrophic cardiomyopathy.","summary":"Gross T wave inversion in the anterolateral leads, suggesting  hypertrophic cardiomyopathy.","stars":6,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Physical signs of hypertrophic cardiomyopathy include a ‘jerky pulse’; an aortic flow  murmur which is characteristically louder after the pause that follows an extrasys­ tole; and mitral regurgitation. Hypertrophic cardiomyopathy is best diagnosed by  echocardiography, which will show asymmetric septal hypertrophy, systolic anterior  movement of the mitral valve apparatus, and sometimes early closure of the aortic  valve. This patient’s echocardiogram showed all these features, confirming the diag­ nosis of hypertrophic cardiomyopathy."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_131.png' OR image_url LIKE '%case_131.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 30-year-old woman admitted to hospital with diabetic ketoacidosis. Any comments?","ecg_shows":"","clinical_interpretation":"These changes are characteristic of hyperkalaemia, which of course is likely to be  present in diabetic ketoacidosis.","what_to_do":"This ECG should alert you to check the serum potassium level immediately: in this  patient it was found to be 7.1 mmol/l. It settled rapidly with treatment of the  diabetes.","summary":"Hyperkalaemia.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Peaked"},"management":{"urgency":"Emergency","notes":"This ECG should alert you to check the serum potassium level immediately: in this  patient it was found to be 7.1 mmol/l. It settled rapidly with treatment of the  diabetes."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_132.png' OR image_url LIKE '%case_132.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded as part of the health screening of an asymptomatic 40-year-old man. How would you proceed?","ecg_shows":"•\tSinus rhythm at about 77/min, with ventricular extrasystoles at the beginning  and end of the record, and a six-beat run of a broad complex rhythm in the  middle of the record •\tThe first complex of the run of broad complexes differs from the others, and is  probably a fusion beat (a combination of a sinus beat and the ectopic rhythm) •\tNormal axis when in sinus rhythm •\tNormal QRS complexes in sinus rhythm •\tInverted T waves in lead III, but not VF","clinical_interpretation":"The run of broad complexes represents accelerated idioventricular rhythm. This is  quite common following a myocardial infarction, but in a healthy subject it is prob­ ably of no significance. The T wave inversion in lead III is not important because  the T wave is upright in lead VF.","what_to_do":"If the individual has no symptoms and the physical examination is normal, no  further action is needed. Accelerated idioventricular rhythm should not be treated.","summary":"Sinus rhythm and accelerated idioventricular rhythm.","stars":3,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":77,"min":72,"max":82},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Routine","notes":"If the individual has no symptoms and the physical examination is normal, no  further action is needed. Accelerated idioventricular rhythm should not be treated."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_133.png' OR image_url LIKE '%case_133.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 60-year-old woman, with long-standing heart failure of uncertain cause, complains of anorexia, weight loss, and general weakness and lethargy. Does this ECG help with her diagnosis and management?","ecg_shows":"•\tAtrial fibrillation •\tCoupled ventricular extrasystoles •\tQ waves in lead VL (in the supraventricular beats) •\tST segment depression in lead V6 •\tFlattened T waves and prominent U waves (best seen in lead V4)","clinical_interpretation":"A patient with heart failure with atrial fibrillation will probably be receiving digoxin  and diuretics. The history of anorexia and weight loss suggests digoxin toxicity, and  the weakness could be due to hypokalaemia. The ECG supports this. Lead V6 shows  digoxin effect, and coupled ventricular extrasystoles are a feature of digoxin toxicity.  The flat T waves and prominent U waves suggest hypokalaemia.","what_to_do":"Remember that hypokalaemia potentiates the effect of digoxin. Therefore, stop the  digoxin, check the electrolytes, and give oral potassium supplements. Do not give  antiarrhythmic agents. Treat the heart failure with vasodilators. This woman improved dramatically when her digoxin dose was reduced and she  was given oral potassium. Then she was prescribed an angiotensin-converting  enzyme inhibitor and a reduced dose of diuretics.","summary":"Atrial fibrillation with ventricular extrasystoles; probable digoxin  toxicity and hypokalaemia.","stars":6,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":80,"min":75,"max":85},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"Lateral"},"st_t":{"ischemia":"ST Depression","t_wave":"Flattened"},"management":{"urgency":"Urgent","notes":"Remember that hypokalaemia potentiates the effect of digoxin. Therefore, stop the  digoxin, check the electrolytes, and give oral potassium supplements. Do not give  antiarrhythmic agents. Treat the heart failure with vasodilators. This woman improved dramatically when her digoxin dose was reduced and she  was given oral potassium. Then she was prescribed an angiotensin-converting  enzyme inhibitor and a reduced dose of diuretics."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"Lateral"}}'::jsonb WHERE image_url LIKE '%case_134.png' OR image_url LIKE '%case_134.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man complains of typical angina. His blood pressure is 150/90, and he has an aortic ejection systolic murmur. This is his ECG. What is the probable cause of his angina, and what would you do?","ecg_shows":"•\tSinus rhythm, rate 77/min •\tNormal axis •\tNormal QRS complexes •\tRaised ST segments following S waves in leads V4–V5 •\tInverted T waves in leads I, VL, V5–V6","clinical_interpretation":"The raised ST segments in leads V4–V5 are due to ‘high take-off’ and are not impor­ tant. The lateral T wave inversion could indicate left ventricular hypertrophy or  ischaemia, and this patient could have aortic stenosis or coronary disease. In the  absence of tall R waves, lateral ischaemia seems more likely than left ventricular  hypertrophy, but it is often difficult to distinguish between these on the ECG.","what_to_do":"Echocardiography will show whether the patient has significant aortic valve disease.  Remember that anaemia can cause systolic murmurs and angina, though probably  not this degree of T wave inversion. The patient had coronary disease.","summary":"Probable lateral ischaemia, but possible left ventricular hypertrophy.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":77,"min":72,"max":82},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Echocardiography will show whether the patient has significant aortic valve disease.  Remember that anaemia can cause systolic murmurs and angina, though probably  not this degree of T wave inversion. The patient had coronary disease."},"qrs_morph":{"hypertrophy":"LVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_135.png' OR image_url LIKE '%case_135.png';
UPDATE ecg_cases SET findings_json = '{"history":"The upper ECG was recorded by paramedics from a 50-year-old woman who had had episodes of chest pain for several years, and who called an ambulance because of a severe attack. By the time she reached the A & E department, when the lower ECG was recorded, her pain had gone. What had happened?","ecg_shows":"","clinical_interpretation":"The first ECG seems to indicate an acute anterolateral myocardial infarction. An  alternative explanation, given the widespread changes, would be pericarditis. The  second ECG is normal. Because the ECG reverted to normal when the pain cleared,  it seems likely that the changes in the initial ECG represent Prinzmetal’s variant  angina.","what_to_do":"Prinzmetal’s variant angina was first described in 1959. It occurs at rest, and the  characteristic raised ST segments seen in the ECG are not reproduced by exertion.  It has been shown by angiography during pain to be due to spasm of one or more  coronary arteries. Relatively few patients with this type of angina have totally  normal arteries, and spasm may occur at the site of atheromatous plaques. Coronary  angiography is indicated. Nifedipine and nitrates may be helpful, but the condition  is difficult to treat.","summary":"Prinzmetal’s variant angina.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Prinzmetal’s variant angina was first described in 1959. It occurs at rest, and the  characteristic raised ST segments seen in the ECG are not reproduced by exertion.  It has been shown by angiography during pain to be due to spasm of one or more  coronary arteries. Relatively few patients with this type of angina have totally  normal arteries, and spasm may occur at the site of atheromatous plaques. Coronary  angiography is indicated. Nifedipine and nitrates may be helpful, but the condition  is difficult to treat."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_136.png' OR image_url LIKE '%case_136.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 45-year-old man was admitted to hospital with a history of 2 h of ischaemic chest pain. His blood pressure was 150/80, and there were no signs of heart failure. What does his ECG show, and how would you treat him?","ecg_shows":"•\tBroad complex tachycardia, rate 180/min •\tNo P waves •\tRight axis deviation •\tQRS complex duration about 140 ms •\tRight bundle branch block (RBBB) pattern, with the R peak taller than the R1  peak in lead V1 – best seen in the fifth complex •\tNon-concordant QRS complexes, with a negative pattern in lead V6 (i.e.  complexes are upwards in lead V1 but downwards in lead V6)","clinical_interpretation":"This is either ventricular tachycardia or supraventricular tachycardia with RBBB.  In favour of the former are the relatively wide QRS complexes and the fact that the  R peak is greater than the R1 peak in lead V1 (i.e. this is not the typical RBBB  pattern). Against ventricular tachycardia are the right axis deviation and the differ­ ent directions of the QRS complexes in the chest leads.","what_to_do":"The problem is to decide whether the patient had a myocardial infarction compli­ cated by ventricular tachycardia, or whether the arrhythmia is causing the anginal  pain. Since he is haemodynamically stable, he needs pain relief, carotid sinus pres­ sure, intravenous adenosine and intravenous lidocaine, in that order. If in doubt, or  if his blood pressure were to fall or he were to develop heart failure, the safest  course of action would be DC cardioversion. This patient needed cardioversion, and the ECG then showed an anterior infarc­ tion. The rhythm was probably ventricular tachycardia.","summary":"Broad complex tachycardia of uncertain origin.","stars":3,"rhythm":{"regularity":"Regular","sinus":false,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":180,"min":175,"max":185},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"The problem is to decide whether the patient had a myocardial infarction compli­ cated by ventricular tachycardia, or whether the arrhythmia is causing the anginal  pain. Since he is haemodynamically stable, he needs pain relief, carotid sinus pres­ sure, intravenous adenosine and intravenous lidocaine, in that order. If in doubt, or  if his blood pressure were to fall or he were to develop heart failure, the safest  course of action would be DC cardioversion. This patient needed cardioversion, and the ECG then showed an anterior infarc­ tion. The rhythm was probably ventricular tachycardia."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_137.png' OR image_url LIKE '%case_137.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 65-year-old man who complained of breathlessness and who showed the physical signs of moderate heart failure. What does the ECG show? Does it have implications for treatment?","ecg_shows":"•\tSinus rhythm, rate 97/min •\tMultifocal ventricular extrasystoles and one supraventricular extrasystole •\tQ waves in the sinus beats in leads III, VF •\tRight bundle branch block (RBBB)","clinical_interpretation":"The presence of Q waves in the inferior leads suggests an old infarction. Ischaemic  disease is therefore probably the cause of the extrasystoles and the RBBB.","what_to_do":"Control of the heart failure may well cause the extrasystoles to disappear; the  extrasystoles should not be treated with antiarrhythmic drugs. The presence of  multifocal extrasystoles should alert you to consider electrolyte abnormalities and  digoxin toxicity.","summary":"Multifocal ventricular extrasystoles, RBBB and probable old inferior  myocardial infarction.","stars":4,"rhythm":{"regularity":"Irregular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":97,"min":92,"max":102},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"RBBB","q_waves":"Inferior"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Control of the heart failure may well cause the extrasystoles to disappear; the  extrasystoles should not be treated with antiarrhythmic drugs. The presence of  multifocal extrasystoles should alert you to consider electrolyte abnormalities and  digoxin toxicity."},"qrs_morph":{"hypertrophy":"None","bbb":"RBBB","q_waves":"Inferior"}}'::jsonb WHERE image_url LIKE '%case_138.png' OR image_url LIKE '%case_138.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded in the A & E department from a 25-year-old man with severe chest pain. No physical abnormalities had been detected, but having seen the ECG what would you look for and what would you do?","ecg_shows":"•\tSinus rhythm, rate 105/min •\tNormal axis •\tNormal QRS complexes •\tRaised ST segments in leads I–III, VF, V4–V6","clinical_interpretation":"The raised ST segments in leads I and V4 follow S waves, and are therefore ‘high  take-off’ and of no significance. The ST segment elevation elsewhere could indicate  an acute infarction, but since the change is so widespread, pericarditis seems more  probable.","what_to_do":"In a 25-year-old, pericarditis is a much more likely diagnosis than infarction, and  thrombolysis must be avoided. The diagnosis is made by lying the patient flat, when  a pericardial rub will become much easier to hear. Echocardiography will show a  pericardial effusion if one is present.","summary":"Widespread ST segment elevation, suggesting pericarditis.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":105,"min":100,"max":110},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Elevation","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"In a 25-year-old, pericarditis is a much more likely diagnosis than infarction, and  thrombolysis must be avoided. The diagnosis is made by lying the patient flat, when  a pericardial rub will become much easier to hear. Echocardiography will show a  pericardial effusion if one is present."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_139.png' OR image_url LIKE '%case_139.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and chest X-ray were recorded from a 70-year-old man who complained of breathlessness. What abnormalities do they show and what is the most likely diagnosis? X-ray reproduced with permission from Corne J & Pointon K (eds), 100 Chest X-Ray Problems, Elsevier, 2007","ecg_shows":"•\tSinus rhythm, rate 102/min •\tPeaked P waves, best seen in leads V1–V2 •\tRight axis deviation (deep S waves in lead I) •\tRSR1 pattern with normal QRS complex duration in lead V1 (partial right  bundle branch block (RBBB)) •\tDeep S waves in lead V6, with no left ventricular pattern","clinical_interpretation":"Peaked P waves suggest right atrial hypertrophy. The partial RBBB pattern is not  significant. Right axis deviation may be seen in tall, thin people with normal hearts,  but with the deep S waves in lead V6 it suggests right ventricular hypertrophy. The  lack of development of a left ventricular pattern in the V leads (i.e. deep S waves  persisting into lead V6) results from the right ventricle occupying most of the pre­ cordium. This is sometimes called ‘clockwise rotation’ (looking at the heart from  below) and is characteristic of chronic lung disease.","what_to_do":"Lung function tests will be more helpful than echocardiography.","summary":"Right atrial hypertrophy and chronic obstructive pulmonary disease.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":102,"min":96,"max":108},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Peaked (Pulmonale)","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"RVH","bbb":"RBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Lung function tests will be more helpful than echocardiography."},"qrs_morph":{"hypertrophy":"RVH","bbb":"RBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_140.png' OR image_url LIKE '%case_140.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 15-year-old boy who collapsed while playing football. His brother had died suddenly. What does the ECG show and what clinical possibilities should be considered?","ecg_shows":"•\tSinus rhythm, rate 91/min •\tNormal PR interval •\tNormal axis •\tNormal QRS complexes •\tProlonged QT interval (QT = 492 ms; QTc = 598 ms) •\tInverted T waves in leads V2–V5","clinical_interpretation":"This is clearly a very abnormal ECG, with a markedly prolonged QT interval and  abnormal T waves.","what_to_do":"The family history suggests that this may well be an example of one of the congenital  forms of prolonged QT interval: the Jervell–Lange–Nielson syndrome or the  Romano–Ward syndrome. These are characterized by episodes of loss of conscious­ ness in children, often at times of increased sympathetic nervous system activity,  and beta-blockers are the immediate form of treatment. The insertion of a perma­ nent defibrillator may be necessary. Prolonged QT interval syndrome is also associ­ ated with antiarrhythmic drugs (quinidine, procainamide, disopyramide, amiodarone  and sotalol) and with other drugs such as the tricyclic antidepressants and erythro­ mycin. Electrolyte abnormalities (low potassium, magnesium or calcium levels) also  prolong the QT interval.","summary":"Marked prolongation of the QT interval – long QT syndrome.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":91,"min":85,"max":95},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":500,"qt_category":"Prolonged","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The family history suggests that this may well be an example of one of the congenital  forms of prolonged QT interval: the Jervell–Lange–Nielson syndrome or the  Romano–Ward syndrome. These are characterized by episodes of loss of conscious­ ness in children, often at times of increased sympathetic nervous system activity,  and beta-blockers are the immediate form of treatment. The insertion of a perma­ nent defibrillator may be necessary. Prolonged QT interval syndrome is also associ­ ated with antiarrhythmic drugs (quinidine, procainamide, disopyramide, amiodarone  and sotalol) and with other drugs such as the tricyclic antidepressants and erythro­ mycin. Electrolyte abnormalities (low potassium, magnesium or calcium levels) also  prolong the QT interval."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_141.png' OR image_url LIKE '%case_141.png';
UPDATE ecg_cases SET findings_json = '{"history":"The house officer from the geriatric ward is puzzled by this ECG and requests your help. What questions would you ask him?","ecg_shows":"•\tSinus rhythm, rate 100/min •\tSlow rhythmic waves, the baseline in some ways resembling atrial flutter, but  slower and coarser •\tShort PR intervals •\tSlurred upstroke of the QRS complexes, particularly in lead I •\tT wave inversion in the anterior leads","clinical_interpretation":"The slow rhythmic variation is due to muscle tremor, and is not cardiac in origin.  The short PR intervals, slurred upstroke of the QRS complexes and inverted T waves  are due to the Wolff–Parkinson–White (WPW) syndrome – the dominant R waves  in the chest leads indicating type A.","what_to_do":"Ask if the patient has Parkinson’s disease: a Parkinsonian tremor would explain the  baseline variation. Does the patient give a history of palpitations or syncope? This  would be the only significant problem that the WPW syndrome might cause in an  elderly patient.","summary":"Muscle artefact, possibly Parkinson’s disease; the WPW syndrome type A.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":100,"min":95,"max":105},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"Ask if the patient has Parkinson’s disease: a Parkinsonian tremor would explain the  baseline variation. Does the patient give a history of palpitations or syncope? This  would be the only significant problem that the WPW syndrome might cause in an  elderly patient."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_142.png' OR image_url LIKE '%case_142.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old woman, who had been treated for depression for several years, was admitted to hospital as an emergency following deliberate self-harm involving a small number of aspirin tablets. There were no abnormalities on examination but this was her ECG. Does it worry you?","ecg_shows":"•\tSinus rhythm, rate 50/min •\tNormal axis •\tNormal QRS complexes •\tT wave inversion in leads I, VL, V4–V6","clinical_interpretation":"Anterolateral T wave inversion is most commonly due to ischaemia, but this seems  unlikely in a young woman with no evidence of heart disease. A cardiomyopathy  would be another possibility, but repolarization (T wave) abnormalities can be  caused by lithium therapy.","what_to_do":"As always when a diagnosis is not clear, find out what drugs the patient is taking.  This patient was taking lithium, and exercise testing and echocardiography showed  no evidence of heart disease.","summary":"Anterolateral T wave inversion due to lithium therapy.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":50,"min":45,"max":55},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Routine","notes":"As always when a diagnosis is not clear, find out what drugs the patient is taking.  This patient was taking lithium, and exercise testing and echocardiography showed  no evidence of heart disease."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_143.png' OR image_url LIKE '%case_143.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 40-year-old man who was admitted to hospital after collapsing in a supermarket. By the time he was seen he was well, and there were no abnormal physical signs. Would you pass this ECG as normal?","ecg_shows":"•\tSinus rhythm, rate 70/min •\tNormal PR interval and QRS complex duration •\tNormal axis •\tQRS complexes in leads V1–V2 show an RSR1 pattern •\tST segments elevated, and downward-sloping, in leads V1–V2","clinical_interpretation":"This is not a normal ECG. The appearances in leads V1–V2 are characteristic of the  Brugada syndrome.","what_to_do":"The Brugada syndrome involves a genetic abnormality that alters sodium transport  in the myocardium, and predisposes to ventricular tachycardia and fibrillation. This  patient’s collapse may well have been due to an arrhythmia. The syndrome is often  familial. The ECG changes are not constant, and on the day after admission this  patient’s ECG was perfectly normal. The ECG changes can be induced, and vent­ ricular tachycardia caused, by antiarrhythmic drugs. The only treatment is an  implanted defibrillator.","summary":"The Brugada syndrome.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":70,"min":65,"max":75},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Elevation","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"The Brugada syndrome involves a genetic abnormality that alters sodium transport  in the myocardium, and predisposes to ventricular tachycardia and fibrillation. This  patient’s collapse may well have been due to an arrhythmia. The syndrome is often  familial. The ECG changes are not constant, and on the day after admission this  patient’s ECG was perfectly normal. The ECG changes can be induced, and vent­ ricular tachycardia caused, by antiarrhythmic drugs. The only treatment is an  implanted defibrillator."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_144.png' OR image_url LIKE '%case_144.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG was recorded from a 35-year-old man who had no symptoms, but who had been found at a routine examination to have a blood pressure of 180/105. An enlarged part of the chest X-ray is also shown. What do the ECG and X-ray show and what action would you suggest?","ecg_shows":"•\tSinus rhythm, rate 50/min •\tVery short PR interval •\tNormal axis •\tSlurred upstroke to QRS complexes – delta wave •\tQRS complex duration prolonged (200 ms) •\tVery tall QRS complexes in the lateral leads •\tInverted T waves in leads I–III, VF, V5–V6","clinical_interpretation":"The ECG shows an example of the Wolff–Parkinson–White (WPW) syndrome type  B. In a patient with high blood pressure the tall QRS complexes and inverted T waves  in the lateral leads would raise the possibility of left ventricular hypertrophy.  However, the changes here are too gross for that, and they are compatible with this  pre-excitation syndrome. The rib notching shows that the high blood pressure is due  to coarctation of the aorta, which is completely unrelated to the WPW syndrome.","what_to_do":"If the patient has no symptoms to suggest a paroxysmal tachycardia, no further  action is necessary – many patients with an ECG consistent with a pre-excitation  syndrome never have an episode of tachycardia. The chance finding of an unrelated  coarctation of the aorta is more important, and surgical correction of this must be  considered. The chest X-ray shows rib notching  (arrowed), due to collaterals that have  developed because of a coarctation of  the aorta.","summary":"The WPW syndrome type B, and an unrelated coarctation of the aorta.","stars":3,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":50,"min":45,"max":55},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"If the patient has no symptoms to suggest a paroxysmal tachycardia, no further  action is necessary – many patients with an ECG consistent with a pre-excitation  syndrome never have an episode of tachycardia. The chance finding of an unrelated  coarctation of the aorta is more important, and surgical correction of this must be  considered. The chest X-ray shows rib notching  (arrowed), due to collaterals that have  developed because of a coarctation of  the aorta."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_145.png' OR image_url LIKE '%case_145.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 30-year-old woman complains of episodes of palpitations associated with dizziness and breathlessness. These begin and stop suddenly. She has had them for many years, but they are becoming more frequent and more severe. The upper ECG was recorded at rest; the lower ECG is part of an ambulatory record, during which she had a typical attack. What do these ECGs show and what would you do?","ecg_shows":"","clinical_interpretation":"This is the Wolff–Parkinson–White (WPW) syndrome,  involving a short PR interval and a widened QRS complex.  This pattern, with a dominant R wave in lead V1 and where  there is a left-sided accessory pathway, is called ‘type A’. It  can easily be mistaken for right ventricular hypertrophy.  The patient’s palpitations are due to atrial fibrillation; an  irregular broad complex tachycardia is characteristic of  atrial fibrillation in the WPW syndrome.","what_to_do":"Atrial fibrillation in association with the WPW syndrome  is extremely dangerous. The patient needs an immediate  electrophysiological study with a view to ablation of  the accessory pathway. An ECG was recorded after the  ablation (see right – leads V4–V6 shown): the PR interval  is now normal and there is no widening of the QRS  complex.","summary":"The WPW syndrome type A, with paroxysmal atrial fibrillation.","stars":2,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":180,"min":160,"max":200},"conduction":{"pr_interval":100,"pr_category":"Short","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Atrial fibrillation in association with the WPW syndrome  is extremely dangerous. The patient needs an immediate  electrophysiological study with a view to ablation of  the accessory pathway. An ECG was recorded after the  ablation (see right – leads V4–V6 shown): the PR interval  is now normal and there is no widening of the QRS  complex."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_146.png' OR image_url LIKE '%case_146.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old man, who had had exertional chest pain for some months, was seen in the A & E department with persistent central chest pain which had commenced 1 h earlier. These are his ECGs. What does the upper ECG show and what would you do? The lower ECG shows what happened when an exercise test was performed.","ecg_shows":"•\tSudden onset of ventricular fibrillation","clinical_interpretation":"The ‘splintered’ QRS complex in the inferior leads is probably of no significance.  The T wave inversion in the inferior and lateral leads suggests a non-ST segment  elevation myocardial infarction (NSTEMI).","what_to_do":"This patient clearly has an acute coronary syndrome. Thrombolysis is not indicated.  Pain relief is essential. He needs aspirin and clopidogrel, and a glyocoprotein  IIb/IIIa inhibitor if angiography is contemplated. He also needs a beta-blocker and  nitrates (intravenous or buccal). The ECG should be recorded every half-hour to  see if ST segment elevation appears. The plasma troponin level should be measured  12 h after the onset of pain. The patient may well need early coronary angiography  with a view to coronary intervention (percutaneous coronary intervention (PCI) or  coronary artery bypass graft (CABG)). Exercise testing is commonly performed  before the patient is discharged from hospital in an attempt to prioritize those who  need an angiogram urgently. Exercise test The lower ECG, recorded in stage 2 of the Bruce protocol, after 4 min and 41 s,  shows: •\tSudden onset of ventricular fibrillation What to do Immediate resuscitation, and early coronary angiography as soon as the patient is  stable. Above all, remember that exercise testing is not totally free of risk.","summary":"Inferolateral NSTEMI; ventricular fibrillation during exercise testing.","stars":1,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":75,"min":70,"max":80},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Normal","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"T Wave Inversion","t_wave":"Inverted"},"management":{"urgency":"Emergency","notes":"This patient clearly has an acute coronary syndrome. Thrombolysis is not indicated.  Pain relief is essential. He needs aspirin and clopidogrel, and a glyocoprotein  IIb/IIIa inhibitor if angiography is contemplated. He also needs a beta-blocker and  nitrates (intravenous or buccal). The ECG should be recorded every half-hour to  see if ST segment elevation appears. The plasma troponin level should be measured  12 h after the onset of pain. The patient may well need early coronary angiography  with a view to coronary intervention (percutaneous coronary intervention (PCI) or  coronary artery bypass graft (CABG)). Exercise testing is commonly performed  before the patient is discharged from hospital in an attempt to prioritize those who  need an angiogram urgently. Exercise test The lower ECG, recorded in stage 2 of the Bruce protocol, after 4 min and 41 s,  shows: •\tSudden onset of ventricular fibrillation What to do Immediate resuscitation, and early coronary angiography as soon as the patient is  stable. Above all, remember that exercise testing is not totally free of risk."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_147.png' OR image_url LIKE '%case_147.png';
UPDATE ecg_cases SET findings_json = '{"history":"An 80-year-old man was admitted to hospital because of a sudden onset of palpitations associated with breathlessness. He had congestive cardiac failure and a heart murmur suggestive of aortic regurgitation. What do this ECG and the chest X-ray show and how would you treat him?","ecg_shows":"•\tBroad complex tachycardia •\tIrregular rhythm, rate 130–200/min •\tNo clear P waves but irregular baseline, best seen in lead VL •\tQRS complex duration 160 ms, with ‘M’ pattern in lead V6, indicating left  bundle branch block (LBBB)","clinical_interpretation":"The marked irregularity of rhythm, coupled with the irregular baseline glimpsed in  one beat in lead VL, shows that this is atrial fibrillation with LBBB.","what_to_do":"Aortic valve disease is commonly associated with LBBB. An echocardiogram is  needed, to ensure that there is no significant aortic stenosis – in which case vasodila­ tors must be used with extreme caution. The heart failure can be treated with  diuretics, and digoxin will control the ventricular rate. Even at the age of 80 years,  aortic valve replacement might be considered. The chest X-ray shows left ven­ tricular enlargement with dila­ tation of the ascending aorta.  There is calcification in the  aortic wall (arrowed). These  changes suggest aortic regurgi­ tation due to old syphilitic  aortitis.","summary":"Atrial fibrillation with LBBB; aortic regurgitation due to syphilitic aortitis.","stars":3,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":160,"min":130,"max":200},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":140,"qrs_category":"Prolonged","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Normal"},"management":{"urgency":"Urgent","notes":"Aortic valve disease is commonly associated with LBBB. An echocardiogram is  needed, to ensure that there is no significant aortic stenosis – in which case vasodila­ tors must be used with extreme caution. The heart failure can be treated with  diuretics, and digoxin will control the ventricular rate. Even at the age of 80 years,  aortic valve replacement might be considered. The chest X-ray shows left ven­ tricular enlargement with dila­ tation of the ascending aorta.  There is calcification in the  aortic wall (arrowed). These  changes suggest aortic regurgi­ tation due to old syphilitic  aortitis."},"qrs_morph":{"hypertrophy":"None","bbb":"LBBB","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_148.png' OR image_url LIKE '%case_148.png';
UPDATE ecg_cases SET findings_json = '{"history":"This ECG and chest X-ray were recorded from a 17-year-old girl who was breathless, had marked ankle swelling with signs of right heart failure, and who had been known to have a heart murmur since birth. She was acyanotic. What ECG abnormalities can you identify, and can you suggest a diagnosis?","ecg_shows":"•\tSinus rhythm, rate 81/min •\tMarkedly peaked P waves (best seen in leads II, V1) •\tNormal axis •\tDominant R wave in lead V1","clinical_interpretation":"The ECG shows right atrial and right ventricular hypertrophy.","what_to_do":"Right atrial hypertrophy is seen with pulmonary hypertension of any cause, tricus­ pid stenosis, and Ebstein’s anomaly. Right ventricular hypertrophy is seen with  pulmonary stenosis and pulmonary hypertension. These conditions can all be diag­ nosed by echocardiography. This patient had pulmonary stenosis.","summary":"Right atrial and right ventricular hypertrophy.","stars":2,"rhythm":{"regularity":"Regular","sinus":true,"conduction_ratio":"1:1","p_qrs_relation":"1:1","sa_block":"None"},"rate":{"target":81,"min":76,"max":86},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Right Deviation","deviation":"Right Deviation"},"p_wave":{"morphology":"Peaked (Pulmonale)","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"None","t_wave":"Inverted"},"management":{"urgency":"Urgent","notes":"Right atrial hypertrophy is seen with pulmonary hypertension of any cause, tricus­ pid stenosis, and Ebstein’s anomaly. Right ventricular hypertrophy is seen with  pulmonary stenosis and pulmonary hypertension. These conditions can all be diag­ nosed by echocardiography. This patient had pulmonary stenosis."},"qrs_morph":{"hypertrophy":"RVH","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_149.png' OR image_url LIKE '%case_149.png';
UPDATE ecg_cases SET findings_json = '{"history":"A 50-year-old woman came to the A & E department because of the sudden onset of palpitations and severe breathlessness. What abnormalities do the ECG and chest X-rays show, and what condition might be responsible? The X-ray on the right shows an enlargement of a penetrated view of the right heart border.","ecg_shows":"•\tAtrial fibrillation •\tNormal axis •\tIrregular QRS complexes with a  ventricular rate of up to 200/min •\tOtherwise normal QRS complexes, apart  from an RSR1 pattern in lead VF •\tST segments depressed in leads V4–V6,  suggesting ischaemia •\tNormal T waves","clinical_interpretation":"Atrial fibrillation with an uncontrolled ventricular rate. The ischaemic changes in  leads V4 and V5 are probably related to the heart rate.","what_to_do":"Ischaemia may have been the cause of the atrial fibrillation, or the rapid ventricular  rate itself may be responsible for the ischaemic changes. Ischaemia is not a likely  primary diagnosis in a 50-year-old woman, and the things to think about are rheu­ matic heart disease (particularly with mitral stenosis), thyrotoxicosis, alcoholism,  and other forms of cardiomyopathy. Immediate treatment of the heart failure with  diuretics may be necessary, but the ventricular rate is best controlled by digoxin,  which can be given intravenously if necessary. DC cardioversion may be necessary  if the patient is in severe heart failure. Remember that a patient with atrial fibril­ lation probably needs anticoagulants on a long-term basis. Echocardiography con­ firmed that this patient had mitral stenosis.","summary":"Atrial fibrillation with a rapid ventricular rate and ischaemic changes,  in a patient with mitral stenosis.","stars":4,"rhythm":{"regularity":"Irregularly Irregular","sinus":false,"conduction_ratio":"Variable","p_qrs_relation":"Variable","sa_block":"None"},"rate":{"target":180,"min":150,"max":200},"conduction":{"pr_interval":160,"pr_category":"Normal","qrs_duration":90,"qrs_category":"Normal","qt_interval":400,"qt_category":"Normal","av_block":"None","sa_block":"None"},"axis":{"quadrant":"Normal","deviation":"Normal"},"p_wave":{"morphology":"Absent","atrial_enlargement":"None","enlargement":"None"},"qrs":{"hypertrophy":"None","bbb":"None","q_waves":"None"},"st_t":{"ischemia":"ST Depression","t_wave":"Normal"},"management":{"urgency":"Emergency","notes":"Ischaemia may have been the cause of the atrial fibrillation, or the rapid ventricular  rate itself may be responsible for the ischaemic changes. Ischaemia is not a likely  primary diagnosis in a 50-year-old woman, and the things to think about are rheu­ matic heart disease (particularly with mitral stenosis), thyrotoxicosis, alcoholism,  and other forms of cardiomyopathy. Immediate treatment of the heart failure with  diuretics may be necessary, but the ventricular rate is best controlled by digoxin,  which can be given intravenously if necessary. DC cardioversion may be necessary  if the patient is in severe heart failure. Remember that a patient with atrial fibril­ lation probably needs anticoagulants on a long-term basis. Echocardiography con­ firmed that this patient had mitral stenosis."},"qrs_morph":{"hypertrophy":"None","bbb":"None","q_waves":"None"}}'::jsonb WHERE image_url LIKE '%case_150.png' OR image_url LIKE '%case_150.png';

COMMIT;
